function OnPlayerDefeated(aiBrain)

    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'OnPlayerDefeated'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        if bDebugMessages == true then LOG(sFunctionRef..': Player has been defeated, brain='..aiBrain.Nickname..'; Was this an AiBotAI='..tostring(aiBrain.AiBotAI or false)..'; ScenarioInfo.Options.Share='..(ScenarioInfo.Options.Share or 'nil')) end
        local iTeam = aiBrain.AiBotTeam
        aiBrain.AiBotIsDefeated = true

        AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastTeammateDeath] = GetGameTimeSeconds()

        --Was it an AiBotAI?
        if aiBrain.AiBotAI and (AiBotOrders.bDontConsiderCombinedArmy or aiBrain.BrainType == 'AI') then
            --Give resources to teammates
            local bHaveTeammates = false
            local oFirstAiBotBrain
            local oFirstOtherBrain
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) == false then
                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
                    if not(oBrain == aiBrain) and not(oBrain.AiBotIsDefeated) and not(oBrain:IsDefeated()) then
                        bHaveTeammates = true
                        if not(oFirstAiBotBrain) then
                            if oBrain.AiBotAI then oFirstAiBotBrain = oBrain
                            elseif not(oFirstOtherBrain) then oFirstOtherBrain = oBrain
                            end
                        end
                    end
                end
            end
            if bHaveTeammates then
                ForkThread(AiBotTeam.GiveAllResourcesToAllies, aiBrain)
                AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastAiBotPlayerDefeat] = GetGameTimeSeconds()
                if oFirstAiBotBrain or oFirstOtherBrain then
                    local oBrainToTransfer = oFirstAiBotBrain or oFirstOtherBrain
                    local tFriendlyUnits = aiBrain:GetListOfUnits(categories.ALLUNITS - categories.UNSELECTABLE - categories.COMMAND, false, true)
                    if AiBotUtilities.IsTableEmpty(tFriendlyUnits) == false then
                        ForkThread(AiBotTeam.TransferUnitsToPlayer, tFriendlyUnits, oBrainToTransfer:GetArmyIndex(), false)
                    end
                end
            else
                --Message on death - Will cover as part of AiBotChat function
            end
        end

        --Was it a team with omni vision, that still has AiBot on the team?
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision] and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
            local bStillHaveOmni = false
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
                if not(oBrain.AiBotIsDefeated) and AiBotConditions.DoesBrainHaveOmniVision(oBrain) then
                    bStillHaveOmni = true
                    break
                end
            end
            if not(bStillHaveOmni) then
                AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision] = false --So we can do forked thread without worrying about calling multiple times at once
                ForkThread(AiBotTeam.TeamHasLostAIxOmniVision, iTeam) --Just in case an error occurs
            end
        end

        --Update tables tracking the various brains
        ForkThread(AiBotTeam.RefreshActiveBrainListForBrainDeath, aiBrain)
        --if the base will have been destroyed, or there isn't a base anyway, then rerecord positions
        if not(ScenarioInfo.Options.Share == 'FullShare') or aiBrain:GetCurrentUnits(categories.ALLUNITS - categories.INSIGNIFICANTUNIT) <= 2 then
            ForkThread(AiBotMap.ReassessPositionsForPlayerDeath, aiBrain)
        end
        ForkThread(AiBotChat.ConsiderEndOfGameMessage, aiBrain)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnACUKilled(oUnit)
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'OnACUKilled'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        if bDebugMessages == true then
            local oKilledBrain = oUnit:GetAIBrain()
            if oKilledBrain then
                LOG(sFunctionRef..': ACU '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' has just died, and its brain is '..oKilledBrain.Nickname..'; ScenarioInfo.Options.Victory='..(ScenarioInfo.Options.Victory or 'nil')..'; Cur ACU and SACU units='..oUnit:GetAIBrain():GetCurrentUnits(categories.COMMAND + categories.SUBCOMMANDER))
            else
                LOG(sFunctionRef..': ACU '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' has just died, and it doesnt have a brain')
            end
        end
        local oKilledBrain = oUnit:GetAIBrain()
        local bDefeated = false

        if ScenarioInfo.Options.Victory == "demoralization" then
            bDefeated = true
        elseif oKilledBrain and not(oKilledBrain.AiBotIsDefeated) and ScenarioInfo.Options.Victory == 'decapitation' then
            --In FAF this means all teammate ACUs; outside of FAF means ACUs and SACUs of that player
            if AiBotUtilities.bFAFActive then
                bDefeated = true
                if EntityCategoryContains(categories.SUBCOMMANDER, oUnit.UnitId) and oKilledBrain:GetCurrentUnits(categories.COMMAND) > 0 then
                    bDefeated = false
                    if bDebugMessages == true then LOG(sFunctionRef..': We still have an ACU so not defeated yet') end
                else
                    local iTeam = oKilledBrain.AiBotTeam
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of friendly brains on our team empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]))) end
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) == false then
                        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering teammate '..oBrain.Nickname..'; IsDefeated='..tostring(oBrain:IsDefeated())..'; Cur ACUs owned='..oBrain:GetCurrentUnits(categories.COMMAND)) end
                            if not(oBrain == oKilledBrain) and oBrain.IsDefeated and not(oBrain:IsDefeated()) then
                                if oBrain:GetCurrentUnits(categories.COMMAND) > 0 then
                                    bDefeated = false
                                    break
                                end
                            end
                        end
                    end
                end
            else
                local tCurUnits = oKilledBrain:GetListOfUnits(categories.COMMAND + categories.SUBCOMMANDER, false, true)
                if AiBotUtilities.IsTableEmpty(tCurUnits) then
                    bDefeated = true
                else
                    bDefeated = true
                    for iOwnedUnit, oOwnedUnit in tCurUnits do
                        if not(oOwnedUnit == oUnit) and not(oOwnedUnit.Dead) and not(oUnit['AiBotDead']) then
                            bDefeated = false
                            break
                        end
                    end
                end
            end
        end
        --Update the table of enemy ACUs for every team
        for iCurTeam = 1, AiBotTeam.iTotalTeamCount do
            if not(iCurTeam == oKilledBrain.AiBotTeam) then
                if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iCurTeam][AiBotTeam.reftEnemyACUs]) then
                    --Do nothing (function will have cleansed the table of old entries already)
                end
            elseif oKilledBrain.AiBotAI then
                if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iCurTeam][AiBotTeam.reftAiBotACUs]) then
                    --Do nothing (function will have cleansed the table of old entries already)
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Will consider calling OnPlayerDefeated, .AiBotIsDefeated='..tostring(oUnit:GetAIBrain().AiBotIsDefeated or false)..'; bDefeated='..tostring(bDefeated)) end
        if bDefeated then
            if oUnit:GetAIBrain() then
                if not(oUnit:GetAIBrain().AiBotIsDefeated) then
                    OnPlayerDefeated(oUnit:GetAIBrain())
                end
            else
                --Possibility that we have already recorded the unit death, so wait 1 second and then if any brains show as defeated but not AiBotDefeated then run the function
                ForkThread(AiBotTeam.DelayedPlayerDeathCheck)
            end
        else
            local aiBrain = oUnit:GetAIBrain()
            local iStartPlateauOrZero, iStartZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotMap.GetPlayerStartPosition(aiBrain))
            local tLZOrWZData, tLZOrWZTeamData
            local iTeam = aiBrain.AiBotTeam
            if iStartPlateauOrZero == 0 then
                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartZone]][AiBotMap.subrefPondWaterZones][iStartZone]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
            else
                tLZOrWZData = AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iStartZone]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
            end
            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData) == false then
                ForkThread(AiBotMap.DelayedConsiderationOfWhetherToIgnoreFriendlyBase, tLZOrWZData, tLZOrWZTeamData, aiBrain.AiBotTeam, iStartPlateauOrZero, iStartZone, AiBotLand.iTicksPerLandCycle * 0.1 + 0.1)
            end
        end

        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnKilled(oUnitKilled, instigator, type, overkillRatio)
    --WARNING: Doesnt trigger when an ACU is killed
    --Will make sure the OnUnitDeath event is called, i.e. this function should only be used where we only want something to run when we killed something, or an enemy killed something of ours

    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'OnKilled'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        if bDebugMessages == true then LOG(sFunctionRef..': event triggered for unit '..(oUnitKilled.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitKilled) or 'nil')..' owned by brain '..oUnitKilled:GetAIBrain().Nickname..'; Have already run='..tostring(oUnitKilled[refbAlreadyRunUnitKilled] or false)) end

        if not(oUnitKilled[refbAlreadyRunUnitKilled]) then
            oUnitKilled[refbAlreadyRunUnitKilled] = true

            if bDebugMessages == true then LOG(sFunctionRef..': oUnitKilled='..oUnitKilled.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitKilled)..'; GameTime='..GetGameTimeSeconds()) end
            if oUnitKilled.GetAIBrain then
                OnUnitDeath(oUnitKilled) --Ensure this is run when a unit dies

                --were we killed by something?
                local oKillerUnit
                local oKillerBrain

                if instigator and not(instigator:BeenDestroyed()) and not(instigator.Dead) then
                    if instigator.GetLauncher and instigator:GetLauncher() then
                        oKillerUnit = instigator:GetLauncher()
                    elseif instigator.DamageData and not(instigator.unit) and not(instigator.UnitId) then
                        --Can get errors for artillery shells when running IsProjectile
                    elseif IsProjectile(instigator) or IsCollisionBeam(instigator) then
                        if instigator.unit then
                            oKillerUnit = instigator.unit
                        end
                    elseif IsUnit(instigator) then
                        oKillerUnit = instigator
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Have an instigator, checking if have valid killer unit. Is valid='..tostring(AiBotUnitInfo.IsUnitValid(oKillerUnit))) end
                    if oKillerUnit and oKillerUnit.GetAIBrain then
                        oKillerBrain = oKillerUnit:GetAIBrain()
                        if bDebugMessages == true then LOG(sFunctionRef..': oKillerUnit='..oKillerUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oKillerUnit)..'; oKillerBrain='..oKillerBrain.Nickname..'; Killer unit assigned plateau+zone (for killed unit brain team)='..repru(oKillerUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][oUnitKilled:GetAIBrain().AiBotTeam])..'; Assigned water zone='..(oKillerUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][oUnitKilled:GetAIBrain().AiBotTeam] or 'nil')) end

                        --Non-AiBot specific killer logic:

                        if EntityCategoryContains(AiBotUnitInfo.refCategoryBomber * categories.TECH3, oKillerUnit.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryT3Power + AiBotUnitInfo.refCategoryT2Power, oKillerUnit.UnitId) then
                            ForkThread(ConsiderRecordingStratBomberToSuicideInto, oKillerUnit, true)
                        end

                        --Non-AiBot specific unit (i.e. applies to both non-AiBot killers and non-AiBot killed units)
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryAirFactory, oUnitKilled.UnitId) then
                            AiBotMap.ConsiderUpdatingPlayerStartPositionForDestroyedFactory(oKillerBrain.AiBotTeam, oUnitKilled, oUnitKilled:GetAIBrain())
                        end

                        --Logic specific to where AiBot unit is killed:
                        if oUnitKilled:GetAIBrain().AiBotAI then
                            local iTeam = oUnitKilled:GetAIBrain().AiBotTeam
                            --Tracking for certain units that are killed - T2 arti and gunships:
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oKillerUnit.UnitId) then AiBotLand.ConsiderIfHaveEnemyFirebase(iTeam, oKillerUnit) end
                            --Track non-experimental air units
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryBomber - AiBotUnitInfo.refCategoryTorpBomber - categories.EXPERIMENTAL, oUnitKilled.UnitId) then
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryBomber, oUnitKilled.UnitId) then
                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiBomberLosses] = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiBomberLosses] + AiBotUnitInfo.GetUnitMassCost(oUnitKilled)
                                else
                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] + AiBotUnitInfo.GetUnitMassCost(oUnitKilled)
                                    --Adjust gunship retreat logic if killed by a ground unit
                                    if oKillerUnit and AiBotAir.iBaseLowHealthThreshold < 0.75 and EntityCategoryContains(AiBotUnitInfo.refCategoryGroundAA, oKillerUnit.UnitId) and EntityCategoryContains(categories.TECH3, oUnitKilled.UnitId) then
                                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills] * 0.7 then
                                            AiBotAir.iBaseLowHealthThreshold = AiBotAir.iBaseLowHealthThreshold + 0.03
                                            AiBotAir.iProjectileLowHealthThreshold = AiBotAir.iProjectileLowHealthThreshold + 0.03
                                        else
                                            AiBotAir.iBaseLowHealthThreshold = AiBotAir.iBaseLowHealthThreshold + 0.02
                                            AiBotAir.iProjectileLowHealthThreshold = AiBotAir.iProjectileLowHealthThreshold + 0.02
                                        end
                                    end
                                end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oUnitKilled.UnitId) then
                                --If we died to enemy air unit then track
                                if oKillerUnit and EntityCategoryContains(AiBotUnitInfo.refCategoryAirNonScout, oKillerUnit.UnitId) then
                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiAirAALossesToAir] = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiAirAALossesToAir] + AiBotUnitInfo.GetUnitMassCost(oUnitKilled)
                                end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oUnitKilled.UnitId) and not(iTeam == oKillerBrain.AiBotTeam) then
                                if oKillerBrain.AiBotTeam then
                                    --I.e. we have an AiBot naval fac killed by a unit from another team
                                    local tWZData, tWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnitKilled:GetPosition(), true, iTeam)
                                    if tWZTeamData then tWZTeamData[AiBotMap.subrefWZFactoryDestroyedCount] = (tWZTeamData[AiBotMap.subrefWZFactoryDestroyedCount] or 0) + 1 end
                                end
                                --Consider changing core zone override flag if last land fac in zone died; we do air fac in the main factory logic
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandHQ, oUnitKilled.UnitId) and not(oKillerBrain == oUnitKilled:GetAIBrain()) then
                                local iPlateau = oUnitKilled[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
                                local iZone = oUnitKilled[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                                if iPlateau and iZone then
                                    local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iZone]
                                    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    if tLZTeamData[AiBotMap.subrefbCoreBaseOverride] or tLZTeamData[AiBotMap.subrefLZbCoreBase] then
                                        local bHaveConstructedHQInZone = false
                                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                            local toLandAndAirFacsInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandHQ + AiBotUnitInfo.refCategoryAirFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                            if AiBotUtilities.IsTableEmpty(toLandAndAirFacsInZone) == false then
                                                for iUnit, oUnit in toLandAndAirFacsInZone do
                                                    if not(oUnit.Dead) and not(oUnit == oUnitKilled) and oUnit:GetFractionComplete() == 1 then
                                                        bHaveConstructedHQInZone = true
                                                        break
                                                    end
                                                end
                                            end
                                        end
                                        if not(bHaveConstructedHQInZone) then
                                            ForkThread(AiBotEconomy.ConsiderChangingCoreBase, oUnitKilled:GetAIBrain(), iPlateau, iZone)
                                        end
                                    end
                                end
                            end
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oKillerUnit.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnitKilled.UnitId) then
                                local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnitKilled:GetPosition(), true, iTeam)
                                if tLZOrWZTeamData then tLZOrWZTeamData[AiBotMap.subrefiTimeOfLastBuildingDeathToTML] = GetGameTimeSeconds() end
                            end

                        end

                        --AiBot specific killer logic
                        if oKillerBrain.AiBotAI then
                            --Logic based on the category of the killer:
                            if EntityCategoryContains(AiBotUnitInfo.refCategorySatellite, instigator.UnitId) and AiBotUnitInfo.IsUnitValid(oKillerUnit) then
                                ForkThread(AiBotAir.NovaxCoreTargetLoop, oKillerBrain, instigator, true)
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oKillerUnit.UnitId) and not(type) and not(overkillRatio) and not(oKillerBrain.AiBotTeam == oUnitKilled:GetAIBrain().AiBotTeam) then
                                --We have reclaimed an enemy - if there arent many enemies in this zone then update the zone; also check for enemy targets within build range to reclaim
                                local tNearbyReclaimableEnemies = oKillerBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryReclaimable, oKillerUnit:GetPosition(), oKillerUnit:GetBlueprint().Economy.MaxBuildDistance, 'Enemy')
                                if bDebugMessages == true then LOG(sFunctionRef..': Is table of nearby reclaimable enemies empty='..tostring( AiBotUtilities.IsTableEmpty(tNearbyReclaimableEnemies))) end
                                local bNotGivenReclaimOrder = true
                                if AiBotUtilities.IsTableEmpty(tNearbyReclaimableEnemies) == false then
                                    for iPotentialEnemy, oPotentialEnemy in tNearbyReclaimableEnemies do
                                        if not(oPotentialEnemy == oUnitKilled) and AiBotUnitInfo.IsUnitValid(oPotentialEnemy) and oPotentialEnemy:GetHealth() > 0 then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will issue new reclaim order for oKillerUnit='..(oKillerUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oKillerUnit) or 'nil')..' owend by brain'..oKillerBrain.Nickname..' to target enemy unit '..(oPotentialEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oPotentialEnemy) or 'nil')..'; Time='..GetGameTimeSeconds()..'; Enemy unit health='..oPotentialEnemy:GetHealth()..'; Enemy unit brain owner='..oPotentialEnemy:GetAIBrain().Nickname) end

                                            ForkThread(AiBotOrders.IssueTrackedReclaim, oKillerUnit, oPotentialEnemy, false, 'FollowRec', false) --WHen tried doing but not via forked thread ended up with game crashing
                                            bNotGivenReclaimOrder = false
                                            break
                                        end
                                    end
                                end
                                if bNotGivenReclaimOrder then
                                    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnitKilled:GetPosition())
                                    if (iPlateauOrZero or 0) > 0 and (iLandOrWaterZone or 0) > 0 then
                                        local tLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][oKillerBrain.AiBotTeam]
                                        --if we reclaimed an enemy unit, then update units in that zone if arent many units left
                                        if not(tLZTeamData[AiBotMap.subrefTEnemyUnits][2]) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                            if bDebugMessages == true then LOG(sFunctionRef..': have just killed a unit so will update the position of all enemy units in the zone, iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; Time='..GetGameTimeSeconds()) end
                                            --UpdateUnitPositionsAndLandZone(aiBrain,   tUnits,                                 iTeam,              iRecordedPlateau, iRecordedLandZone, bUseLastKnownPosition, bAreAirUnits, tLZTeamData, bUpdateTimeOfLastEnemyPositionCheck, bAreEnemyUnits)
                                            AiBotLand.UpdateUnitPositionsAndLandZone(oKillerBrain, tLZTeamData[AiBotMap.subrefTEnemyUnits], oKillerBrain.AiBotTeam, iPlateauOrZero, iLandOrWaterZone, true,                   false,          tLZTeamData, true,                                  true)
                                        end
                                    end

                                end
                                --Gunship and strat bomber tracking (non-experimental)
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryBomber - AiBotUnitInfo.refCategoryTorpBomber - categories.EXPERIMENTAL, oKillerUnit.UnitId) then
                                local iTeam = oKillerBrain.AiBotTeam
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryBomber, oKillerUnit.UnitId) then
                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiT1ToT3BomberKills] = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiT1ToT3BomberKills] + AiBotUnitInfo.GetUnitMassCost(oKillerUnit)
                                else
                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills] = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills] + AiBotUnitInfo.GetUnitMassCost(oKillerUnit)
                                end
                                --AirAA tracking
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oKillerUnit.UnitId) then
                                local iTeam = oKillerBrain.AiBotTeam
                                AiBotTeam.tTeamData[iTeam][AiBotTeam.refiAirAAKills] = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiAirAAKills] + AiBotUnitInfo.GetUnitMassCost(oKillerUnit)
                            end

                            --Logic based on the category of the unit killed
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryT3Mex + AiBotUnitInfo.refCategoryT3Power + AiBotUnitInfo.refCategoryExperimentalLevel, oUnitKilled.UnitId) then
                                if AiBotOrders.bDontConsiderCombinedArmy or oKillerUnit.AiBotActive then
                                    --Scathis special message if killed by UEF
                                    if oKillerUnit and EntityCategoryContains(AiBotUnitInfo.refCategoryScathis, oUnitKilled.UnitId) and EntityCategoryContains(categories.UEF, oKillerUnit.UnitId) and oKillerBrain[AiBotChat.refiAssignedPersonality] == AiBotChat.refiFletcher then
                                        ForkThread(AiBotChat.SendMessage, oKillerBrain, 'UEFKilledScathis', LOC('<LOC X05_M02_050_010>[{i Fletcher}]: Scratch one Scathis. Fletcher out.'), 1, 600, false, true, 'X05_Fletcher_M02_03831', 'X05_VO')
                                        --Killed T3 arti or experimental arti and there are no other friendly T3/Exp arti units on that team
                                    elseif oKillerUnit and EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti, oUnitKilled.UnitId) and AiBotChat.IsTeamCoalition(oKillerBrain.AiBotTeam) and AiBotUtilities.IsTableEmpty(oUnitKilled:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti, oUnitKilled:GetPosition(), AiBotMap.iMapSize * 2, 'Ally')) then
                                        local bSendToTeam = false
                                        if math.random(1,2) == 1 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[oKillerBrain.AiBotTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) == false and table.getn(AiBotTeam.tTeamData[oKillerBrain.AiBotTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) >= 2 then bSendToTeam = true end
                                        --SendMessage(aiBrain, sMessageType,        sMessage,                                                                       iOptionalDelayBeforeSending, iOptionalTimeBetweenMessageType, bOnlySendToTeam, bWaitUntilHaveACU, sOptionalSoundCue, sOptionalSoundBank, oOptionalOnlyBrainToSendTo)
                                        AiBotChat.SendMessage(oKillerBrain, 'CoalKillArti', LOC('<LOC X01_M01_200_010>[{i HQ}]: That\'s the last of them -- all the artillery positions are down.'), 1,       600,                            bSendToTeam,          true,               'X01_HQ_M01_03631', 'X01_VO')
                                        --Dont trigger if killed via nuke
                                    elseif oKillerUnit and not(EntityCategoryContains(AiBotUnitInfo.refCategorySML, oKillerUnit.UnitId)) then
                                        --Check mod dist is far enoguh away from our core base that unlikely it has dealt lots of damage
                                        local bConsiderMessage = true
                                        if EntityCategoryContains(categories.MOBILE, oUnitKilled.UnitId) then
                                            bConsiderMessage = false
                                            local tUnitLZData, tUnitLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnitKilled:GetPosition(), true, oKillerBrain.AiBotTeam)
                                            if tUnitLZTeamData and tUnitLZTeamData[AiBotMap.refiModDistancePercent] >= 0.3 and not(tUnitLZTeamData[AiBotMap.subrefLZbCoreBase]) and ((oUnitKilled.VetExperience or oUnitKilled.Sync.totalMassKilled or 0) < 12000) then
                                                bConsiderMessage = true
                                            end
                                        end
                                        if bConsiderMessage then
                                            if (oUnitKilled.VetExperience or oUnitKilled.Sync.totalMassKilled or 0) < (oUnitKilled[AiBotUnitInfo.refiUnitMassCost] or 0) * 0.5 or EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryGameEnder, oUnitKilled.UnitId) then
                                                --If enemy is beating us on eco and units on our side of map then dont gloat
                                                if not(EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnitKilled.UnitId)) and AiBotTeam.tLandSubteamData[oKillerBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] > AiBotTeam.tLandSubteamData[oKillerBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] and AiBotConditions.GetEnemyTeamActualMassIncome(oKillerBrain.AiBotTeam) > 1.3 * AiBotTeam.tTeamData[oKillerBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossMass] / oKillerBrain[AiBotEconomy.refiBrainResourceMultiplier] then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': We still are losing so wont gloat') end
                                                else
                                                    if bDebugMessages == true then LOG(sFunctionRef..': About to call chat for valuable unit killed, oUnitKilled='..oUnitKilled.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitKilled)..', owned by brain '..oUnitKilled:GetAIBrain().Nickname..'; oKillerUnit='..oKillerUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oKillerUnit)..' owned by brain '..(oKillerBrain.Nickname or 'nil')) end
                                                    ForkThread(AiBotChat.JustKilledEnemyValuableUnit, oUnitKilled.UnitId, oUnitKilled:GetAIBrain(), oKillerBrain) --If dont do as forked thread then any error breaks the game
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                --Consider message if this was a significant unit
                if EntityCategoryContains(AiBotUnitInfo.refCategoryT3Mex + AiBotUnitInfo.refCategoryT3Power + AiBotUnitInfo.refCategoryExperimentalLevel + AiBotUnitInfo.refCategoryAllHQFactories * categories.TECH3, oUnitKilled.UnitId) then
                    if oUnitKilled:GetFractionComplete() == 1 or (EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnitKilled.UnitId) and oUnitKilled:GetFractionComplete() >= 0.6) then
                        local bConsideredNormalMessage = false
                        --Send distress message
                        if oUnitKilled:GetAIBrain().AiBotAI and (AiBotOrders.bDontConsiderCombinedArmy or oUnitKilled.AiBotActive) then
                            local tUnitLZData, tUnitLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnitKilled:GetPosition(), true, oUnitKilled:GetAIBrain().AiBotTeam)
                            --Was the unit in a mod dist of <=0.4 (so getting close to base or in base)?
                            if tUnitLZTeamData[AiBotMap.refiModDistancePercent] <= 0.4 and (tUnitLZTeamData[AiBotMap.refiModDistancePercent] <= 0.3 or not(EntityCategoryContains(AiBotUnitInfo.refCategoryMex + categories.MOBILE, oUnitKilled.UnitId))) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Just lost unit '..oUnitKilled.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitKilled)..', owned by brain'..oUnitKilled:GetAIBrain().Nickname..'; Mod dist='..(tUnitLZTeamData[AiBotMap.refiModDistancePercent] or 'nil')..'; oKillerUnit='..(oKillerUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oKillerUnit) or 'nil')..'; will send taunt if havent sent one recently, Time='..GetGameTimeSeconds()) end
                                ForkThread(AiBotChat.JustLostValuableUnit, oUnitKilled.UnitId, oUnitKilled:GetAIBrain(), oKillerBrain) --If dont do as forked thread then any error breaks the game
                                bConsideredNormalMessage = true
                            end
                        end
                        if not(bConsideredNormalMessage) and EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnitKilled.UnitId) then
                            --Special message if we have a hall personality AiBot teammate, and killer brain was UEF
                            if oKillerBrain and oKillerBrain:GetFactionIndex() == AiBotUnitInfo.refFactionUEF then
                                --Do we have hall as a teammate?
                                local iTeam = oKillerBrain.AiBotTeam
                                local bHaveHall = false
                                local oBrainToSendMessage
                                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
                                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                        if oBrain[AiBotChat.refiAssignedPersonality] == AiBotChat.refiHall and oBrain.BrainType == 'AI' and not(oBrain == oKillerBrain) then
                                            oBrainToSendMessage = oBrain
                                            break
                                        end
                                    end
                                end
                                if oBrainToSendMessage then
                                    ForkThread(AiBotChat.SendMessage, oBrainToSendMessage, 'HallCongrats', LOC('<LOC X01_M02_210_010>[{i Hall}]: Good work, Colonel. I\'m damn proud to have you in the UEF.'), 1, 10000, false, true, 'X01_Hall_M02_03658', 'X01_VO')
                                end
                            end
                        end
                    end
                end
            elseif bDebugMessages == true then LOG(sFunctionRef..': Unit killed doesnt have a brain')
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnPropDestroyed(oProp)
    --Confirmed manually this triggers e.g. if a bomber destroys a rock, and if a tree is reclaimed
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'OnPropDestroyed'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnYthothaDeath(oUnit)
    --Called when a ythotha (oUnit) is flagged as dying or being killed
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'OnYthothaDeath'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        local refbYthothaDeath = 'AiBotEventYthothaDeath'

        if not(oUnit[refbYthothaDeath]) then
            oUnit[refbYthothaDeath] = true
            local tStormPosition = {oUnit:GetPosition()[1], oUnit:GetPosition()[2], oUnit:GetPosition()[3]}
            local tNearbyUnits
            if bDebugMessages == true then LOG(sFunctionRef..': Ythotha has just died, will look for nearby units and tell them to run away') end
            local iTimeToRun
            local iSearchRange = 70 --at 50 distance a fatboy can end up dying to it
            local toAiBotEasyUnitsToRun
            for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
                tNearbyUnits = oBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileLand, tStormPosition, iSearchRange, 'Ally')
                if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
                    local bRunCurrentUnit
                    for iFriendlyUnit, oFriendlyUnit in tNearbyUnits do
                        if bDebugMessages == true then LOG(sFunctionRef..': oFriendlyUnit='..oFriendlyUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFriendlyUnit)..'; if we own it then will make it run away') end
                        if oFriendlyUnit:GetAIBrain() == oBrain then --Only do this for AiBot units
                            if AiBotUnitInfo.IsUnitValid(oFriendlyUnit, true) then
                                if oFriendlyUnit[AiBotUnitInfo.refbEasyBrain] then
                                    if EntityCategoryContains(categories.EXPERIMENTAL, oFriendlyUnit.UnitId) then
                                        if not(toAiBotEasyUnitsToRun) then toAiBotEasyUnitsToRun = {} end
                                        table.insert(toAiBotEasyUnitsToRun, oFriendlyUnit)
                                    end

                                else
                                    bRunCurrentUnit = true
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oFriendlyUnit.UnitId) and (oFriendlyUnit:IsUnitState('Building') or oFriendlyUnit:IsUnitState('Repairing')) and oFriendlyUnit:GetWorkProgress() >= 0.94 and (oFriendlyUnit:GetWorkProgress() >= 0.97 or oFriendlyUnit:GetFocusUnit().UnitId and EntityCategoryContains(AiBotUnitInfo.refCategoryAllShieldUnits + categories.MOBILE, oFriendlyUnit:GetFocusUnit().UnitId)) then
                                        bRunCurrentUnit = false
                                    end
                                    if bRunCurrentUnit then
                                        --Engineers that are assisting a near-complete shield or mobile unit - keep building
                                        iTimeToRun = math.min(32, math.max(10, 18 + (50 - AiBotUtilities.GetDistanceBetweenPositions(oFriendlyUnit:GetPosition(), tStormPosition) / (oFriendlyUnit:GetBlueprint().Physics.MaxSpeed or 1))))
                                        if bDebugMessages == true then LOG(sFunctionRef..': Telling friendly unit '..oFriendlyUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFriendlyUnit)..' to move away for 18s via moveawayfromtarget order') end
                                        ForkThread(AiBotMicro.MoveAwayFromTargetTemporarily, oFriendlyUnit, iTimeToRun, tStormPosition)
                                    end
                                end
                            end
                        end
                    end
                end
            end
            if toAiBotEasyUnitsToRun then
                for iUnit, oFriendlyUnit in toAiBotEasyUnitsToRun do
                    if not(oFriendlyUnit.Dead) and AiBotUtilities.GetDistanceBetweenPositions(oFriendlyUnit:GetPosition(), tStormPosition) <= 60 then --60 instead of 70 as want to be a bit worse
                        iTimeToRun = math.min(25, math.max(10, 18 + (50 - AiBotUtilities.GetDistanceBetweenPositions(oFriendlyUnit:GetPosition(), tStormPosition) / (oFriendlyUnit:GetBlueprint().Physics.MaxSpeed or 1))))
                        ForkThread(AiBotMicro.DelayedMoveAwayFromTarget, oFriendlyUnit, iTimeToRun, tStormPosition, math.random(300,500)/100)
                    end
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnUnitDeath(oUnit)
    --NOTE: This is called by the death of any unit of any player, so careful with what commands are given
        --Some callbacks line onkilled will call this as well to make sure it is run (since for some things like when an ACU is killed it doesnt trigger directly)
    if AiBotUtilities.bAiBotAIInGame and AiBotMap.bWaterZoneInitialCreation then --No point running on death logic for units at start of the game
        local sFunctionRef = 'OnUnitDeath'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



        if bDebugMessages == true then
            LOG(sFunctionRef..'Hook successful. oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; GameTime='..GetGameTimeSeconds()..'; oUnit[refbAlreadyRunUnitKilled]='..tostring(oUnit[refbAlreadyRunUnitKilled] or false)..'; oUnit[AiBotDead]='..tostring(oUnit['AiBotDead'] or false))
            if oUnit.GetAIBrain then LOG(sFunctionRef..': Unit owner='..oUnit:GetAIBrain().Nickname) end
        end
        --Is it an ACU?
        if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) or (ScenarioInfo.Options.Victory == 'decapitation' and EntityCategoryContains(categories.SUBCOMMANDER, oUnit.UnitId)) then
            OnACUKilled(oUnit)
        else
            if oUnit.CachePosition and (not(oUnit.UnitId) or not(EntityCategoryContains(categories.ALLUNITS - categories.INSIGNIFICANTUNIT, oUnit.UnitId))) then --Redundancy to check not dealing with a unit, not sure this will actually trigger as looks like wreck deaths are picked up by the prop logic above
                if bDebugMessages == true then
                    LOG(sFunctionRef..': Unit killed has a cache position, will draw in blue around it')
                    AiBotUtilities.DrawLocation(oUnit.CachePosition, nil, 1, 100, nil)
                end
                ForkThread(AiBotMap.RecordThatWeWantToUpdateReclaimAtLocation, oUnit.CachePosition, 0)
            else
                if oUnit.GetAIBrain then
                    --------Non-AiBot Specific logic------
                    --Rough unit count
                    if not(oUnit['AiBotDead']) then
                        oUnit['AiBotDead'] = true
                        AiBotOverseer.refiRoughTotalUnitsInGame = AiBotOverseer.refiRoughTotalUnitsInGame - 1

                        --Adjust T3 MAA count
                        if AiBotUtilities.IsTableEmpty(oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam]) == false and EntityCategoryContains(AiBotUnitInfo.refCategoryMAA * categories.TECH3, oUnit.UnitId) then
                            for iRecordedTeam, bRecorded in oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam] do
                                AiBotTeam.tTeamData[iRecordedTeam][AiBotTeam.iEnemyT3MAAActiveCount] = math.max(0, (AiBotTeam.tTeamData[iRecordedTeam][AiBotTeam.iEnemyT3MAAActiveCount] or 0) - 1)
                            end
                        end



                        --TMD protection logic - refresh land zone TMD entries
                        if oUnit[AiBotBuilding.refbUnitWantsMoreTMD] then AiBotBuilding.UpdateLZUnitsWantingTMDForUnitDeath(oUnit) end

                        --Big threat global team table update
                        if AiBotUtilities.IsTableEmpty(oUnit[AiBotUnitInfo.reftbInArmyIndexBigThreatTable]) == false then
                            AiBotTeam.RemoveUnitFromBigThreatTable(oUnit)
                        end


                        AiBotOrders.ClearAnyRepairingUnits(oUnit)

                        --Hydro resource location made available again
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryHydro, oUnit.UnitId) then
                            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition(), true, oUnit)
                            if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefHydroLocations]) == false then
                                for iHydroLocation, tHydroLocation in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefHydroLocations] do
                                    if AiBotUtilities.GetDistanceBetweenPositions(tHydroLocation, oUnit:GetPosition()) <= 2 then
                                        --Check we have no built hydros that are a different unit (to support upgrading hydros)
                                        local rPotentialTargetRect = AiBotUtilities.GetRectAroundLocation(tHydroLocation, 1)
                                        local tUnitsInRect = GetUnitsInRect(rPotentialTargetRect)
                                        local bHaveHydroOnPoint = false
                                        if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
                                            local tHydrosInRect = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryHydro, tUnitsInRect)
                                            if AiBotUtilities.IsTableEmpty(tHydrosInRect) == false then
                                                for iExistingHydro, oExistingHydro in tHydrosInRect do
                                                    if AiBotUnitInfo.IsUnitValid(oExistingHydro) and not(oExistingHydro == oUnit) then
                                                        bHaveHydroOnPoint = true
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Have another hydro unit blocking this hydro point so wont mark it as available, oExistingHydro='..oExistingHydro.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oExistingHydro)) end
                                                        break
                                                    end
                                                end
                                            end
                                        end
                                        if not(bHaveHydroOnPoint) then
                                            table.insert(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefHydroUnbuiltLocations], tHydroLocation)
                                        end
                                        break
                                    end
                                end
                            end
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnit.UnitId) then
                            --Record mex position first as it is a forked thread so may lose position if the unit dies; however ignore if looks like an upgrading mex unit
                            if bDebugMessages == true then LOG(sFunctionRef..': We have a mex that has died, checking if it was the upgrading element, .CanTakeDamage='..tostring(oUnit.CanTakeDamage or false)..'; .IsUpgrade='..tostring(oUnit.IsUpgrade or false)..'; Fraction complete='..oUnit:GetFractionComplete()..'; Owner='..oUnit:GetAIBrain().Nickname) end
                            if not(oUnit.CanTakeDamage == false and oUnit.IsUpgrade == true) then
                                local tMexPosition = {oUnit:GetPosition()[1], oUnit:GetPosition()[2], oUnit:GetPosition()[3]}
                                if bDebugMessages == true then LOG(sFunctionRef..': About to call OnMexDeath via fork, tMexPosition='..repru(tMexPosition)) end
                                if tMexPosition[1] == 0 and tMexPosition[2] == 0 then AiBotUtilities.ErrorHandler('Dont have a valid mex position - mex is showing as 0,0,0') end
                                ForkThread(AiBotBuilding.OnMexDeath, tMexPosition, (oUnit.UnitId or 'nil'), (AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil'), oUnit:GetAIBrain():GetArmyIndex(), oUnit:GetFractionComplete() == 1) --Need to fork thread or else get an error when try to wait in the building logic
                            elseif oUnit:GetFractionComplete() == 1 then
                                --Rare case where a constructed unit showed in LOUD with .IsUpgrade as true and .CanTakeDamage as false
                                ForkThread(AiBotBuilding.ConsiderDelayedOnMexDeathCall, {oUnit:GetPosition()[1], oUnit:GetPosition()[2], oUnit:GetPosition()[3]}, (oUnit.UnitId or 'nil'), (AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil'), oUnit:GetAIBrain():GetArmyIndex(), oUnit:GetAIBrain().AiBotTeam, true)
                            end
                            --[[local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition(), true, oUnit)
                            if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZOrWZMexLocations]) == false then
                                for iMexLocation, tMexLocation in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZOrWZMexLocations] do
                                    --Prev line - redid at same time as changing approach for removing an unbuilt location to try and be more accurate
                                    --if AiBotUtilities.GetDistanceBetweenPositions(tMexLocation, oUnit:GetPosition()) <= 0.9 then
                                    --Revised line:
                                    if math.abs(tMexLocation[1] - oUnit:GetPosition()[1]) < 0.9 and math.abs(tMexLocation[3] - oUnit:GetPosition()[3]) < 0.9 then
                                        table.insert(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefMexUnbuiltLocations], tMexLocation)
                                        break
                                    end
                                end
                            end--]]
                            --Radar intel coverage update
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryRadar, oUnit.UnitId) then
                            ForkThread(AiBotLand.UpdateRadarCoverageForDestroyedRadar, oUnit)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategorySonar, oUnit.UnitId) then
                            ForkThread(AiBotNavy.UpdateSonarCoverageForDestroyedSonar, oUnit)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryWall, oUnit.UnitId) and not(oUnit:GetAIBrain().AiBotAI) then
                            AiBotLand.TrackWallSegment(oUnit, false)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oUnit.UnitId) then
                            --For each AiBot team with active AiBotAI consider if we have a firebase
                            AiBotLand.ConsiderIfAnyEnemyTeamsStillHaveFirebaseOnT2ArtiDeath(oUnit)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryTMD + AiBotUnitInfo.refCategoryTML, oUnit.UnitId) then
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryTMD, oUnit.UnitId) then
                                AiBotBuilding.TMDDied(oUnit)
                            else
                                AiBotBuilding.TMLDied(oUnit)
                            end
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategorySMD, oUnit.UnitId) then
                            if oUnit:GetFractionComplete() == 1 then
                                --Go through each team other team with AiBot in it, and if they have nukes with loaded missiles, consider firing immediately
                                for iTeam = 1, AiBotTeam.iTotalTeamCount do
                                    if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or 0) > 0 then
                                        ForkThread(AiBotBuilding.ConsiderFiringFirstLoadedNukeOnTeam, iTeam)
                                    end
                                end
                            end
                        end

                        --Fixed shields
                        if AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoUnitsCoveredByShield]) == false then
                            AiBotBuilding.UpdateShieldCoverageOfUnits(oUnit, true)
                            --Units having shield coverage - update the shield table
                        elseif oUnit[AiBotBuilding.reftoShieldsProvidingCoverage] and AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]) == false then
                            for iShield, oShield in oUnit[AiBotBuilding.reftoShieldsProvidingCoverage] do
                                if AiBotUnitInfo.IsUnitValid(oShield) and AiBotUtilities.IsTableEmpty(oShield[AiBotBuilding.reftoUnitsCoveredByShield]) == false then
                                    for iEntry, oEntry in oShield[AiBotBuilding.reftoUnitsCoveredByShield] do
                                        if oEntry == oUnit then
                                            table.remove(oShield[AiBotBuilding.reftoUnitsCoveredByShield], iEntry)
                                            break
                                        end
                                    end
                                end
                            end
                        end

                        --Ythotha deathball avoidance
                        --Note -seraphimunits.lua contains SEnergyBallUnit which looks like it is for when the death ball is spawned; ID is XSL0402; SpawnElectroStorm is in the ythotha script
                        --Sandbox test - have c.36s from ythotha dying to energy ball dying, so want to run away for half of this (18s) plus extra time based on how far away we already were
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oUnit.UnitId) then
                            if oUnit.UnitId == 'xsl0401' then
                                OnYthothaDeath(oUnit)
                            end
                        end
                        if EntityCategoryContains(categories.STRUCTURE + categories.EXPERIMENTAL -AiBotUnitInfo.refCategoryMex -AiBotUnitInfo.refCategoryHydro, oUnit.UnitId) and (EntityCategoryContains(categories.STRUCTURE, oUnit.UnitId) or oUnit:GetFractionComplete() < 1) then
                            if oUnit[AiBotEngineer.reftUnitBlacklistSegmentXZ] then --EntityCategoryContains(categories.EXPERIMENTAL * categories.MOBILE - AiBotUnitInfo.refCategoryExperimentalArti, oJustBuilt.UnitId) then
                                --Treat area around experimental under construction as available again
                                AiBotEngineer.ClearBlacklistForUnitConstructed(oUnit)
                            end
                            AiBotEngineer.SearchForBuildableLocationsNearDestroyedBuilding(oUnit)
                        end

                        --Campaign specific - upgrading structure that isn't yet complete
                        if AiBotMap.bIsCampaignMap and oUnit[AiBotUnitInfo.refbObjectiveUnit] and not(oUnit[refbAlreadyRunUnitKilled]) and oUnit:GetFractionComplete() < 1 and oUnit:GetAIBrain().CampaignAI and oUnit.DoUnitCallbacks and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) then
                            oUnit:DoUnitCallbacks('OnKilled')
                        end

                        --Hostile civilian - update the zone flag for every AiBotTeam
                        if oUnit[AiBotUnitInfo.refbHostileImmobileCivilian] then
                            for iTeam, tTeam in AiBotTeam.tTeamData do
                                ForkThread(AiBotTeam.ConsiderHostileCivilianZoneFlagForDetectedUnit, oUnit, iTeam, true)
                            end
                        end

                        -------AiBot specific logic---------
                        if bDebugMessages == true then LOG(sFunctionRef..': About to consider AiBotspecific on death logic, unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Owned by brain '..oUnit:GetAIBrain().Nickname..'; Is AiBot='..tostring(oUnit:GetAIBrain().AiBotAI or false)) end
                        --Is the unit owned by AiBotAI?
                        if oUnit:GetAIBrain().AiBotAI then
                            --Air units - remove any assigned strike damage
                            if oUnit[AiBotAir.refoStrikeDamageAssigned] then
                                AiBotAir.RemoveAssignedAttacker(oUnit[AiBotAir.refoStrikeDamageAssigned], oUnit)
                            end
                            --Air scout death - record the target zone as dangerous
                            if oUnit[AiBotAir.reftScoutAssignedPlateauAndZoneRef] then
                                AiBotAir.OnAirScoutDeath(oUnit)
                            end
                            --Transport death - record target island as dangerous
                            if oUnit[AiBotAir.refiTargetIslandForDrop] then
                                local iTeam = oUnit:GetAIBrain().AiBotTeam
                                local iTargetIsland = oUnit[AiBotAir.refiTargetIslandForDrop]
                                AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandDropTime][iTargetIsland] = GetGameTimeSeconds()
                                if oUnit[AiBotAir.refiTargetZoneForDrop] then
                                    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime][iTargetIsland]) then
                                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime] = {} end
                                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime][iTargetIsland] = {}
                                    end
                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime][iTargetIsland][oUnit[AiBotAir.refiTargetZoneForDrop]] = GetGameTimeSeconds()
                                end
                            elseif oUnit[AiBotAir.refiTargetZoneForDrop] then --presumably a water zone if it has no island ref
                                local iTeam = oUnit:GetAIBrain().AiBotTeam
                                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedWaterZoneDropTime]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedWaterZoneDropTime] = {} end
                                AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedWaterZoneDropTime][oUnit[AiBotAir.refiTargetZoneForDrop]] = GetGameTimeSeconds()
                            end

                            --Raider assignment
                            if oUnit[AiBotLand.refiRaidingBasePlateau] then AiBotLand.ClearUnitRaiderStatus(oUnit, oUnit:GetAIBrain().AiBotTeam, false) end

                            --Logic that doesnt require the unit to ahve finished construction:

                            --Fixed shielding
                            if oUnit[AiBotBuilding.refbUnitWantsShielding] or oUnit[AiBotBuilding.reftoUnitsCoveredByShield] then --or oUnit[AiBotBuilding.reftoShieldsProvidingCoverage] then
                                --[[if oUnit[AiBotBuilding.reftoUnitsCoveredByShield] then
                                    --AiBotBuilding.UpdateShieldCoverageOfUnits(oUnit, true) --Already done above for all ai now --]]
                                --else
                                AiBotBuilding.CheckIfUnitWantsFixedShield(oUnit) --I.e. if a fixed hsield has died that is owned by AiBot, then want to run this function so can reassess if we hae any units that now want shielding
                                --end
                            end

                            --Gameender build tracker
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder, oUnit.UnitId) then AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refiFriendlyGameEnderCount] = math.max(0, (AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refiFriendlyGameEnderCount] or 0) - 1) end

                            --GE template shielding
                            if oUnit[AiBotBuilding.reftArtiTemplateRefs] then
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oUnit.UnitId) then
                                    local tArtiTemplate = AiBotMap.tAllPlateaus[oUnit[AiBotBuilding.reftArtiTemplateRefs][1]][AiBotMap.subrefPlateauLandZones][oUnit[AiBotBuilding.reftArtiTemplateRefs][2]][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam][AiBotMap.reftActiveGameEnderTemplates][oUnit[AiBotBuilding.reftArtiTemplateRefs][3]]
                                    if tArtiTemplate then
                                        tArtiTemplate[AiBotMap.subrefGEbDontNeedEngineers] = false
                                        --also set to false in 5s due ot building animation
                                        AiBotUtilities.DelayChangeVariable(tArtiTemplate, AiBotMap.subrefGEbDontNeedEngineers, false, 5)
                                    end
                                    --Update shieldSACUs if this is a UEF SACU
                                elseif EntityCategoryContains(categories.UEF * categories.SUBCOMMANDER, oUnit.UnitId) then
                                    local tArtiTemplate = AiBotMap.tAllPlateaus[oUnit[AiBotBuilding.reftArtiTemplateRefs][1]][AiBotMap.subrefPlateauLandZones][oUnit[AiBotBuilding.reftArtiTemplateRefs][2]][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam][AiBotMap.reftActiveGameEnderTemplates][oUnit[AiBotBuilding.reftArtiTemplateRefs][3]]
                                    if tArtiTemplate and AiBotUtilities.IsTableEmpty(tArtiTemplate[AiBotMap.subreftoGEShieldSACUs]) == false then
                                        for iSACU, oSACU in tArtiTemplate[AiBotMap.subreftoGEShieldSACUs] do
                                            if oSACU == oUnit then table.remove(tArtiTemplate[AiBotMap.subreftoGEShieldSACUs], iSACU) break end
                                        end
                                    end
                                end
                            end

                            --Special tracking e.g. for factions and shields and game enders - update
                            if oUnit[AiBotBuilding.refoNearbyFactoryOfFaction] then --i.e. gameender that wants a factory's engineers - the gameender is dead so want to clear entries for it
                                AiBotBuilding.ClearTrackingOfDeadUnitWantingFactoryEngineers(oUnit)
                            end
                            if oUnit[AiBotBuilding.reftoUnitsWantingFactoryEngineers] then --i.e. a factory that was down as the one providing engineers to a gameender - want to find a new factory
                                AiBotBuilding.UpdateTrackingOfDeadFactoryProvidingEngineers(oUnit)
                            end

                            --PD specific - stop trying to build here (in case we have far away engineers still trying to build at this location for this unit)
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryPD, oUnit.UnitId) then
                                AiBotEngineer.ConsiderClearingEngineersForUnitJustDamagedOrDestroyed(oUnit, AiBotEngineer.refActionBuildEmergencyPD)
                            end

                            --Run unit type specific on death logic where the unit is completed
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if need to run certain AiBotAI on death logic, unit fraction ocmplete='..oUnit:GetFractionComplete()) end
                            if oUnit:GetFractionComplete() == 1 then
                                AiBotEconomy.UpdateGrossIncomeForUnit(oUnit, true) --Dont fork thread
                                --Dropped units - flag that this island is dangerous if were dropped recently
                                if oUnit[AiBotAir.refiLastIslandDrop] and oUnit[AiBotAir.refiTimeLastDropped] and GetGameTimeSeconds() - oUnit[AiBotAir.refiTimeLastDropped] <= 90 then
                                    local iTeam = oUnit:GetAIBrain().AiBotTeam
                                    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandDropTime]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandDropTime] = {} end
                                    --Check we dont still have factories or signif structures here
                                    local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                                    if (tLZOrWZTeamData[AiBotMap.subrefLZSValue] or 0) < 1000 and (tLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) < 100 then
                                        local bHaveCompletedFactory = false
                                        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                            local tFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                            if AiBotUtilities.IsTableEmpty(tFactories) == false then
                                                for iFactory, oFactory in tFactories do
                                                    if AiBotUnitInfo.IsUnitValid(oFactory) and oFactory:GetFractionComplete() == 1 then
                                                        bHaveCompletedFactory = true
                                                        break
                                                    end
                                                end
                                            end
                                        end
                                        if not(bHaveCompletedFactory) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Recording that island '..(oUnit[AiBotAir.refiLastIslandDrop] or 'nil')..' is dangerous as we just had a previously dropped unit die here') end
                                            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandDropTime][oUnit[AiBotAir.refiLastIslandDrop]] = GetGameTimeSeconds()
                                        end
                                    end
                                end


                                if EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) then
                                    AiBotEngineer.ClearEngineerTracking(oUnit)
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryScathis, oUnit.UnitId) then
                                    if AiBotUtilities.IsTableEmpty(AiBotEngineer.tAllScathis) == false then
                                        for iScathis, oScathis in AiBotEngineer.tAllScathis do
                                            if oScathis == oUnit then
                                                table.remove(AiBotEngineer.tAllScathis, iScathis) --Only doing this once so can get away with using table.remove, otherwise would want to use AiBotUtilities.ArrayRemove
                                                break
                                            end
                                        end
                                    end
                                elseif EntityCategoryContains(categories.STRUCTURE, oUnit.UnitId) then
                                    --Check for upgrades
                                    --Upgrade tracking (even if have run this already)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will check if upgrade tracking needs updating, unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                                    AiBotTeam.UpdateUpgradeTrackingOfUnit(oUnit, true)
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnit.UnitId) then
                                        AiBotEconomy.UpdateZoneAiBotMexByTechCount(oUnit, true)
                                        --Update upgrading mexes
                                        AiBotEconomy.UpdateTableOfUpgradingMexesForTeam(oUnit:GetAIBrain().AiBotTeam)
                                        --Losing HQ but have a teammate of the relevant faction with better tech
                                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAllHQFactories - categories.TECH1, oUnit.UnitId) then
                                        if AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 then
                                            ForkThread(AiBotTeam.ConsiderGiftingSupportFactoriesToTeammateWithBetterHQ, oUnit:GetAIBrain(), oUnit.UnitId)
                                        end
                                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield - categories.TECH2 - categories.TECH1, oUnit.UnitId) then
                                        --Shield tracking
                                        local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, oUnit:GetAIBrain().AiBotTeam)
                                        if tLZTeamData then
                                            tLZTeamData[AiBotMap.subrefiT3FixedShieldConstructedCount] = math.max(0, (tLZTeamData[AiBotMap.subrefiT3FixedShieldConstructedCount] or 0) - 1)
                                            if oUnit:GetBlueprint().Defense.Shield.ShieldMaxHealth >= AiBotBuilding.iExperimentalShieldHealthValue then
                                                tLZTeamData[AiBotMap.subrefiExperimentalShieldConstructedCount] = math.max(0, (tLZTeamData[AiBotMap.subrefiExperimentalShieldConstructedCount] or 0) - 1)
                                            end
                                        end
                                    end
                                    AiBotEconomy.UpdateHighestFactoryTechLevelForDestroyedUnit(oUnit) --checks if it was a factory as part of this function

                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMobileLand, oUnit.UnitId) then
                                    --If unit was traveling to another land zone, then update that land zone so it no longer things the unit is traveling here
                                    AiBotLand.RemoveUnitFromListOfUnitsTravelingToLandZone(oUnit) --(this will check if it was or not)
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oUnit.UnitId) then
                                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.reftoFriendlyLandExperimentals]) == false then
                                            for iExp, oExp in AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.reftoFriendlyLandExperimentals] do
                                                if oExp == oUnit then
                                                    table.remove(AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.reftoFriendlyLandExperimentals], iExp)
                                                    break
                                                end
                                            end
                                        end
                                    end
                                end

                                --Mobile shield update
                                if oUnit[AiBotLand.refoAssignedMobileShield] then
                                    oUnit[AiBotLand.refoAssignedMobileShield][AiBotLand.refoMobileShieldTarget] = nil
                                end
                                if oUnit[AiBotLand.refoMobileShieldTarget] then
                                    oUnit[AiBotLand.refoMobileShieldTarget][AiBotLand.refoAssignedMobileShield] = nil
                                end
                            else
                                --Fraction complete is <1
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUnit.UnitId) then
                                    AiBotEconomy.UpdateHighestFactoryTechLevelForDestroyedUnit(oUnit) --still want to consider due to issue had where ACU was rebuilding only land fac was part-compelte, it got destroyed, but it thought it had T1 land fac available
                                end
                            end
                            --Update record of units with disabled weapons
                            if oUnit[AiBotUnitInfo.refbWeaponDisabled] then
                                local iTeam = oUnit:GetAIBrain().AiBotTeam
                                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoUnitsWithDisabledWeapons]) == false then
                                    for iRecorded, oRecorded in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoUnitsWithDisabledWeapons] do
                                        if oRecorded == oUnit then
                                            table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoUnitsWithDisabledWeapons], iRecorded)
                                            break
                                        end
                                    end
                                end
                            end

                            if oUnit[AiBotBuilding.refbActiveOpticsManager] then
                                local iTeam = oUnit:GetAIBrain().AiBotTeam
                                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoAlliedQuantumOptics]) == false then
                                    for iRecorded, oRecorded in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoAlliedQuantumOptics] do
                                        if oUnit == oRecorded then
                                            table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoAlliedQuantumOptics], iRecorded)
                                            break
                                        end
                                    end
                                end
                            end

                            --If unit was paused, update the table
                            if oUnit[AiBotUnitInfo.refiPausedPriority] then
                                AiBotUnitInfo.AddOrRemoveUnitFromListOfPausedUnits(oUnit, false)
                            end

                            --Primary naval fac - remove
                            if oUnit[AiBotFactory.refbPrimaryFactoryForIslandOrPond] and EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oUnit.UnitId) then
                                local iSegmentX, iSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oUnit:GetPosition())
                                local iPond = AiBotMap.tPondBySegment[iSegmentX][iSegmentZ]
                                if iPond then
                                    local iTeam = oUnit:GetAIBrain().AiBotTeam

                                    if not(AiBotUnitInfo.IsUnitValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.refoPrimaryPondNavalFactory][iPond])) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refoPrimaryPondNavalFactory][iPond] == oUnit then
                                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refoPrimaryPondNavalFactory][iPond] = nil
                                    end
                                end
                            end
                        else
                            --Specific logic to apply only if the unit is not owned by AiBot
                            if oUnit[AiBotUnitInfo.reftiTeamsRecordedAsNonAiBotAlly] and EntityCategoryContains(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryMex, oUnit.UnitId) then
                                local sTeamDataRef
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUnit.UnitId) then
                                    sTeamDataRef = AiBotMap.refiNonAiBotTeammateFactoryCount
                                else
                                    sTeamDataRef = AiBotMap.refiNonAiBotTeammateMexCount
                                end

                                for _, iTeam in oUnit[AiBotUnitInfo.reftiTeamsRecordedAsNonAiBotAlly] do
                                    local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                                    if tLZOrWZTeamData then
                                        tLZOrWZTeamData[sTeamDataRef] = math.max(0, (tLZOrWZTeamData[sTeamDataRef] or 0) - 1)
                                    end
                                end
                            end
                            if oUnit[AiBotUnitInfo.refbNonAiBotExpConstruction] then
                                local iTeam = oUnit:GetAIBrain().AiBotTeam
                                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoNonAiBotConstructingExpAndT3Navy]) == false then
                                    for iRecordedUnit, oRecordedUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoNonAiBotConstructingExpAndT3Navy] do
                                        if oRecordedUnit == oUnit then
                                            table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoNonAiBotConstructingExpAndT3Navy], iRecordedUnit)
                                            break
                                        end
                                    end
                                end
                                oUnit[AiBotUnitInfo.refbNonAiBotExpConstruction] = false
                            end
                        end
                    end
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        end
    end

--function OnWorkEnd(self, work)
    --Have commented out the line that calls this since not currently using it

    --Not sure when/if this even triggers - would need to review if plan to use
    --LOG('WOrk end has finished for self='..self.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(self)..'; work reprs='..reprs(work))
--end

function OnEnhancementStarted(self, work)
    --e.g. returns log like OnEhancementStarted start, self.UnitId==url0001; work="CoolingUpgrade"
    if AiBotUtilities.bAiBotAIInGame then
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        local sFunctionRef = 'OnEnhancementStarted'
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        if bDebugMessages == true then LOG(sFunctionRef..': start, self.UnitId=='..(self.UnitId or 'nil')..'; work='..reprs(work)..'; owner='..self:GetAIBrain().Nickname..' on team='..self:GetAIBrain().AiBotTeam) end
        self[AiBotUnitInfo.refsLastEnhancementStarted] = work
        if work == 'Teleporter' and self.GetAIBrain then
            local iACUTeam = self:GetAIBrain().AiBotTeam
            for iTeam = 1, AiBotTeam.iTotalTeamCount do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering team '..iTeam..' with AiBotBrain count='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or 'nil')) end
                if not(iTeam == iACUTeam) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                    local oFirstBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                    if bDebugMessages == true then LOG(sFunctionRef..': Is first AiBot brain an enemy of the ACU that compelted an enhancement='..tostring(IsEnemy(self:GetAIBrain():GetArmyIndex(), AiBotTeam.GetFirstActiveAiBotBrain(iTeam):GetArmyIndex()))) end
                    if oFirstBrain.GetArmyIndex and not(oFirstBrain.AiBotIsDefeated) and IsEnemy(self:GetAIBrain():GetArmyIndex(), AiBotTeam.GetFirstActiveAiBotBrain(iTeam):GetArmyIndex()) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will monitor for when enemy starts ont eleport upgrade') end
                        ForkThread(AiBotTeam.MonitorEnemyTeleportUpgrade, self, iTeam, work)
                    end
                end
            end
        end
        if AiBotUnitInfo.IsUnitValid(self) and EntityCategoryContains(categories.COMMAND, self.UnitId) and self:GetAIBrain().AiBotAI then
            self[AiBotACU.refiHealthWhenStartedUpgrade] = AiBotUnitInfo.GetUnitCurHealthAndShield(self)
            self[AiBotACU.reftiUpgradingHealthData] = {}
            AiBotACU.UpdateACUUpgradingHealth(self)
        end
    end
end

function OnEnhancementComplete(oUnit, sEnhancement)
    if AiBotUtilities.bAiBotAIInGame then
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        local sFunctionRef = 'OnEnhancementComplete'
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        --Check we haven't just run this
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code, Time we last completed sEnhancmeent '..sEnhancement..' for oUnit owned by player '..oUnit:GetAIBrain().Nickname..'='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.reftiTimeOfLastEnhancementComplete][sEnhancement] or -100)..'; Upgrade count before update='..(oUnit[AiBotACU.refiUpgradeCount] or 'nil')) end
        if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.reftiTimeOfLastEnhancementComplete][sEnhancement] or -100) >= 0.5 then
            --Clear micro flag as we set it to true for some units to avoid orders overriding
            if oUnit[AiBotUnitInfo.refbSpecialMicroActive] then
                oUnit[AiBotUnitInfo.refbSpecialMicroActive] = nil
            end
            if not(oUnit[AiBotUnitInfo.reftiTimeOfLastEnhancementComplete]) then oUnit[AiBotUnitInfo.reftiTimeOfLastEnhancementComplete] = {} end
            if oUnit[AiBotACU.refbWantsPriorityUpgrade] then oUnit[AiBotACU.refbWantsPriorityUpgrade] = nil end
            oUnit[AiBotUnitInfo.reftiTimeOfLastEnhancementComplete][sEnhancement] = GetGameTimeSeconds()
            if bDebugMessages == true then LOG(sFunctionRef..': Enhancement completed for self='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..'; sEnhancement='..reprs(sEnhancement)..'; Has enhancement for this='..tostring(oUnit:HasEnhancement(sEnhancement))..'; Unit DF range pre upgrade='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')) end
            AiBotUnitInfo.UpdateUnitCombatMassRatingForUpgrades(oUnit)
            local iDFRangePreUpgrade = (oUnit[AiBotUnitInfo.refiDFRange] or 0)
            AiBotUnitInfo.RecordUnitRange(oUnit) --Refresh the range incase enhancement has increased anything
            if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > iDFRangePreUpgrade and oUnit[AiBotUnitInfo.refiDFRange] >= 30 and not(oUnit.Dead) and oUnit:GetAIBrain().AiBotAI then
                AiBotLand.ConsiderPriorityLandScoutFlag(oUnit)
            end
            --LOUD specific - manually reflect weapon ranges for the basic gun upgrades as arent recorded against the blueprint
            if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) < 30 then
                local tsOtherUpgradeNames = {
                    'EXRipperBooster',
                    'EXZephyrBooster',
                    'EXChronotronBooster',
                    'EXDisruptorrBooster',
                }
                for iUpgrade, sUpgrade in tsOtherUpgradeNames do
                    if oUnit:HasEnhancement(sUpgrade) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Adjusting unit range for LOUD/QUIET enhancement, DFRange pre increase='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; iDFRangePreUpgrade='..iDFRangePreUpgrade) end
                        oUnit[AiBotUnitInfo.refiDFRange] = (oUnit[AiBotUnitInfo.refiDFRange] or 0) + 5
                        break
                    end
                end
            end
            if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > iDFRangePreUpgrade then
                AiBotOverseer.bLikelyGunUpgrade = true
            end

            --Mobile TML logic (e.g. ACU and SACU, and billy nuke) - note some manual ranges are e.g. for overcharge
            if (oUnit[AiBotUnitInfo.refiManualRange] or 0) > 50 then
                --Record this against every opposing AiBot Team
                if bDebugMessages == true then LOG(sFunctionRef..': have unit with tml upgrade, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                ForkThread(AiBotTeam.RecordMobileTMLThreatForAllEnemyTeams, oUnit)
            end

            --Update upgrade count
            oUnit[AiBotACU.refiUpgradeCount] = (oUnit[AiBotACU.refiUpgradeCount] or 0) + 1
            if EntityCategoryContains(categories.COMMAND + categories.SUBCOMMANDER, oUnit.UnitId) then
                if sEnhancement == 'Teleporter' then
                    if bDebugMessages == true then LOG(sFunctionRef..': Flagging that unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' has got teleporter upgrade and setting weapon prioritisation accordingly') end
                    oUnit[AiBotACU.refbACUHasTeleport] = true
                    if ScenarioInfo.Options.Victory == "demoralization" then
                        AiBotUnitInfo.SetUnitWeaponTargetPriorities(oUnit, AiBotUnitInfo.refWeaponPriorityTeleSnipeInclACU, false)
                    else
                        AiBotUnitInfo.SetUnitWeaponTargetPriorities(oUnit, AiBotUnitInfo.refWeaponPriorityTeleSnipeExclACU, false)
                    end
                elseif sEnhancement == 'AdvancedEngineering' then
                    oUnit[AiBotACU.refiBuildTech] = 2
                elseif sEnhancement == 'T3Engineering' then
                    oUnit[AiBotACU.refiBuildTech] = 3
                elseif sEnhancement == 'AdvancedEngineeringRemove' then
                    oUnit[AiBotACU.refiBuildTech] = 1
                elseif sEnhancement == 'T3EngineeringRemove' then
                    oUnit[AiBotACU.refiBuildTech] = 1
                elseif  sEnhancement == 'StealthGenerator' or sEnhancement == 'FAF_SelfRepairSystem' or sEnhancement == 'CloakingGenerator' then
                    if oUnit[AiBotLand.refoAssignedMobileStealth] then
                        oUnit[AiBotLand.refoAssignedMobileStealth][AiBotLand.refoMobileStealthTarget] = nil
                    end
                    --Have all enemy AiBot teams send air scouts to keep an eye on this unit
                    for iTeam = 1, AiBotTeam.iTotalTeamCount do
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                            ForkThread(AiBotAir.MonitorEnemyACUForScoutPrioritisation,oUnit, iTeam)
                        end
                    end
                    --Treat enemies with laser com or seraphim gun as being land experimentals so they are seen as greater threat
                elseif sEnhancement == 'MicrowaveLaserGenerator' or sEnhancement == 'BlastAttack' then
                    --double-check the upgrade mass cost indicates it is a deadly upgrade
                    local iUpgradeMassCost = oUnit:GetBlueprint().Enhancements[sEnhancement].BuildCostMass
                    if bDebugMessages == true then LOG(sFunctionRef..': Have got laser or sera gun, iUpgradeMassCost='..iUpgradeMassCost) end
                    if iUpgradeMassCost >= 3000 then
                        --Every other team - add to bigthreat table
                        local iOurTeam = oUnit:GetAIBrain().AiBotTeam
                        for iTeam = 1, AiBotTeam.iTotalTeamCount do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering adding to big threat table for iTeam='..iTeam..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; Team of the ACU='..iOurTeam) end
                            if not(iOurTeam == iTeam) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Adding to big threat table') end
                                AiBotTeam.AddUnitToBigThreatTable(iTeam, oUnit)
                            end
                        end
                    end
                    --Enable autoovercharge if this is an AiBotACU and flag we dont want to manually overcharge
                    if oUnit.SetAutoOvercharge and oUnit:GetAIBrain().AiBotAI and (AiBotOrders.bDontConsiderCombinedArmy or oUnit.AiBotActive) then
                        oUnit:SetAutoOvercharge(true)
                        oUnit[AiBotUnitInfo.refbDisableOvercharge] = true
                    end
                end
                if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then
                    --Consider being more aggressive with ACU again (mainly relevant for team games)
                    oUnit[AiBotACU.refbUseACUAggressively] = AiBotACU.DoWeStillWantToBeAggressiveWithACU(oUnit)
                    if oUnit[AiBotACU.reftiUpgradingHealthData] then oUnit[AiBotACU.reftiUpgradingHealthData] = nil end
                end
                --Flag that enemy has a dangerous ACU if they have multiple combat upgrades
                if oUnit[AiBotACU.refiUpgradeCount] >= 2 and (oUnit[AiBotUnitInfo.refiDFMassThreatOverride] or 0) - AiBotUnitInfo.iBaseACUThreat >= 1600 and (oUnit:GetMaxHealth() >= AiBotUnitInfo.iBaseACUExpectedHealth + 2000 or (oUnit.MyShield and oUnit.MyShield:GetMaxHealth() > 0) or oUnit:HasEnhancement('StealthGenerator')) then
                    local iTeamToIgnore = oUnit:GetAIBrain().AiBotTeam
                    for iCurTeam = 1, AiBotTeam.iTotalTeamCount do
                        if not(iCurTeam == iTeamToIgnore) and (AiBotTeam.tTeamData[iCurTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or 0) > 0 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Flagging that the enemy has a dangerous ACU for team '..iCurTeam..'; due to ACU owned by '..oUnit:GetAIBrain().Nickname..' with upgrade count='..oUnit[AiBotACU.refiUpgradeCount]) end
                            AiBotTeam.tTeamData[iCurTeam][AiBotTeam.refbEnemyHasDangerousACU] = true
                        end
                    end
                end


            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAllHQFactories, oUnit.UnitId) and AiBotUtilities.bFAFActive then
                oUnit[AiBotFactory.refbPrimaryFactoryForIslandOrPond] = true --makes sure we dont pause this factory in a mass stall now it has enhancements
            end
            --Fix AIx modifier
            if oUnit:GetAIBrain().CheatEnabled then
                AiBotUnitInfo.FixUnitResourceCheatModifiers(oUnit)
            end
            if oUnit:GetAIBrain().AiBotAI then
                if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then
                    AiBotACU.GetUpgradePathForACU(oUnit)
                end
                --Remove any upgrade tracking
                AiBotTeam.UpdateUpgradeTrackingOfUnit(oUnit, true, sEnhancement)
            end
            if sEnhancement == 'CloakingGenerator' then
                --Record in table for enemy teams
                CloakedUnitIdentified(oUnit)
            end
            --Update eco for RAS
            local tEnhancement = oUnit:GetBlueprint().Enhancements[sEnhancement]
            if bDebugMessages == true then LOG(sFunctionRef..': tEnhancement='..reprs(tEnhancement)) end
            if tEnhancement then
                if tEnhancement.ProductionPerSecondEnergy or tEnhancement.ProductionperSecondMass then
                    --Remove existing entries for unit then create new ones
                    AiBotEconomy.UpdateGrossIncomeForUnit(oUnit, true, true)
                    AiBotEconomy.UpdateGrossIncomeForUnit(oUnit, false, false)
                end
            end

            --Teleport details
            if sEnhancement == 'Teleporter' then
                for iCurTeam = 1, AiBotTeam.iTotalTeamCount do
                    if not(iCurTeam == oUnit:GetAIBrain().AiBotTeam) and AiBotTeam.tTeamData[iCurTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                        AiBotTeam.tTeamData[iCurTeam][AiBotTeam.refbEnemyHasTeleport] = true
                    end
                end
            end

            --Paragon - xfer SACU (disabled as we lose upgrades on transfer as at Aug 25
            --[[if sEnhancement == 'ResourceAllocation' and EntityCategoryContains(categories.SUBCOMMANDER, oUnit.UnitId) and oUnit:GetAIBrain().AiBotAI and (AiBotOrders.bDontConsiderCombinedArmy or oUnit.AiBotActive) and oUnit:GetAIBrain()[AiBotEconomy.refbBuiltParagon] then
                local oLeastMassNonParagonBrain
                local iLeastNetMass = 500
                for iBrain, oBrain in AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                    if not(oBrain[AiBotEconomy.refbBuiltParagon]) and oBrain[AiBotEconomy.refiNetMassBaseIncome] < iLeastNetMass then
                        iLeastNetMass = oBrain[AiBotEconomy.refiNetMassBaseIncome]
                        oLeastMassNonParagonBrain = oBrain
                    end
                end
                if oLeastMassNonParagonBrain then
                    ForkThread(AiBotTeam.TransferUnitsToPlayer, { oUnit }, oLeastMassNonParagonBrain:GetArmyIndex(), false)
                end
            end--]]

            if bDebugMessages == true then LOG(sFunctionRef..': Unit DF range after updating recorded range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')) end
        end
        --if not(oUnit.Dead) and oUnit.SetAutoOvercharge and oUnit:GetAIBrain().AiBotAI and (AiBotOrders.bDontConsiderCombinedArmy or oUnit.AiBotActive) then oUnit:SetAutoOvercharge(false) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function CloakedUnitIdentified(oUnit)
    if AiBotUtilities.bAiBotAIInGame then
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        local sFunctionRef = 'CloakedUnitIdentified'
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        local iUnitBrainIndex = oUnit:GetAIBrain():GetArmyIndex()
        local tbTeamsConsidered = {}
        for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
            if IsEnemy(oBrain:GetArmyIndex(), iUnitBrainIndex) and not(tbTeamsConsidered[oBrain.AiBotTeam]) then
                local iTeam = oBrain.AiBotTeam
                tbTeamsConsidered[iTeam] = true
                local bAddToTable = true
                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCloakedEnemyUnits]) then
                    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCloakedEnemyUnits] = {}
                else
                    for iRecorded, oRecorded in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCloakedEnemyUnits] do
                        if oRecorded == oUnit then
                            bAddToTable = false
                            break
                        end
                    end
                end
                if bAddToTable then
                    table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCloakedEnemyUnits], oUnit)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Added unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by brain '..oUnit:GetAIBrain().Nickname..' to table of cloaked units for iTeam='..iTeam..' unless was already recorded, bAddToTable='..tostring(bAddToTable)..'; Time='..GetGameTimeSeconds()) end
            end
        end
        oUnit[AiBotUnitInfo.refbUnitIsCloaked] = true
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnShieldBubbleDamaged(self, instigator)
    if AiBotUtilities.bAiBotAIInGame then
        local oShield = self.Owner
        --LOG('Shield damaged, self='..reprs(self)..'; owner='..reprs(self.Owner))
        if not(oShield.Dead) then
            if oShield:GetAIBrain().AiBotAI then
                oShield[AiBotUnitInfo.refiTimeLastDamaged] = GetGameTimeSeconds()
                --If damaged by Aeon T3 arti set a temporary flag
                if instigator.UnitId == 'uab2302' then oShield[AiBotBuilding.refiTimeOfLastAeonT3ArtiDamageToShield] = GetGameTimeSeconds() end
            end
            --LOG('instigator='..reprs(instigator))
            if AiBotUnitInfo.IsUnitValid(instigator) and instigator:GetAIBrain().AiBotAI and IsEnemy(oShield:GetAIBrain():GetArmyIndex(), instigator:GetAIBrain():GetArmyIndex()) then
                local oUnitCausingDamage
                if instigator and not(instigator:BeenDestroyed()) then
                    if instigator.GetLauncher and instigator:GetLauncher() then
                        oUnitCausingDamage = instigator:GetLauncher()
                    elseif instigator.DamageData and not(instigator.unit) and not(instigator.UnitId) then
                        --Can get errors for artillery shells when running IsProjectile
                    elseif IsProjectile(instigator) or IsCollisionBeam(instigator) then
                        if instigator.unit then
                            oUnitCausingDamage = instigator.unit
                        end
                    elseif IsUnit(instigator) then
                        oUnitCausingDamage = instigator
                    end
                end
                if oUnitCausingDamage and not(oUnitCausingDamage.Dead) then oUnitCausingDamage[AiBotUnitInfo.refiTimeOfLastUnblockedShot] = GetGameTimeSeconds() end
                if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oShield.UnitId) then
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryMML, instigator.UnitId) then
                        local iShieldPlateau, iShieldLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oShield:GetPosition())
                        if (iShieldLandZone or 0) > 0 and iShieldPlateau > 0 then
                            local tLZTeamData = AiBotMap.tAllPlateaus[iShieldPlateau][AiBotMap.subrefPlateauLandZones][iShieldLandZone][AiBotMap.subrefLZTeamData][instigator:GetAIBrain().AiBotTeam]
                            tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] = GetGameTimeSeconds()
                            local iMMLPlateau, iMMLZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(instigator:GetPosition())
                            if (iMMLPlateau or 0) > 0 and (iMMLZone or 0) > 0 and not(iMMLZone == iShieldLandZone and iMMLPlateau == iShieldPlateau) then
                                local tMMLLZTeamData = AiBotMap.tAllPlateaus[iMMLPlateau][AiBotMap.subrefPlateauLandZones][iMMLZone][AiBotMap.subrefLZTeamData][instigator:GetAIBrain().AiBotTeam]
                                tMMLLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] = GetGameTimeSeconds()
                            end
                            --LOG('Flagging that we have had missiles intercepted by TMD or shield for iShieldLandZone and MML zone, iShieldLandZone='..(iShieldLandZone or 'nil')..'; iMMLZone='..(iMMLZone or 'nil')..'; iMMLPlateau='..(iMMLPlateau or 'nil'))
                        end
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti, instigator.UnitId) then
                        --LOG('Cur shield health='..oShield.MyShield:GetHealth())
                        if oShield.MyShield.GetHealth and oShield.MyShield:GetHealth() <= 750 then
                            --Record shield in table of recently failed shields for if we have a novax
                            local iTeam = instigator:GetAIBrain().AiBotTeam
                            local bRecordedAlready
                            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyShieldsFailedToArti]) then
                                AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyShieldsFailedToArti] = {}
                            else
                                for iEntry, oRecorded in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyShieldsFailedToArti] do
                                    if oRecorded == oShield then
                                        bRecordedAlready = true
                                        break
                                    end
                                end
                            end
                            if not(bRecordedAlready) then
                                table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyShieldsFailedToArti], oShield)
                            end
                        end
                    end
                else
                    --Fatboy specific; if changing threshold here then also change in team
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oShield.UnitId) then
                        if (oShield[AiBotBuilding.refiTMLShotsFired] or 0) > 0 and oUnitCausingDamage.GetAIBrain and oUnitCausingDamage:GetAIBrain().AiBotAI and EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oUnitCausingDamage.UnitId) then
                            oShield[AiBotBuilding.refiTMLShotsHit] = (oShield[AiBotBuilding.refiTMLShotsHit] or 0) + 1
                        end
                        if oShield.MyShield.GetHealth and oShield.MyShield:GetHealth() <= oShield.MyShield:GetMaxHealth() * 0.5 then
                            local iTeam = instigator:GetAIBrain().AiBotTeam
                            local bRecordedAlready
                            if oShield.MyShield:GetHealth() <= 1250 then
                                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyShieldsFailedToArti]) then
                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyShieldsFailedToArti] = {}
                                else
                                    for iEntry, oRecorded in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyShieldsFailedToArti] do
                                        if oRecorded == oShield then
                                            bRecordedAlready = true
                                            break
                                        end
                                    end
                                end
                                if not(bRecordedAlready) then
                                    table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyShieldsFailedToArti], oShield)
                                end
                            end
                            bRecordedAlready = false
                            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoVulnerableFatboys]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoVulnerableFatboys] = {}
                            else
                                for iEntry, oRecorded in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoVulnerableFatboys] do
                                    if oRecorded == oShield then
                                        bRecordedAlready = true
                                        break
                                    end
                                end
                            end
                            if not(bRecordedAlready) then
                                table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoVulnerableFatboys], oShield)
                                ForkThread(AiBotTeam.MonitorVulnerableFatboys,iTeam)
                            end
                        end
                    end
                end
            end
        end
    end
end

function OnDamaged(self, instigator) --This doesnt trigger when a shield bubble is damaged - see OnShieldBubbleDamaged for this
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'OnDamaged'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if self.IsWreckage then
            --Will only update when props and wrecks are destroyed for performance reasons
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Non-wreck damaged') end
            if self.GetUnitId and (not(AiBotMap.bIsCampaignMap) or GetGameTimeSeconds() >= 300 or not(ScenarioInfo.OpEnded)) then
                local oUnitCausingDamage
                if instigator and not(instigator:BeenDestroyed()) then
                    if instigator.GetLauncher and instigator:GetLauncher() then
                        oUnitCausingDamage = instigator:GetLauncher()
                    elseif instigator.DamageData and not(instigator.unit) and not(instigator.UnitId) then
                        --Can get errors for artillery shells when running IsProjectile
                    elseif IsProjectile(instigator) or IsCollisionBeam(instigator) then
                        if instigator.unit then
                            oUnitCausingDamage = instigator.unit
                        end
                    elseif IsUnit(instigator) then
                        oUnitCausingDamage = instigator
                    end
                    if bDebugMessages == true then
                        if not(oUnitCausingDamage) then LOG(sFunctionRef..': Dont ahve a valid unit as instigator')
                        else LOG(sFunctionRef..': Have a unit causing damage='..oUnitCausingDamage.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitCausingDamage)) end
                    end
                end

                --Logic specific to AiBot units dealing damage
                if AiBotUnitInfo.IsUnitValid(oUnitCausingDamage) and oUnitCausingDamage:GetAIBrain().AiBotAI then
                    --Update so unit isnt treated as having shot blocked
                    oUnitCausingDamage[AiBotUnitInfo.refbLastShotBlocked] = false
                    oUnitCausingDamage[AiBotUnitInfo.refiTimeOfLastUnblockedShot] = GetGameTimeSeconds()
                    if AiBotUnitInfo.IsUnitValid(self) and (self[AiBotUnitInfo.refiTargetShotBlockedCount] or 0) > 0 then self[AiBotUnitInfo.refiTargetShotBlockedCount] = self[AiBotUnitInfo.refiTargetShotBlockedCount] - 10 end

                    --Unit category specific:
                        --T3/experimental arti specific
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti, oUnitCausingDamage.UnitId) then
                        --Reset the arti shot count if damaged a high value unit
                        if AiBotUnitInfo.IsUnitValid(self) then
                            if bDebugMessages == true then LOG(sFunctionRef..': T3/Exp arti owned by AiBot brain '..oUnitCausingDamage:GetAIBrain().Nickname..', arti unit='..oUnitCausingDamage.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitCausingDamage)..' has just damaged unit '..self.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(self)..' which is valid') end
                            local iUnitDamagedMassValue = (self[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(self)) * self:GetFractionComplete()
                            if iUnitDamagedMassValue >= 700 then
                                --Reduce the ineffective arti shot count
                                local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(self:GetPosition())
                                local tLZOrWZTeamData
                                if iPlateauOrZero > 0 then
                                    tLZOrWZTeamData  = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][oUnitCausingDamage:GetAIBrain().AiBotTeam]
                                else
                                    --Water zone
                                    tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][oUnitCausingDamage:GetAIBrain().AiBotTeam]
                                end
                                local iReductionValue
                                if iUnitDamagedMassValue >= 10000 then
                                    iReductionValue = 50
                                elseif iUnitDamagedMassValue >= 3000 then
                                    iReductionValue = 12
                                else
                                    iReductionValue = 6
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Changing ineffective shot count, iPlateauOrZero='..iPlateauOrZero..'; iLandOrWateZone='..iLandOrWaterZone..'; tLZOrWZTeamData[AiBotMap.subrefiIneffectiveArtiShotCount]='..(tLZOrWZTeamData[AiBotMap.subrefiIneffectiveArtiShotCount] or 'nil')..'; iReductionValue='..iReductionValue) end
                                tLZOrWZTeamData[AiBotMap.subrefiIneffectiveArtiShotCount] = math.max(0, (tLZOrWZTeamData[AiBotMap.subrefiIneffectiveArtiShotCount] or 0) - iReductionValue)
                            end
                        end
                        --TML - update shots hit
                    elseif self[AiBotBuilding.refiTMLShotsFired] or 0 > 0 and EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oUnitCausingDamage.UnitId) then
                        self[AiBotBuilding.refiTMLShotsHit] = (self[AiBotBuilding.refiTMLShotsHit] or 0) + 1
                        --Mobile missile units that have a missed count - record
                    elseif self[AiBotUnitInfo.refiMissileShotBlockedCount] and oUnitCausingDamage[AiBotUnitInfo.reftoTargetBlockedMissileCountByEntityId][self.EntityId] then
                        self[AiBotUnitInfo.refiMissileShotBlockedCount] = math.max(0, self[AiBotUnitInfo.refiMissileShotBlockedCount] - 8) --Missile ships have quite a high degree of firing randomness, so want to decrease by a lot if we manage to hit
                        oUnitCausingDamage[AiBotUnitInfo.reftoTargetBlockedMissileCountByEntityId][self.EntityId] = math.max(0, oUnitCausingDamage[AiBotUnitInfo.reftoTargetBlockedMissileCountByEntityId][self.EntityId] - 3)
                        --Bombers - record that have successfully damaged the target (i.e. that our bomb didnt miss after all)
                    elseif self[AiBotUnitInfo.refiBombMissedCount] and EntityCategoryContains(AiBotUnitInfo.refCategoryBomber, oUnitCausingDamage.UnitId) then
                        self[AiBotUnitInfo.refiBombMissedCount] = nil
                        --Scouts on 'kite enemy' logic that have run into an ACU (which will regen more than they can damage) - free up scouts for other use
                    elseif oUnitCausingDamage[AiBotUnitInfo.refbScoutCombatOverride] and EntityCategoryContains(categories.COMMAND, self.UnitId) and not(self.Dead) and AiBotUnitInfo.GetUnitHealthPercent(self) >= 0.99 then
                        --Check how many scouts we have in the zone with combat override, if we have more than 3, then release this from override
                        local iTeam = oUnitCausingDamage:GetAIBrain().AiBotTeam
                        local iPlateau = oUnitCausingDamage[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
                        local iLandZone = oUnitCausingDamage[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                        if iPlateau and iLandZone then
                            local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                            if tLZData then
                                local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                    local tLandScouts = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandScout, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                    if AiBotUtilities.IsTableEmpty(tLandScouts) == false then
                                        local iCombatScouts = 0
                                        for iScout, oScout in tLandScouts do
                                            if not(oScout.Dead) and oScout[AiBotUnitInfo.refbScoutCombatOverride] and AiBotUtilities.GetDistanceBetweenPositions(oScout:GetPosition(), self:GetPosition()) <= oScout[AiBotUnitInfo.refiCombatRange] +  6 then
                                                iCombatScouts = iCombatScouts + 1
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': iCombatScouts in range='..iCombatScouts..'; total scouts='..table.getn(tLandScouts)..'; Considering if should clear combat scout flag on oUnitCausingDamage='..oUnitCausingDamage.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitCausingDamage)..' who just hurt ACU owned by '..self:GetAIBrain().Nickname) end
                                        if iCombatScouts >= 3 then
                                            oUnitCausingDamage[AiBotUnitInfo.refbScoutCombatOverride] = nil
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if EntityCategoryContains(categories.EXPERIMENTAL, self.UnitId) and self:GetFractionComplete() < 1 and self:GetFractionComplete() > 0.1 then
                        if (AiBotOrders.bDontConsiderCombinedArmy or oUnitCausingDamage.AiBotActive) then
                            ForkThread(AiBotChat.PartCompleteExperimentalDamaged, self, oUnitCausingDamage)
                        end
                    end
                    --If damaging enemy ACU consider all-in attack to kill it
                    if not(self.Dead) and EntityCategoryContains(categories.COMMAND, self.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryMobileDFLand, oUnitCausingDamage.UnitId) and self:GetHealth() <= 12500 then
                        ForkThread(AiBotMicro.ConsiderAllInLandPushOnACU, oUnitCausingDamage:GetAIBrain(), self)
                    end
                end

                --Logic specific to AiBot units dealt damage
                if self:GetAIBrain().AiBotAI then
                    if bDebugMessages == true then LOG(sFunctionRef..': AiBotAI owned unit just taken damage, unit='..self.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(self)..'; Is this a gunship that can refuel='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryGunship - categories.CANNOTUSEAIRSTAGING, self.UnitId) and not(self.MyShield) and not(self[AiBotUnitInfo.refbProjectilesMeanShouldRefuel]))..'; self.MyShield==nil='..tostring(self.MyShield == nil)..'; self[AiBotUnitInfo.refbProjectilesMeanShouldRefuel]='..tostring(self[AiBotUnitInfo.refbProjectilesMeanShouldRefuel] or false)..'; oUnitCausingDamage='..(oUnitCausingDamage.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitCausingDamage) or 'nil')) end
                    if EntityCategoryContains(categories.COMMAND, self.UnitId) then
                        if self:IsUnitState('Upgrading') then
                            --Do we want to cancel the upgrade? If were hit by a TML then want to
                            if AiBotUnitInfo.IsUnitValid(oUnitCausingDamage) and EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oUnitCausingDamage.UnitId) then
                                if not(self[AiBotUnitInfo.refbEasyBrain]) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will cancel upgrade and move away temporarily') end
                                    AiBotMicro.MoveAwayFromTargetTemporarily(self, 5, oUnitCausingDamage:GetPosition())
                                    self[AiBotUnitInfo.refiTimeLastCanceledUpgrade] = GetGameTimeSeconds()
                                    local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(self:GetPosition(), true, self:GetAIBrain().AiBotTeam)
                                    self[AiBotUnitInfo.refiDistToEnemyBaseWhenLastCanceledUpgrade] = AiBotUtilities.GetDistanceBetweenPositions(self:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase])
                                end
                            end
                        end
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryPD, self.UnitId) and AiBotUnitInfo.IsUnitValid(self) and (self:GetFractionComplete() <= 0.7 or (self:GetFractionComplete() <= 0.85 and AiBotUnitInfo.GetUnitHealthPercent(self) <= 0.5)) and EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryIndirect, oUnitCausingDamage.UnitId) then
                        AiBotEngineer.ConsiderClearingEngineersForUnitJustDamagedOrDestroyed(self,  AiBotEngineer.refActionBuildEmergencyPD)
                        --Special voice message for fletcher fatboy damaged by soulripper
                    elseif self[AiBotAir.refiTargetZoneForDrop] and EntityCategoryContains(AiBotUnitInfo.refCategoryTransport, self.UnitId) then
                        self[AiBotUnitInfo.refiTimeLastDamaged] = GetGameTimeSeconds()
                    elseif oUnitCausingDamage.UnitId and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, self.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryGunship * categories.CYBRAN * categories.EXPERIMENTAL, oUnitCausingDamage.UnitId) and self:GetAIBrain()[AiBotChat.refiAssignedPersonality] == AiBotChat.refiFletcher then
                        if AiBotOrders.bDontConsiderCombinedArmy or oUnitCausingDamage.AiBotActive then
                            ForkThread(AiBotChat.SendMessage, self:GetAIBrain(), 'SoulripperDmgFatboy', LOC('<LOC X05_M02_240_010>[{i Fletcher}]: Soul Rippers are tearing up my Fatboy! I need air cover, now!'), 1, 600, false, true, 'X05_Fletcher_M02_04945', 'X05_VO')
                        end
                        --Gunships - consider retreating early
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryGunship - categories.CANNOTUSEAIRSTAGING, self.UnitId) and not(self.MyShield) and not(self[AiBotUnitInfo.refbProjectilesMeanShouldRefuel]) then
                        if AiBotUnitInfo.IsUnitValid(self) then
                            local iCurHealth = self:GetHealth()
                            local iMaxHealth = self:GetMaxHealth()

                            if bDebugMessages == true then LOG(sFunctionRef..': iCurHealth='..iCurHealth..'; iMaxHealth='..iMaxHealth..'; %='..iCurHealth / iMaxHealth..'; Projectile low health%='..AiBotAir.GetHealthRunThreshold(iMaxHealth, self)) end
                            if iCurHealth <= iMaxHealth * AiBotAir.GetHealthRunThreshold(iMaxHealth, self) then
                                self[AiBotUnitInfo.refbProjectilesMeanShouldRefuel] = true
                                AiBotAir.SendUnitsForRefueling({ self }, self:GetAIBrain().AiBotTeam, self:GetAIBrain().AiBotAirSubteam, true)
                                if bDebugMessages == true then LOG(sFunctionRef..'; sent gunship '..self.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(self)..' for refueling due to existing damage taken') end
                            end
                        end
                    end
                    --General - if enemy has non-long range direct fire structure that hit an AiBot unit, then check if it is in the same or adjacen tzone, so can record if it isnt
                    if oUnitCausingDamage.GetPosition and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnitCausingDamage.UnitId) and oUnitCausingDamage[AiBotUnitInfo.refiDFRange] and oUnitCausingDamage[AiBotUnitInfo.refiDFRange] < 100 and oUnitCausingDamage[AiBotUnitInfo.refiDFRange] > 0 and self.GetPosition then
                        if oUnitCausingDamage[AiBotUnitInfo.refiDFRange] < 60 or AiBotUtilities.GetDistanceBetweenPositions(oUnitCausingDamage:GetPosition(), self:GetPosition()) < 60 then
                            local iPDPlateauOrZero, iPDZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnitCausingDamage:GetPosition())
                            local iDamagedPlateauOrZero, iDamagedZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(self:GetPosition())
                            if not(iPDPlateauOrZero == iDamagedPlateauOrZero and iPDZone == iDamagedZone) and (iPDPlateauOrZero or 0) > 0 and iDamagedPlateauOrZero > 0 then
                                --Arent in the same zone, but are both in land zones are we in an adjacent zone?
                                local tDamagedLZData = AiBotMap.tAllPlateaus[iDamagedPlateauOrZero][AiBotMap.subrefPlateauLandZones][iDamagedZone]
                                local bPDIsInAdjacentZone = false
                                if iDamagedPlateauOrZero == iPDPlateauOrZero and AiBotUtilities.IsTableEmpty(tDamagedLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                    for _, iAdjLZ in tDamagedLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                        if iAdjLZ == iPDZone then
                                            bPDIsInAdjacentZone = true
                                            break
                                        end
                                    end
                                end
                                if not(bPDIsInAdjacentZone) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have PD in a nearby non-adjacent zone, oUnitCausingDamage='..oUnitCausingDamage.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitCausingDamage)..'; iPDPlateauOrZero='..iPDPlateauOrZero..'; iPDZone='..iPDZone..'; iDamagedPlateauOrZero='..iDamagedPlateauOrZero..'; iDamagedZone='..iDamagedZone..'; Time='..GetGameTimeSeconds()) end
                                    local bAlreadyRecorded = false
                                    if not(tDamagedLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones]) then
                                        tDamagedLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] = {}
                                    else
                                        for iEntry, tPlateauAndZone in tDamagedLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] do
                                            if tPlateauAndZone[2] == iPDZone and tPlateauAndZone[1] == iPDPlateauOrZero then
                                                bAlreadyRecorded = true
                                                break
                                            end
                                        end
                                    end
                                    if not(bAlreadyRecorded) then
                                        table.insert(tDamagedLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones], {iPDPlateauOrZero, iPDZone})
                                        local tPDLZData = AiBotMap.tAllPlateaus[iPDPlateauOrZero][AiBotMap.subrefPlateauLandZones][iPDZone]
                                        if not(tPDLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones]) then tPDLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones] = {} end
                                        table.insert(tPDLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones], {iDamagedPlateauOrZero, iDamagedZone})
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': tDamagedLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones]='..reprs(tDamagedLZData[AiBotMap.subrefDangerousNearbyPlateauAndZones])) end
                                end
                            end
                        end
                    end
                end

            end

        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnBombFired(oWeapon, projectile, bIgnoreProjectileCheck)
    --bIgnoreProjectileCheck - if this is true, then will run the main part of the logic even if have fired a bomb recently and have no projectile specified (i.e. intended use is with the redundancy for onweaponfired which calls this logic)
    if AiBotUtilities.bAiBotAIInGame then
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        local sFunctionRef = 'OnBombFired'
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code') end
        local oUnit = oWeapon.unit
        if oUnit and oUnit.GetUnitId and (projectile or bIgnoreProjectileCheck or GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastDodgeBombEvent] or 0) >= 2) then
            oUnit[AiBotUnitInfo.refiLastBombFired] = GetGameTimeSeconds()
            local sUnitID = oUnit.UnitId

            if bDebugMessages == true then LOG(sFunctionRef..': bomber position when firing bomb='..repru(oUnit:GetPosition())..'; Bomber='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Owner='..oUnit:GetAIBrain().Nickname..'; Time='..GetGameTimeSeconds()..'; Time since last bomber event='..(GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastDodgeBombEvent] or 0))) end
            if EntityCategoryContains(AiBotUnitInfo.refCategoryBomber + AiBotUnitInfo.refCategoryTorpBomber, sUnitID) then
                --if not(EntityCategoryContains(categories.EXPERIMENTAL, sUnitID)) then
                if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastDodgeBombEvent] or 0) >= 2 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will try and dodge the bomb fired by unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                    AiBotMicro.DodgeBomb(oUnit, oWeapon, projectile)
                end
                --Logic relating to the bomber itself:
                if not(oUnit.Dead) then
                    --Ahwassa and strats - micro the bomber so they turn around and retreat to rally point/nearest base, but dont micro the first couple of strats as the enemy is less likely to have T3 AA (and slowing down to micro could cause them to die to flak)
                    if EntityCategoryContains(categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryBomber, sUnitID) and ((not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) and not(oUnit[AiBotAir.rebEarlyBomberTargetBase]) and not(oUnit[AiBotAir.refiBomberTargetNavalEngiWZ])) or not(EntityCategoryContains(categories.TECH1, sUnitID))) then
                        --bombers - micro to turn around and go to rally point
                        if oUnit:GetAIBrain().AiBotAI then
                            local oTargetUnit = oUnit[AiBotOrders.reftiLastOrders][AiBotOrders.subrefoOrderUnitTarget]
                            if AiBotUnitInfo.IsUnitValid(oUnit) then
                                oUnit[AiBotUnitInfo.refiBombMissedCount] = ( oUnit[AiBotUnitInfo.refiBombMissedCount] or 0) + 1
                            end
                            if oUnit[AiBotAir.refbBomberUsingMexHunterLogic] then
                                ForkThread(AiBotAir.AttackTargetForMexHuntingBomber, oUnit, true)
                            elseif not(oUnit[AiBotUnitInfo.refbEasyBrain]) or oUnit.UnitId == 'xsa0402' then
                                --T1 early bomber - disable run away logic
                                if oUnit[AiBotAir.rebEarlyBomberTargetBase] then
                                    if not(AiBotUnitInfo.DoesBomberFireSalvo(oUnit)) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Clearing any micro flags we have for the bomber') end
                                        if oUnit[AiBotUnitInfo.refbSpecialMicroActive] then
                                            oUnit[AiBotUnitInfo.refbSpecialMicroActive] = false
                                        end
                                    else
                                        if bDebugMessages == true then LOG(sFunctionRef..': Do nothing as bomber firing a salvo and is a 1st bomber') end
                                    end
                                elseif oUnit[AiBotAir.refiBomberTargetNavalEngiWZ] then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Do nothing as naval engi bomber') end
                                else
                                    --Track exp bombs fired (relevant for when trying to use our aoe to hit mobile targets safely)
                                    if bDebugMessages == true then LOG(sFunctionRef..': will get bomber to head towards rally point, bomber='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Bomber position='..repru(oUnit:GetPosition())..'; Rally point='..repru(AiBotTeam.tAirSubteamData[oUnit:GetAIBrain().AiBotAirSubteam][AiBotTeam.reftAirRallyPoint])..'; Dist to rally point='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), AiBotTeam.tAirSubteamData[oUnit:GetAIBrain().AiBotAirSubteam][AiBotTeam.reftAirRallyPoint])..'; Angle from bomber to rally='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), AiBotTeam.tAirSubteamData[oUnit:GetAIBrain().AiBotAirSubteam][AiBotTeam.reftAirRallyPoint])..'; Angle from bomber to its owners start position='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), AiBotMap.GetPlayerStartPosition(oUnit:GetAIBrain()))..'; oTargetUnit='..(oTargetUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTargetUnit) or 'nil')) end
                                    if AiBotUnitInfo.IsUnitValid(oTargetUnit) and EntityCategoryContains(categories.EXPERIMENTAL, sUnitID) then
                                        oTargetUnit[AiBotAir.refiExpBomberShotCount] = (oTargetUnit[AiBotAir.refiExpBomberShotCount] or 0) + 1
                                    end

                                    --Decide whether to retreat to air rally point or nearest base; most of the time go to rally, but switch to base if angel to rally is significantly different and has a high mod dist, in case we risk passing by enemy AA on the way
                                    local tRetreatLocation = AiBotAir.GetRetreatLocationForBomberThatJustFired(oUnit)

                                    if bDebugMessages == true then LOG(sFunctionRef..': Will try turning around to a retreat location if special micro not already active, oUnit[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                                    if not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) and AiBotUtilities.IsTableEmpty(tRetreatLocation) == false then
                                        local iTimeToTurnToRally = 15
                                        if oUnit.UnitId == 'xsa0402' then iTimeToTurnToRally = AiBotAir.GetTimeForExpBomberToTurnToRally(oUnit, oWeapon, projectile) end
                                        ForkThread(AiBotMicro.TurnAirUnitAndMoveToTarget, oUnit, tRetreatLocation, iTimeToTurnToRally, 3)
                                    end
                                end
                            end

                            --Have friendly gunships dodge
                            AiBotMicro.FriendlyGunshipsAvoidBomb(oUnit, oWeapon, projectile)
                        end
                        --T1 bombers targeting enemy ACU when not in snipe mode - consider reassigning/retreating if groundAA or AirAA threat nearby
                    elseif EntityCategoryContains(categories.TECH1 * AiBotUnitInfo.refCategoryBomber + categories.TECH2 * AiBotUnitInfo.refCategoryBomber, oUnit.UnitId) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.toActiveSnipeTargets]) then
                        local tLastOrder = oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]]
                        local oLastTarget = tLastOrder[AiBotOrders.subrefoOrderUnitTarget]
                        if AiBotUnitInfo.IsUnitValid(oLastTarget) and EntityCategoryContains(categories.COMMAND, oLastTarget.UnitId) then
                            --Check we arent close to killing the ACU
                            if oLastTarget:GetHealth() > (oLastTarget[AiBotAir.refiStrikeDamageAssigned] or 0) * 5 then
                                ForkThread(AiBotAir.ConsiderIfBomberTargetingACUShouldReassign, oUnit, oLastTarget)
                            end
                        end
                    end
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

--WARNING: OnWeaponFired and/or OnProjectilfeFired - one of these (probably the latter) resulted in error messages when t1 arti fired, disabled both of them as dont use now

function OnWeaponFired(oWeapon)
    if AiBotUtilities.bAiBotAIInGame then
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        local sFunctionRef = 'OnWeaponFired'
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if not(AiBotMap.bWaterZoneInitialCreation) then
            while GetGameTimeSeconds() < 5 do
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitTicks(1)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                if AiBotMap.bWaterZoneInitialCreation then break end
            end
        end



        if bDebugMessages == true then LOG(sFunctionRef..': Start of code; does the weapon have a valid unit='..tostring(AiBotUnitInfo.IsUnitValid(oWeapon.unit))..'; Weapon unitID='..(oWeapon.unit.UnitId or 'nil')..'; oWeapon[AiBotUnitInfo.refiLastWeaponEvent]='..(oWeapon[AiBotUnitInfo.refiLastWeaponEvent] or 'nil')..'; reprs='..reprs(oWeapon)..'; oWeapon.Label='..(oWeapon.Label or 'nil')..'; oWeapon.Blueprint.Label='..(oWeapon.Blueprint.Label or 'nil')..'; oWeapon.bp.Label='..(oWeapon.bp.Label or 'nil')..'; Time='..GetGameTimeSeconds()) end
        local oUnit = oWeapon.unit
        if oUnit and oUnit.GetUnitId and oUnit.GetAIBrain and AiBotUnitInfo.IsUnitValid(oUnit) then

            local oParentBrain = oUnit:GetAIBrain()
            --AiBot torp bomber micro (done here as want to make sure we pick up the last weapon event)
            if oParentBrain.AiBotAI then
                if EntityCategoryContains(AiBotUnitInfo.refCategoryTorpBomber, oUnit.UnitId) and not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
                    --Micro torp bombers if this is the last shot and torp only has 1 rack
                    if bDebugMessages == true then LOG(sFunctionRef..': Unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..' has just fired a shot, Time='..GetGameTimeSeconds()..'; oWeapon[AiBotUnitInfo.refiLastWeaponEvent]='..(oWeapon[AiBotUnitInfo.refiLastWeaponEvent] or 'nil')..'; is salvo data nil='..tostring(oUnit.CurrentSalvoData == nil)..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; Is unit state attacking='..tostring(oUnit:IsUnitState('Attacking'))..'; reprs of Weapon salvo data='..reprs(oWeapon.CurrentSalvoData)..'; Weapon blueprint='..reprs((oWeapon.Blueprint or oWeapon.bp))..'; Is rack size highest value='..tostring((oWeapon.CurrentRackSalvoNumber or 0) >= ((oWeapon.Blueprint or oWeapon.bp).RackSalvoSize or 0))..'; Is salvo size highest value='..tostring((oWeapon.CurrentSalvoNumber or 0) >= ((oWeapon.Blueprint or oWeapon.bp).MuzzleSalvoSize or 0))..'; oWeapon.CurrentRackSalvoNumber='..(oWeapon.CurrentRackSalvoNumber or 'nil')..'; (oWeapon.Blueprint or oWeapon.bp).RackSalvoSize='..(oWeapon.Blueprint or oWeapon.bp).RackSalvoSize..';oWeapon.CurrentSalvoNumber='..(oWeapon.CurrentSalvoNumber or 'nil')..'; Muzzle salvo size='..((oWeapon.Blueprint or oWeapon.bp).MuzzleSalvoSize or 0)) end
                    if (oWeapon.CurrentRackSalvoNumber or 0) >= ((oWeapon.Blueprint or oWeapon.bp).RackSalvoSize or 0) and (oWeapon.CurrentSalvoNumber or 0) >= ((oWeapon.Blueprint or oWeapon.bp).MuzzleSalvoSize or 0) then
                        if not(oUnit[AiBotUnitInfo.refbEasyBrain]) then
                            ForkThread(AiBotMicro.TurnAirUnitAndMoveToTarget, oUnit, AiBotTeam.tAirSubteamData[oParentBrain.AiBotAirSubteam][AiBotTeam.reftAirRallyPoint], 25, 1)
                        end
                    end
                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oUnit.UnitId) then
                    ForkThread(AiBotBuilding.ConsiderManualT2ArtiTarget, oUnit, oWeapon)
                    local iTeam = oParentBrain.AiBotTeam
                    local tLZTeamData = AiBotMap.tAllPlateaus[oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]][AiBotMap.subrefPlateauLandZones][oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]][AiBotMap.subrefLZTeamData][iTeam]
                    if tLZTeamData then tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] = GetGameTimeSeconds() end
                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oUnit.UnitId) and not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
                    --Micro asfs and inties to hover-fire at slower targets
                    if bDebugMessages == true then LOG(sFunctionRef..': Unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..' has just fired a shot, Time='..GetGameTimeSeconds()..'; oWeapon[AiBotUnitInfo.refiLastWeaponEvent]='..(oWeapon[AiBotUnitInfo.refiLastWeaponEvent] or 'nil')..'; is salvo data nil='..tostring(oUnit.CurrentSalvoData == nil)..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; Is unit state attacking='..tostring(oUnit:IsUnitState('Attacking'))..'; reprs of Weapon salvo data='..reprs(oWeapon.CurrentSalvoData)..'; reprs of weapon='..reprs(oWeapon)..'; Weapon blueprint='..reprs((oWeapon.Blueprint or oWeapon.bp))..'; Is rack size highest value='..tostring((oWeapon.CurrentRackSalvoNumber or 0) >= ((oWeapon.Blueprint or oWeapon.bp).RackSalvoSize or 0))..'; Is salvo size highest value='..tostring((oWeapon.CurrentSalvoNumber or 0) >= ((oWeapon.Blueprint or oWeapon.bp).MuzzleSalvoSize or 0))..'; oWeapon.CurrentRackSalvoNumber='..(oWeapon.CurrentRackSalvoNumber or 'nil')..'; (oWeapon.Blueprint or oWeapon.bp).RackSalvoSize='..(oWeapon.Blueprint or oWeapon.bp).RackSalvoSize..';oWeapon.CurrentSalvoNumber='..(oWeapon.CurrentSalvoNumber or 'nil')..'; Muzzle salvo size='..((oWeapon.Blueprint or oWeapon.bp).MuzzleSalvoSize or 0)) end
                    if (oWeapon.CurrentRackSalvoNumber or 0) >= ((oWeapon.Blueprint or oWeapon.bp).RackSalvoSize or 0) and (oWeapon.CurrentSalvoNumber or 0) >= ((oWeapon.Blueprint or oWeapon.bp).MuzzleSalvoSize or 0) then

                        if not(oUnit[AiBotUnitInfo.refbEasyBrain]) and not(oUnit:GetAIBrain()[AiBotMicro.refiMaxUnitsToHoverMicroAtOnce]) then --If have limit on how many units can hover-micro then want to save for bombers, not waste on 1 asf/intie
                            ForkThread(AiBotMicro.ConsiderAirAAHoverAttackTowardsTarget, oUnit, oWeapon)
                        end
                    end
                end


            end
            if bDebugMessages == true then LOG(sFunctionRef..': Time since last weapon event='..GetGameTimeSeconds() - (oWeapon[AiBotUnitInfo.refiLastWeaponEvent] or -1)) end
            if not(oWeapon[AiBotUnitInfo.refiLastWeaponEvent]) or GetGameTimeSeconds() - oWeapon[AiBotUnitInfo.refiLastWeaponEvent] >= 0.5 then
                oWeapon[AiBotUnitInfo.refiLastWeaponEvent] = GetGameTimeSeconds()
                oUnit[AiBotUnitInfo.refiLastWeaponEvent] = GetGameTimeSeconds()
                --Update unit last known position/record it
                for iTeam, tTeam in AiBotTeam.tTeamData do
                    if not(iTeam == oParentBrain.AiBotTeam) then
                        if AiBotUtilities.IsTableEmpty(tTeam[AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
                            for iBrain, oBrain in tTeam[AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                --If is AiBotEasy then only add if unit is relatively nearby
                                if not(oBrain.AiBotEasy) or EntityCategoryContains(categories.MOBILE - AiBotUnitInfo.refCategoryScathis, oUnit.UnitId) or (oUnit[AiBotUnitInfo.refiCombatRange] or 0) <= 80 then
                                    AiBotTeam.ConsiderAssigningUnitToZoneForBrain(oBrain, oUnit) --This function includes check of whether this is an AiBot brain, and updates last known position
                                    break
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti, oUnit.UnitId) then
                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] = true
                                end
                            end
                        end
                    end
                end

                --Consider dodging
                if bDebugMessages == true then LOG(sFunctionRef..': About to consider dodging logic and recording non-AiBot nuke target locations, weapon.DamageType='..(oWeapon.DamageType or 'nil')..'; (oWeapon.Blueprint or oWeapon.bp).DamageType='..((oWeapon.Blueprint or oWeapon.bp).DamageType or 'nil')..'; Weapon label='..(oWeapon.Label or 'nil')..'; reprs of oWeapon='..reprs(oWeapon)) end
                if EntityCategoryContains(AiBotUnitInfo.refCategoryBomber, oUnit.UnitId) and ((oWeapon.Label or oWeapon.Blueprint.Label or oWeapon.bp.Label) == 'GroundMissile') then
                    --Corsairs dont trigger the onbombfired event normally hence why we have this
                    if bDebugMessages == true then
                        LOG(sFunctionRef..': Weapon fired by corsair, unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit))
                        if oWeapon:GetCurrentTarget().GetPosition then LOG(sFunctionRef..': Target of weapon='..repru(oWeapon:GetCurrentTarget():GetPosition())) end
                    end
                    if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastDodgeBombEvent] or 0) >= 2 then
                        ForkThread(AiBotMicro.DodgeBomb, oUnit, oWeapon, nil)
                    end
                else
                    if EntityCategoryContains(AiBotUnitInfo.refCategorySML, oUnit.UnitId) and (oWeapon.Blueprint or oWeapon.bp).DamageType == 'Nuke' then
                        --Nuke missile fired - update the table for non-AiBot AI (AiBotAI will have recorded the target when the order was given)
                        if bDebugMessages == true then LOG(sFunctionRef..': Unit brain='..oUnit:GetAIBrain().Nickname..'; GetCurrentTarget()='..reprs(oWeapon:GetCurrentTarget())..'; GetCurrentTargetPos='..reprs(oWeapon:GetCurrentTargetPos())) end
                        if not(oUnit:GetAIBrain().AiBotAI) and oWeapon.GetCurrentTargetPos then
                            local iTeam = oUnit:GetAIBrain().AiBotTeam
                            local tCurrentTarget = oWeapon:GetCurrentTargetPos()
                            if AiBotUtilities.IsTableEmpty(tCurrentTarget) == false then
                                AiBotBuilding.RecordNukeTarget(iTeam, tCurrentTarget)
                                if bDebugMessages == true then LOG(sFunctionRef..': Target of weapon='..repru(tCurrentTarget)) end
                            end
                        end
                    end
                    --Dodge logic for certain other attacks (conditions for this are in considerdodgingshot)
                    if bDebugMessages == true then LOG(sFunctionRef..': Will consider whether we want to dodge the shot, oWeapon.unit.UnitId='..(oWeapon.unit.UnitId or 'nil')) end
                    ForkThread(AiBotMicro.ConsiderDodgingShot, oUnit, oWeapon)
                end

                --Update overcharge tracking
                if oWeapon.GetBlueprint and oWeapon.BeenDestroyed and not(oWeapon:BeenDestroyed()) and oWeapon:GetBlueprint().Overcharge then
                    if bDebugMessages == true then LOG(sFunctionRef..': Overcharge weapon has just fired') end
                    oUnit[AiBotUnitInfo.refiTimeOfLastOverchargeShot] = GetGameTimeSeconds()
                    if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) and oUnit:GetAIBrain().AiBotAI then
                        --Get another order immediately rather than waiting (means we dont have to try and queue orders up for ACU logic)
                        AiBotACU.GetACUOrder(oUnit:GetAIBrain(), oUnit)
                    end
                end

                --AiBot owned unit specific logic
                if oUnit:GetAIBrain().AiBotAI then
                    --Shot is blocked logic
                    if bDebugMessages == true then LOG(sFunctionRef..': COnsidering if unit shot is blocked Time='..GetGameTimeSeconds()..', range category='..((oWeapon.Blueprint or oWeapon.bp).RangeCategory or 'nil')..'; reprs of .RangeCategory='..reprs((oWeapon.Blueprint or oWeapon.bp).RangeCategory)..'; Is unit a relevant DF category='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryMobileDFLand + AiBotUnitInfo.refCategoryNavalSurface * categories.DIRECTFIRE + AiBotUnitInfo.refCategorySeraphimDestroyer + categories.uas0401 - AiBotUnitInfo.refCategoryMissileShip, oUnit.UnitId))..'; repr of oWeapon.Blueproint='..reprs((oWeapon.Blueprint or oWeapon.bp))) end
                    local iWeaponRangeCategory = ((oWeapon.Blueprint or oWeapon.bp).RangeCategory)
                    if (iWeaponRangeCategory == 'UWRC_DirectFire' and EntityCategoryContains(AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryMobileDFLand + AiBotUnitInfo.refCategoryCombatScout + AiBotUnitInfo.refCategoryLightAttackBot + AiBotUnitInfo.refCategoryNavalSurface * categories.DIRECTFIRE + AiBotUnitInfo.refCategorySeraphimDestroyer + categories.uas0401 - AiBotUnitInfo.refCategoryMissileShip, oUnit.UnitId)) or (iWeaponRangeCategory == 'UWRC_AntiNavy' and EntityCategoryContains(AiBotUnitInfo.refCategorySubmarine, oUnit.UnitId)) then
                        --Get weapon target if it is a DF weapon or sub torpedo
                        local oTarget
                        if oWeapon.GetCurrentTarget and not(oWeapon:BeenDestroyed()) then oTarget = oWeapon:GetCurrentTarget() end
                        if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' has just fired a shot. Do we have a valid target for our weapon='..tostring(AiBotUnitInfo.IsUnitValid(oTarget))..'; time last shot was blocked='..(oUnit[AiBotUnitInfo.refiTimeOfLastCheck] or 'nil')) end
                        if AiBotUnitInfo.IsUnitValid(oTarget) then
                            if not(oUnit[AiBotUnitInfo.refbLastShotBlocked]) then oUnit[AiBotUnitInfo.refiTimeOfLastUnblockedShot] = math.max((oUnit[AiBotUnitInfo.refiTimeOfLastCheck] or -100), (oUnit[AiBotUnitInfo.refiTimeOfLastUnblockedShot] or -100)) end
                            oUnit[AiBotUnitInfo.refiTimeOfLastCheck] = GetGameTimeSeconds()
                            oUnit[AiBotUnitInfo.refbLastShotBlocked] = AiBotLogic.IsShotBlocked(oUnit, oTarget, EntityCategoryContains(AiBotUnitInfo.refCategorySubmarine, oUnit.UnitId))
                            if bDebugMessages == true then LOG(sFunctionRef..': oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..'; Is shot blocked='..tostring(oUnit[AiBotUnitInfo.refbLastShotBlocked])..'; built in blocking terrain result for low profile='..tostring(oUnit:GetAIBrain():CheckBlockingTerrain(oUnit:GetPosition(), oTarget:GetPosition(), 'Low'))..'; High profile='..tostring(oUnit:GetAIBrain():CheckBlockingTerrain(oUnit:GetPosition(), oTarget:GetPosition(), 'High'))) end

                            if oUnit[AiBotUnitInfo.refbLastShotBlocked] then
                                --Reset after 20s if we havent fired any more shots at the target
                                --function DelayChangeVariable(oVariableOwner, sVariableName, vVariableValue, iDelayInSeconds, sOptionalOwnerConditionRef, iMustBeLessThanThisTimeValue, iMustBeMoreThanThisTimeValue, vMustNotEqualThisValue)
                                AiBotUtilities.DelayChangeVariable(oUnit, AiBotUnitInfo.refbLastShotBlocked, false, 20, AiBotUnitInfo.refiTimeOfLastCheck, GetGameTimeSeconds() + 0.01)
                                --Increase shot blocked count if this is a longer ranged naval unit firing at a structure
                                if oUnit[AiBotUnitInfo.refiCombatRange] > 50 and EntityCategoryContains(AiBotUnitInfo.refCategoryNavalSurface, oUnit.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oTarget.UnitId) then
                                    oTarget[AiBotUnitInfo.refiTargetShotBlockedCount] = (oTarget[AiBotUnitInfo.refiTargetShotBlockedCount] or 0) + 1
                                end
                                --PD - consider manual control
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryPD, oUnit.UnitId) then
                                    ForkThread(AiBotBuilding.GetManualPDTarget, oUnit, oTarget)
                                end
                            elseif oUnit[AiBotUnitInfo.refiCombatRange] > 50 and EntityCategoryContains(AiBotUnitInfo.refCategoryNavalSurface, oUnit.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oTarget.UnitId) then
                                oTarget[AiBotUnitInfo.refiTargetShotBlockedCount] = 0
                            end
                        end
                        if EntityCategoryContains(AiBotUnitInfo.refCategorySMD, oUnit.UnitId) then
                            if (oUnit.GetNukeSiloAmmoCount and oUnit:GetNukeSiloAmmoCount() >= 1) or (oUnit.GetTacticalSiloAmmoCount and oUnit:GetTacticalSiloAmmoCount() >= 1) then
                                oUnit[AiBotUnitInfo.refiTimeOfLastCheck] = GetGameTimeSeconds() - 240 - AiBotBuilding.iTimeForSMDToBeConstructed
                            else
                                oUnit[AiBotUnitInfo.refiTimeOfLastCheck] = GetGameTimeSeconds() - AiBotBuilding.iTimeForSMDToBeConstructed --For an SMD this will effectively mean we think the SMD isnt loaded anymore; below acts as a basic check to approximate scenarios where SMD has been around a while (ideally if improving on this would just use a dif variable to refiTimeOfLastCheck so can track the actual values wanted)
                            end
                            --If this was an Aeon SMD owned by vendetta personality then send voice taunt
                            if oUnit:GetAIBrain()[AiBotChat.refiAssignedPersonality] == AiBotChat.refiVendetta and (AiBotOrders.bDontConsiderCombinedArmy or oUnit.AiBotActive) then
                                ForkThread(AiBotChat.SendMessage, oUnit:GetAIBrain(), 'VendettaSMD', LOC('<LOC X06_T01_560_010>[{i Vendetta}]: Nice try.'), 1, 600, false, true, 'X06_Vedetta_T01_03018', 'X06_VO')
                            end
                        end
                    end
                    --T3 arti targeting logic; TML missile tracking
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti, oUnit.UnitId) then
                        ForkThread(AiBotBuilding.GetT3ArtiTarget, oUnit)
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oUnit.UnitId) then
                        if AiBotUnitInfo.IsUnitValid(oUnit[AiBotBuilding.refoLastTMLTarget]) then
                            oUnit[AiBotBuilding.refoLastTMLTarget][AiBotBuilding.refiTimeOfLastLaunch] = GetGameTimeSeconds()
                            if bDebugMessages == true then LOG(sFunctionRef..': have set time of last launch to '..oUnit[AiBotBuilding.refoLastTMLTarget][AiBotBuilding.refiTimeOfLastLaunch]..' for target '..oUnit[AiBotBuilding.refoLastTMLTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit[AiBotBuilding.refoLastTMLTarget])) end
                        end
                    end
                    --SML, TML and SMD - unpause (if paused)
                    if EntityCategoryContains(AiBotUnitInfo.refCategorySML + AiBotUnitInfo.refCategorySMD + AiBotUnitInfo.refCategoryTML, oUnit.UnitId) then
                        AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oUnit, false)
                        --TML and nuke - consider launching missile if have any remaining
                        ForkThread(AiBotBuilding.JustFiredMissile, oUnit)
                    end

                    --Naval bombardment units in campaign that cant path through a pond
                    if AiBotMap.bIsCampaignMap and oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][oUnit:GetAIBrain().AiBotTeam] and EntityCategoryContains(AiBotUnitInfo.refCategoryBombardment, oUnit.UnitId) then
                        local iTeam = oUnit:GetAIBrain().AiBotTeam
                        local iWZ = oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam]
                        local iPond = AiBotMap.tiPondByWaterZone[iWZ]
                        AiBotMap.tPondDetails[iPond][AiBotMap.refiCampaignLastBombardmentWeaponFired] = GetGameTimeSeconds()
                    end
                end

                --T2 bombers - call OnBombFired event (doesnt fire properly normally since it fires missiles)
                if (oUnit.UnitId == 'dra0202' or (not(AiBotUtilities.bFAFActive) and (oWeapon.Label or oWeapon.Blueprint.Label or oWeapon.bp.Label) == 'Bomb')) and (not(oUnit[AiBotUnitInfo.refiLastBombFired]) or GetGameTimeSeconds() - oUnit[AiBotUnitInfo.refiLastBombFired] > 0.1) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will call onbombfired as a redundancy') end
                    OnBombFired(oWeapon, nil, oUnit.UnitId == 'dra0202')
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

    end
end

