function ProjectileFiredAtGunship(oTarget, oProjectile)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ProjectileFiredAtGunship'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(oTarget[AiBotUnitInfo.reftoEnemyProjectiles]) then
        oTarget[AiBotUnitInfo.reftoEnemyProjectiles] = {}
    end
    table.insert(oTarget[AiBotUnitInfo.reftoEnemyProjectiles], oProjectile)
    --Estimate total damage to be dealt
    local iTotalDamage = 0
    for iCurProjectile = table.getn(oTarget[AiBotUnitInfo.reftoEnemyProjectiles]), 1, -1 do
        local oCurProjectile = oTarget[AiBotUnitInfo.reftoEnemyProjectiles][iCurProjectile]
        if oCurProjectile:BeenDestroyed() then
            table.remove(oTarget[AiBotUnitInfo.reftoEnemyProjectiles], iCurProjectile)
        else
            iTotalDamage = iTotalDamage + (oCurProjectile.DamageData.DamageAmount or 'nil')
        end
    end

    local iCurHealth = oTarget:GetHealth()
    local iMaxHealth = oTarget:GetMaxHealth()
    if (iCurHealth - iTotalDamage) <= iMaxHealth * AiBotAir.GetHealthRunThreshold(iMaxHealth, oTarget) then

        oTarget[AiBotUnitInfo.refbProjectilesMeanShouldRefuel] = true
        if oTarget[AiBotAir.reftGunshipSpecialRallyPathing][AiBotAir.subrefLastRecordedZone] then
            if bDebugMessages == true then LOG(sFunctionRef..': Gunship '..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..' is already retreating') end
        else
            AiBotAir.SendUnitsForRefueling({ oTarget }, oTarget:GetAIBrain().AiBotTeam, oTarget:GetAIBrain().AiBotAirSubteam, true)
            if bDebugMessages == true then LOG(sFunctionRef..'; sent gunship '..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..' for refueling') end
        end
    end

    --LOG('TEMP oProjectile targeting gunship reprs='..reprs(oProjectile)..'; reprs of damage data='..reprs(oProjectile.DamageData)..'; damageData.DamageAmount='..(oProjectile.DamageData.DamageAmount or 'nil'))
    if bDebugMessages == true then LOG(sFunctionRef..': projectile target='..(oTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTarget) or 'nil')..'; Cur projectile damage='..(oProjectile.DamageData.DamageAmount or 'nil')..'; iTotalDamage='..iTotalDamage..'; iCurHealth='..iCurHealth..'; iMaxHealth='..iMaxHealth..'; oTarget[AiBotUnitInfo.refbProjectilesMeanShouldRefuel]='..tostring(oTarget[AiBotUnitInfo.refbProjectilesMeanShouldRefuel] or false)..'; Time='..GetGameTimeSeconds()) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ProjectileCreated(oProjectile, inWater)
    --LOG('TEMPCODE projectile created, oProjectile.Launcher.UnitId='..(oProjectile.Launcher.UnitId or 'nil')..'; Is .Launcher nil='..tostring(oProjectile.Launcher == nil)..'; .GetLauncher is nil='..tostring(oProjectile.GetLauncher == nil)..';  oProjectile.BeenDestroyed is nil='..tostring( oProjectile.BeenDestroyed == nil))
    --[[if oProjectile.GetCurrentTargetPosition then
        LOG('TEMPCODE will draw projectile created target')
        AiBotUtilities.DrawLocation(oProjectile:GetCurrentTargetPosition(), 2)
    end--]]
    if oProjectile.BeenDestroyed and not(oProjectile:BeenDestroyed()) and (not(AiBotMap.bIsCampaignMap) or GetGameTimeSeconds() >= 300 or not(ScenarioInfo.OpEnded)) then
        local bTrackingProjectile = false
        --LOG('TEMPCODE GetTrackingTarget=nil='..tostring(oProjectile.GetTrackingTarget == nil))
        if oProjectile.GetTrackingTarget then
            local oTarget = oProjectile:GetTrackingTarget()
            --AiBot target specific logic:
            --LOG('TEMPCODE oTarget='..(oTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTarget) or 'nil'))
            if AiBotUnitInfo.IsUnitValid(oTarget) then
                bTrackingProjectile = true
                if oTarget:GetAIBrain().AiBotAI and not(oTarget[AiBotUnitInfo.refbEasyBrain]) then
                    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
                    local sFunctionRef = 'ProjectileCreated'
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

                    --Gunships - consider retreating early
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryGunship - categories.CANNOTUSEAIRSTAGING, oTarget.UnitId) and not(oTarget.MyShield) and not(oTarget[AiBotUnitInfo.refbProjectilesMeanShouldRefuel]) then
                        ProjectileFiredAtGunship(oTarget, oProjectile)
                    end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                end
            end
        end
        if not(bTrackingProjectile) then
            --LOG('TEMPCODE reprs of oProjectile='..reprs(oProjectile)..'; reprs of oProjectile.Launcher='..reprs(oProjectile.Launcher)..'; oProjectile.InnerRing is nil='..tostring(oProjectile.InnerRing == nil)..'; oProjectile.OuterRing is nil='..tostring(oProjectile.OuterRing == nil)..'; Is launcher a nuke='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategorySML, oProjectile.Launcher.UnitId)))
            --Gunship related
            if oProjectile.OriginalTarget then
                local oTarget = oProjectile.OriginalTarget
                if AiBotUnitInfo.IsUnitValid(oTarget) and oTarget:GetAIBrain().AiBotAI and not(oTarget[AiBotUnitInfo.refbEasyBrain]) then
                    --Gunships - consider retreating early
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryGunship - categories.CANNOTUSEAIRSTAGING, oTarget.UnitId) and not(oTarget.MyShield) and not(oTarget[AiBotUnitInfo.refbProjectilesMeanShouldRefuel]) then
                        ProjectileFiredAtGunship(oTarget, oProjectile)
                    end
                end
            end

            if not(oProjectile.Launcher) and not(AiBotUtilities.bFAFActive) and oProjectile.GetLauncher then
                oProjectile.Launcher = oProjectile:GetLauncher()
                --Consider adding inner and outer rings if this is a nuke launcher
                if oProjectile.Launcher.UnitId and EntityCategoryContains(AiBotUnitInfo.refCategorySML, oProjectile.Launcher.UnitId) and not(oProjectile.InnerRing) then
                    --Battleship exception - if target isnt far away assume we are dealing with normal battleship weapon
                    local bIncludeNukeRings = true
                    if oProjectile.Launcher[AiBotUnitInfo.refiDFRange] and oProjectile.GetCurrentTargetPosition then
                        local tTarget = oProjectile:GetCurrentTargetPosition()
                        if AiBotUtilities.IsTableEmpty(tTarget) == false and AiBotUtilities.GetDistanceBetweenPositions(tTarget, oProjectile.Launcher:GetPosition()) <= oProjectile.Launcher[AiBotUnitInfo.refiDFRange] + 5 then
                            bIncludeNukeRings = false
                        end
                    end
                    if bIncludeNukeRings then
                        local oLauncherBP = oProjectile.Launcher:GetBlueprint()
                        if oLauncherBP.Weapon then
                            for iWeapon, tWeapon in oLauncherBP.Weapon do
                                if tWeapon.NukeInnerRingRadius then
                                    --LOG('TEMPCODE setting nuke inner and outer radius')
                                    oProjectile.InnerRing = tWeapon.NukeInnerRingRadius
                                    oProjectile.OuterRing = (tWeapon.NukeOuterRingRadius or 40)
                                    break
                                end
                            end
                        end
                    else
                    end
                end
            end
            if oProjectile.Launcher.UnitId and oProjectile.InnerRing and oProjectile.OuterRing and EntityCategoryContains(AiBotUnitInfo.refCategorySML, oProjectile.Launcher.UnitId) then
                --Have a nuke missile that has just been fired
                local oLauncher = oProjectile.Launcher
                --LOG('Is launcher valid='..tostring(AiBotUnitInfo.IsUnitValid(oLauncher)))
                if AiBotUnitInfo.IsUnitValid(oLauncher) then
                    local iTeam = oLauncher:GetAIBrain().AiBotTeam
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                        ForkThread(AiBotMicro.KeepUnitsAwayFromNukeOrTMLTarget, oProjectile, oLauncher, iTeam)
                    end
                    --Start a threat for each team with AiBot in that isnt an ally to check if we have visual of the missile
                    for iCurTeam = 1, AiBotTeam.iTotalTeamCount do
                        if not(iCurTeam == iTeam) and AiBotTeam.tTeamData[iCurTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                            ForkThread(AiBotMicro.MonitorEnemyNukeOrTMLMissileForIntel, oProjectile, iCurTeam)
                        end
                    end
                end
                --All TML targeting (for dodging shots once see missile)
            elseif oProjectile.Launcher.UnitId and oProjectile.CreatedByWeapon.Blueprint.DamageRadius and EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oProjectile.Launcher.UnitId) then
                local iTeam = (oProjectile.CreatedByWeapon.Brain.AiBotTeam or AiBotOverseer.tAllAIBrainsByArmyIndex[oProjectile.Army].AiBotTeam)
                if iTeam then
                    for iCurTeam = 1, AiBotTeam.iTotalTeamCount do
                        if not(iCurTeam == iTeam) and AiBotTeam.tTeamData[iCurTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                            ForkThread(AiBotMicro.MonitorEnemyNukeOrTMLMissileForIntel, oProjectile, iCurTeam)
                        end
                    end
                end

            end
            --AiBot specific TML targeting
            if oProjectile.Launcher.UnitId and oProjectile.Launcher[AiBotBuilding.refoLastTMLTarget] and EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oProjectile.Launcher.UnitId) then
                local oLauncher = oProjectile.Launcher
                if AiBotUnitInfo.IsUnitValid(oLauncher) and oLauncher:GetAIBrain().AiBotAI then
                    --Track the missile target against the projectile
                    oProjectile[AiBotBuilding.refoLastTMLTarget] = oLauncher[AiBotBuilding.refoLastTMLTarget]
                end
            end
        end
    end
end

