function OnMissileBuilt(self, weapon)
    if AiBotUtilities.bAiBotAIInGame then
        if self.GetAIBrain and self:GetAIBrain().AiBotAI then
            local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
            local sFunctionRef = 'OnMissileBuilt'
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

            self[AiBotBuilding.refbMissileRecentlyBuilt] = true
            AiBotUtilities.DelayChangeVariable(self, AiBotBuilding.refbMissileRecentlyBuilt, false, 5)


            --Pause if we already have 2 missiles (mroe if smd and enemy has nukes)
            if bDebugMessages == true then
                if AiBotUnitInfo.IsUnitValid(self) then
                    LOG(sFunctionRef..': Have valid unit='..self.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(self))
                else
                    LOG(sFunctionRef..': self='..reprs(self))
                end
            end

            local iMissiles = 1 --For some reason the count is off by 1, presumably a slight delay between the event being called and the below ammo counts working
            if self.GetTacticalSiloAmmoCount then iMissiles = iMissiles + self:GetTacticalSiloAmmoCount() end
            if bDebugMessages == true then LOG(sFunctionRef..': iMissiles based on tactical silo ammo='..iMissiles) end
            if self.GetNukeSiloAmmoCount then iMissiles = iMissiles + self:GetNukeSiloAmmoCount() end
            if bDebugMessages == true then LOG(sFunctionRef..': iMissiles after Nuke silo ammo='..iMissiles) end
            if iMissiles >= 1 then
                --Stop assisting units (so can reassess if we still want to assist)
                if AiBotUtilities.IsTableEmpty(self[AiBotUnitInfo.reftoUnitsAssistingThis]) == false then
                    local tEngineersToStop = {}
                    for iEngineer, oEngineer in self[AiBotUnitInfo.reftoUnitsAssistingThis] do
                        table.insert(tEngineersToStop, oEngineer)
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to make engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to stop assisting') end
                    end
                    for iEngineer, oEngineer in tEngineersToStop do
                        if AiBotUnitInfo.IsUnitValid(oEngineer) then
                            AiBotOrders.IssueTrackedClearCommands(oEngineer)
                            if bDebugMessages == true then LOG(sFunctionRef..': Just sent a clear order to '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to stop assisting') end
                        end
                    end
                end
                --SMD - use specical function to assess if have too many missiles
                local bPauseMissile
                if EntityCategoryContains(AiBotUnitInfo.refCategorySMD, self.UnitId) then
                    bPauseMissile = AiBotConditions.WantToPauseSMD(self, true)
                    --Do we have any SMD without missiles, and no yolona on the team? If so then change the flag about needing resources for missiles
                    local bHaveSMDOrSMLNeedingMissiles = false
                    local iTeam = self:GetAIBrain().AiBotTeam
                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                        if oBrain:GetCurrentUnits(AiBotUnitInfo.refCategorySML) > 0 then
                            bHaveSMDOrSMLNeedingMissiles = true
                            break
                        else
                            local tSMD = oBrain:GetListOfUnits(AiBotUnitInfo.refCategorySMD, false, true)
                            if AiBotUtilities.IsTableEmpty(tSMD) == false then
                                for iSMD, oSMD in tSMD do
                                    if not(oSMD == self) then
                                        if oSMD:GetFractionComplete() < 1 or ((not(oSMD.GetNukeSIloAmmoCount) or oSMD:GetNukeSiloAmmoCount() == 0) and (not(oSMD.GetTacticalSiloAmmoCount) or oSMD:GetTacticalSiloAmmoCount() == 0)) then
                                            bHaveSMDOrSMLNeedingMissiles = true
                                            break
                                        end
                                    end
                                end
                                if bHaveSMDOrSMLNeedingMissiles then break end
                            end
                        end
                    end
                    if not(bHaveSMDOrSMLNeedingMissiles) then
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNeedResourcesForMissile] = false
                    end
                else
                    --Nuke launcher - If 2+ missiles then pause, and consider unpausing later
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy nuke launchers empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[self:GetAIBrain().AiBotTeam][AiBotTeam.reftEnemyNukeLaunchers]))..'; Have low power='..tostring(AiBotConditions.HaveLowPower(self:GetAIBrain().AiBotTeam))..'; Gross mass='..AiBotTeam.tTeamData[self:GetAIBrain().AiBotTeam][AiBotTeam.subrefiTeamGrossMass]..'; Mass % stored='..AiBotTeam.tTeamData[self:GetAIBrain().AiBotTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]) end
                    if iMissiles >= 2 and not(EntityCategoryContains(categories.EXPERIMENTAL, self.UnitId)) then
                        local iTeam = self:GetAIBrain().AiBotTeam
                        --Dont pause if overflowing
                        if AiBotConditions.HaveLowPower(iTeam) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 400 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.8 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 30 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 25 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.99))) then
                            bPauseMissile = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Have at least 2 missiles so will set paused to true on unit '..self.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(self)) end
                        end
                    end
                end
                if bPauseMissile then
                    --self:SetPaused(true)
                    AiBotUnitInfo.PauseOrUnpauseUnitWithoutTracking(self, true)
                    AiBotUnitInfo.SetUnitMissileAutoBuildStatus(self, false)
                    --if self.SetAutoMode then self:SetAutoMode(false) end

                    --Recheck every 10s
                    ForkThread(AiBotBuilding.CheckIfWantToBuildAnotherMissile, self)
                end
            end

            if not(EntityCategoryContains(AiBotUnitInfo.refCategorySMD, self.UnitId)) then
                if bDebugMessages == true then LOG(sFunctionRef..': Calling logic to consider launching a missile') end
                --LOG('Forked consideration of launching missile 6')
                ForkThread(AiBotBuilding.ConsiderLaunchingMissile, self, weapon)
            end
        end

    end
end

--[[
function OnProjectileFired(oWeapon, oMuzzle)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'OnProjectileFired'
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code') end
    if oWeapon.GetBlueprint then
        LOG('OnWeaponFired hook for blueprint='..repru(oWeapon:GetBlueprint()))
    end
    if oWeapon.unit then
        LOG('Have a unit; unit position='..repru(oWeapon.unit:GetPosition()))
    end
end--]]

function OnConstructionStarted(oEngineer, oConstruction, sOrder)
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'OnConstructionStarted'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        if not(oConstruction.UnitId) then --LOUD compatibility redundancy (OnCreate should also do this)
            if not(AiBotUtilities.bFAFActive) then
                if not(oConstruction.EntityId) then oConstruction.EntityId = oConstruction:GetEntityId() end
                oConstruction.UnitId = oConstruction:GetBlueprint().BlueprintId
            end
        end



        --Update land zone queued orders
        if AiBotUtilities.IsTableEmpty(oEngineer[AiBotEngineer.reftQueuedBuildings]) == false then
            AiBotEngineer.RemoveBuildingFromQueuedBuildings(oEngineer, oConstruction)
        end

        --Both AiBot and non-AiBot:
        if not(oConstruction[AiBotUnitInfo.refbConstructionStart]) then
            --Construction is being done of a building, by a building
            if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oConstruction.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oEngineer.UnitId) then
                --Mex and hydro upgrade tracking redundancy if not FAF
                if not(AiBotUtilities.bFAFActive) and EntityCategoryContains(AiBotUnitInfo.refCategoryHydro + AiBotUnitInfo.refCategoryMex, oConstruction.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryHydro + AiBotUnitInfo.refCategoryMex, oEngineer.UnitId) then
                    oConstruction.IsUpgrade = true
                end

                --Intel approximation - a human player would be able to infer that if they'd scouted a mex and now it is greyed out, that means the opponent has upgraded it; so it is reasonable for the AI to be given the same information
                local iConstructionTeam = oConstruction:GetAIBrain().AiBotTeam
                for iTeam = 1, AiBotTeam.iTotalTeamCount, 1 do
                    if not(iTeam == iConstructionTeam) and oEngineer[AiBotUnitInfo.reftbConsideredForAssignmentByTeam][iTeam] then
                        local oFirstAiBotBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                        if oFirstAiBotBrain then
                            AiBotTeam.AssignUnitToLandZoneOrPond(oFirstAiBotBrain, oConstruction, false, false, true)
                        end
                    end
                end
            end
            --Has enemy started on a nuke, not under stealth, in their main base? such that as a player we would likely be scouting for such a unit periodically? If so then flag to try scouting
            if EntityCategoryContains(AiBotUnitInfo.refCategorySML, oConstruction.UnitId) then
                for iTeam = 1, AiBotTeam.iTotalTeamCount, 1 do
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                        local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                        if not(AiBotUnitInfo.CanSeeUnit(aiBrain, oConstruction, true)) then
                            --Is nuke close to enemy base?
                            local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oConstruction:GetPosition(), true, iTeam)
                            if AiBotUtilities.GetDistanceBetweenPositions(oConstruction:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase]) <= 180 then
                                --Check not under stealth (cybran is 32 radius)
                                local oEnemyBrain = oConstruction:GetAIBrain()
                                local tNearbyStealth = oEnemyBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryStealthGenerator + AiBotUnitInfo.refCategoryMobileLandStealth, oConstruction:GetPosition(), 32, 'Ally')
                                if AiBotUtilities.IsTableEmpty(tNearbyStealth) then
                                    AiBotAir.AddUnitWantingPriorityScout(oConstruction, false, aiBrain.AiBotAirSubteam)
                                end
                            end
                        end
                    end
                end
            end
        end


        --AiBot specific
        if oEngineer:GetAIBrain().AiBotAI then
            --Stuff to update every time construction starts
            if oEngineer[AiBotBuilding.reftArtiTemplateRefs] then oEngineer[AiBotConditions.refiEngineerStuckCheckCount] = 0 end
            if oEngineer[AiBotOrders.refiMoveAndBuildStuckCount] then oEngineer[AiBotOrders.refiMoveAndBuildStuckCount] = 0 end
            if oConstruction.GetUnitId and not(oConstruction[AiBotUnitInfo.refbConstructionStart]) then
                oConstruction[AiBotUnitInfo.refbConstructionStart] = true
                --Enable AiBotActive status if the engineer is active and we have set to inherit
                if not(AiBotOrders.bDontConsiderCombinedArmy) and (oEngineer.AiBotActive or (oEngineer.Parent and oEngineer.Parent.AiBotActive and EntityCategoryContains(categories.EXTERNALFACTORYUNIT, oEngineer.UnitId))) and oEngineer:GetAIBrain().BrainType == 'Human' and tonumber(ScenarioInfo.Options.AiBotCAInherit or 2) == 1 and not(oConstruction.AiBotActive) and not(tonumber(ScenarioInfo.Options.AiBotCombinedArmy or 2) == 3) and not(tonumber(ScenarioInfo.Options.AiBotCombinedArmy or 2) == 4) then
                    oConstruction.AiBotActive = true
                    oConstruction:UpdateStat('AiBotActive', 1)
                end

                if bDebugMessages == true then
                    --local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oConstruction:GetPosition()) --decided not to include due to worry this might desync replays
                    LOG(sFunctionRef..': Construction just started by AiBot engineer belonging to '..oEngineer:GetAIBrain().Nickname..' on oConstruction='..oConstruction.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oConstruction)..'; postiion='..repru(oConstruction:GetPosition())..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; oEngineer[AiBotBuilding.reftArtiTemplateRefs]='..repru(oEngineer[AiBotBuilding.reftArtiTemplateRefs])..'; Engi action (if any)='..(oEngineer[AiBotEngineer.refiAssignedAction] or 'nil')..'; Parent='..(oEngineer.Parent.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineer.Parent) or 'nil')..'; time='..GetGameTimeSeconds())
                end
                --Record any mexes so we can repair them if construction gets interrupted
                if EntityCategoryContains(AiBotUnitInfo.refCategoryT1Mex, oConstruction.UnitId) then
                    AiBotEngineer.RecordPartBuiltMex(oEngineer, oConstruction)
                end

                --Track special game ender logic buildings
                if oEngineer[AiBotBuilding.reftArtiTemplateRefs] then
                    if bDebugMessages == true then LOG(sFunctionRef..': We have construction being built by engi with arti template ref, so will copy over engineer arti template ref, oEngineer[AiBotBuilding.reftArtiTemplateRefs]='..repru(oEngineer[AiBotBuilding.reftArtiTemplateRefs])) end
                    oConstruction[AiBotBuilding.reftArtiTemplateRefs] =  {oEngineer[AiBotBuilding.reftArtiTemplateRefs][1], oEngineer[AiBotBuilding.reftArtiTemplateRefs][2], oEngineer[AiBotBuilding.reftArtiTemplateRefs][3]}

                    local tLZTeamData = AiBotMap.tAllPlateaus[oEngineer[AiBotBuilding.reftArtiTemplateRefs][1]][AiBotMap.subrefPlateauLandZones][oEngineer[AiBotBuilding.reftArtiTemplateRefs][2]][AiBotMap.subrefLZTeamData][oConstruction:GetAIBrain().AiBotTeam]
                    if tLZTeamData then
                        if bDebugMessages == true then
                            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oConstruction:GetPosition())
                            LOG(sFunctionRef..': Arti template recording of unit where construction started; engineer template ref='..repru(oEngineer[AiBotBuilding.reftArtiTemplateRefs])..'; Is table of active game ender templates for this ref empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][oEngineer[AiBotBuilding.reftArtiTemplateRefs]]))..'; Is tLZTeamData[AiBotMap.reftActiveGameEnderTemplates] empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates]))..'; Construction plateau='..(iPlateau or 'nil')..'; LZ='..(iLandZone or 'nil')..'; Engineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; oConstruction='..oConstruction.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oConstruction))
                        end
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oConstruction.UnitId) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Have started fixed shield so will add to table of shields for this reference') end
                            local tTemplateRef = tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][oEngineer[AiBotBuilding.reftArtiTemplateRefs][3]]
                            --Check shield isn't already recorded
                            local bAlreadyRecorded = false
                            if AiBotUtilities.IsTableEmpty(tTemplateRef[AiBotMap.subrefGEShieldUnits]) == false then
                                for iRecordedShield, oRecordedShield in tTemplateRef[AiBotMap.subrefGEShieldUnits] do
                                    if oRecordedShield == oConstruction then
                                        bAlreadyRecorded = true
                                        break
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': bAlreadyRecorded='..tostring(bAlreadyRecorded)) end
                            if not(bAlreadyRecorded) then
                                table.insert(tTemplateRef[AiBotMap.subrefGEShieldUnits], oConstruction)
                                if bDebugMessages == true then LOG(sFunctionRef..': Added unit to table of shield units') end
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Wont record shield '..oConstruction.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oConstruction)..' against arti template as it was already recorded') end
                            end

                            --Check if we no longer need special faction engineers
                            if AiBotUtilities.IsTableEmpty(tTemplateRef[AiBotMap.subrefGEArtiUnits]) == false and table.getn(tTemplateRef[AiBotMap.subrefGEShieldUnits]) >= math.min(7, table.getn(tTemplateRef[AiBotMap.subrefGEShieldLocations])) then
                                for iArti, oArti in tTemplateRef[AiBotMap.subrefGEArtiUnits] do
                                    if oArti[AiBotBuilding.refoNearbyFactoryOfFaction] then
                                        AiBotBuilding.UnitNoLongerRequiresFactoryFactionShieldEngineers(oArti)
                                    end
                                end
                            end
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oConstruction.UnitId) then
                            local tTemplateRef = tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][oEngineer[AiBotBuilding.reftArtiTemplateRefs][3]]
                            local bAlreadyRecorded = false
                            if AiBotUtilities.IsTableEmpty(tTemplateRef[AiBotMap.subrefGEArtiUnits]) == false then
                                for iRecordedArti, oRecordedArti in tTemplateRef[AiBotMap.subrefGEArtiUnits] do
                                    if oRecordedArti == oConstruction then
                                        bAlreadyRecorded = true
                                        break
                                    end
                                end
                            end
                            if not(bAlreadyRecorded) then
                                --Check this isn't a mobile non-scathis unit
                                if not(EntityCategoryContains(categories.MOBILE, oConstruction.UnitId)) or AiBotUnitInfo.GetBlueprintMaxGroundRange(oConstruction:GetBlueprint()) >= 500 then
                                    table.insert(tTemplateRef[AiBotMap.subrefGEArtiUnits], oConstruction)
                                elseif bDebugMessages == true then LOG(sFunctionRef..': We have constructed a mobile unit with a short range so wont record as an arti unit')
                                end
                            end
                            tTemplateRef[AiBotMap.subrefbFailedToGetArtiLocation] = false
                            if bDebugMessages == true then LOG(sFunctionRef..': Have started experimental type unit so will add to table of arti for this reference, oConstruction='..oConstruction.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oConstruction)..'; bAlreadyRecorded='..tostring(bAlreadyRecorded)) end
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategorySMD, oConstruction.UnitId) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Have started SMD unit so will add to table of SMD for this reference') end
                            tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][oEngineer[AiBotBuilding.reftArtiTemplateRefs][3]][AiBotMap.subrefGESMDUnit] = oConstruction
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryGroundAA + AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryPD, oConstruction.UnitId) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Just started on AA/SAM/PD/T2 arti unit so will add to table of defences for this reference') end
                            if not(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][oEngineer[AiBotBuilding.reftArtiTemplateRefs][3]][AiBotMap.subrefGEDefenceUnits]) then tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][oEngineer[AiBotBuilding.reftArtiTemplateRefs][3]][AiBotMap.subrefGEDefenceUnits] = {} end
                            table.insert(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][oEngineer[AiBotBuilding.reftArtiTemplateRefs][3]][AiBotMap.subrefGEDefenceUnits], oConstruction)
                        else
                            AiBotUtilities.ErrorHandler('Engineer has just started construction on a unit that isnt one we would expect to be built for gameender template logic, Unit='..(oConstruction.UnitId or 'nil')..'; Engineer action='..(oEngineer[AiBotEngineer.refiAssignedAction] or 'nil')..'; Engineer='..(oEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineer) or 'nil'))
                            oConstruction[AiBotBuilding.reftArtiTemplateRefs] = nil
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryFactory + categories.EXTERNALFACTORYUNIT, oEngineer.UnitId) then oEngineer[AiBotBuilding.reftArtiTemplateRefs] = nil end
                            if bDebugMessages == true then LOG(sFunctionRef..': Engi starting unexpected category, oEngineer='..(oEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineer) or 'nil')..'; Brain='..oEngineer:GetAIBrain().Nickname..'; index='..oEngineer:GetAIBrain():GetArmyIndex()) end
                        end
                    else AiBotUtilities.ErrorHandler('Started building a unit for arti template but it isnt in a zone')
                    end
                end

                --Decide if want to shield this construction and update buildable location, or (in the case of experimentals) if we want to cancel the construction
                if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryExperimentalLevel, oConstruction.UnitId) then
                    local bCancelBuilding = false
                    --LOUD specific - cant build resource gens near each other
                    if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and EntityCategoryContains(categories.EXPERIMENTAL * categories.MASSFABRICATION, oConstruction.UnitId) then
                        ForkThread(AiBotBuilding.RecordExperimentalResourceGen, oConstruction)
                    end
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti, oConstruction.UnitId) and not(oConstruction[AiBotBuilding.reftArtiTemplateRefs]) and not(oEngineer[AiBotBuilding.reftArtiTemplateRefs]) then
                        local iTeam = oEngineer:GetAIBrain().AiBotTeam
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.9 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] < 3 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] < 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.6)) then
                            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oConstruction:GetPosition())
                            if iPlateau > 0 and (iLandZone or 0) > 0 then
                                --NOTE: If changing above thresholds then consider also changing AiBotEngineer ConsiderActionToAssign threshold (want above to be less likely to trigger to avoid constant loop of starting and cancelling)
                                local iSearchRange = math.max(175, 450 - AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) --(slightly further search range than the AiBotEngineer approach)
                                local iSearchCategory = nil --means will search for everything
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder, oConstruction.UnitId) then iSearchCategory = AiBotUnitInfo.refCategoryGameEnder
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti, oConstruction.UnitId) then iSearchCategory = AiBotUnitInfo.refCategoryFixedT3Arti
                                else
                                    --Search for all experimentals  (so leave as nil) - however given the above restriction this is more for redundancy as would only expect to be here if are building game ender or t3 arti
                                end
                                local bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete = AiBotEngineer.GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandZone, true, iSearchRange, iSearchCategory)
                                if iMassToComplete >= math.max(17500, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] * 1.3) then
                                    --Estimate how long it will take to complete if we manage to spend 40% of gross mass on existing experimentals
                                    if (iMassToComplete - AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]) / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 0.4 > 40 then
                                        bCancelBuilding = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Want to cancel construction that we just started, iMassToComplete='..iMassToComplete..'; Mass stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) end
                                    end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': bCancelBuilding='..tostring(bCancelBuilding)) end
                    if bCancelBuilding then
                        --Clear all engineeres trying to build this
                        AiBotEngineer.ClearEngineersBuildingUnit(oEngineer, oConstruction)
                        --Tell the engi that just constructed to reclaim
                        AiBotOrders.IssueTrackedReclaim(oEngineer, oConstruction, false, 'AbrtNRec', true)
                        if bDebugMessages == true then LOG(sFunctionRef..': Have told engineer to abort consturction of '..oConstruction.UnitId..' and to reclaim it instead') end
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Engineer that is starting this construction='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; oEngineer[AiBotEngineer.refiAssignedAction]='..(oEngineer[AiBotEngineer.refiAssignedAction] or 'nil')) end
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oConstruction.UnitId) then
                            local iTeam = oConstruction:GetAIBrain().AiBotTeam
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to cancel experimental queued in other zones, bCancelBuilding='..tostring(bCancelBuilding)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]..'; Mass stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; Team has low mass='..tostring(AiBotConditions.TeamHasLowMass(iTeam))) end
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] < 20000 and AiBotConditions.TeamHasLowMass(iTeam) then
                                --If dont have an experimental constructed yet then when we start our first exp go through each other zone with engineers trying to build an experimental and clear the engineers if we have low mass and the engineers havent started building yet
                                local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oConstruction:GetPosition())
                                if iPlateau > 0 and iLandZone > 0 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will consider cancelling other queued engineer construction if there is any; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]) end
                                    AiBotEngineer.GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandZone, false, nil, nil, true, nil, oConstruction:GetAIBrain().AiBotAirSubteam)
                                end
                            end
                        end

                        --Game ender and T3 arti specific - reserve locations for shields
                        if bDebugMessages == true then LOG(sFunctionRef..': is oConstruction[AiBotBuilding.reftArtiTemplateRefs] nil='..tostring(oConstruction[AiBotBuilding.reftArtiTemplateRefs] == nil)) end
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti, oConstruction.UnitId) and not(oConstruction[AiBotBuilding.reftArtiTemplateRefs]) then
                            --Record shields against the gameender/T3 arti if they are in the reserved location
                            AiBotBuilding.ReserveLocationsForGameEnder(oConstruction)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will reserve location for gameender and alternative shielding') end
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oConstruction.UnitId) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Dealing with a shield '..oConstruction.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oConstruction)..', if part of special shield defence then will assign to GE template') end
                            if oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionSpecialShieldDefence then
                                AiBotBuilding.AssignShieldToGameEnder(oConstruction, oEngineer)
                            else
                                --Consider adding normal shields to the gameender defence if they are built very near to a game ender location
                                if oConstruction:GetAIBrain().AiBotAI and oEngineer:GetAIBrain().AiBotAI then
                                    local iShieldRadius = (oConstruction:GetBlueprint().Defense.Shield.ShieldSize or 0) * 0.5
                                    if iShieldRadius > 10 then --larger than a T2 aeon shield
                                        local iTeam = oEngineer:GetAIBrain().AiBotTeam
                                        local tShieldLZData, tShieldLZTeamData = AiBotMap.GetLandOrWaterZoneData(oConstruction:GetPosition(), true, iTeam)
                                        local bHaveMatch = false

                                        if AiBotUtilities.IsTableEmpty(tShieldLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection]) == false then
                                            for iGameEnder, oGameEnder in tShieldLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection] do
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if oGameEnder as priorit yshield locations, is reftLocationsForPriorityShield empty='..tostring(AiBotUtilities.IsTableEmpty(oGameEnder[AiBotBuilding.reftLocationsForPriorityShield]))) end
                                                if AiBotUtilities.IsTableEmpty(oGameEnder[AiBotBuilding.reftLocationsForPriorityShield]) == false then
                                                    for iLocation, tLocation in oGameEnder[AiBotBuilding.reftLocationsForPriorityShield] do
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Dist between GE priority shield location and this shield='..AiBotUtilities.GetRoughDistanceBetweenPositions(tLocation, oConstruction:GetPosition())) end
                                                        if AiBotUtilities.GetRoughDistanceBetweenPositions(tLocation, oConstruction:GetPosition()) <= 3 then
                                                            if AiBotUtilities.GetDistanceBetweenPositions(oConstruction:GetPosition(), oGameEnder:GetPosition()) <= iShieldRadius * 0.9 then
                                                                if bDebugMessages == true then LOG(sFunctionRef..': Fixed shield construction '..oConstruction.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oConstruction)..' built by engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; will be assigned to a game ender shield as it is close to oGameEnder '..oGameEnder.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oGameEnder)) end
                                                                bHaveMatch = true
                                                                AiBotBuilding.AssignShieldToGameEnder(oConstruction, oEngineer)
                                                                break
                                                            end
                                                        end
                                                    end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': bHaveMatch before basic dist check='..tostring(bHaveMatch)..'; is reftoSpecialAssignedShields empty='..tostring(AiBotUtilities.IsTableEmpty(oGameEnder[AiBotBuilding.reftoSpecialAssignedShields]))..'; Dist between shield and GE='..AiBotUtilities.GetDistanceBetweenPositions(oConstruction:GetPosition(), oGameEnder:GetPosition())..'; Shield radius='..((oConstruction:GetBlueprint().Defense.Shield.ShieldSize or 0) * 0.5)) end
                                                    if not(bHaveMatch) and AiBotUtilities.GetDistanceBetweenPositions(oConstruction:GetPosition(), oGameEnder:GetPosition()) <= (oConstruction:GetBlueprint().Defense.Shield.ShieldSize or 0) * 0.5 - 4 then
                                                        bHaveMatch = true
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will assign this shield as one of the template shields for the GE template') end
                                                        AiBotBuilding.AssignShieldToGameEnder(oConstruction, oEngineer)
                                                    end
                                                    if bHaveMatch then break end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        elseif EntityCategoryContains(categories.COMMAND, oEngineer.UnitId) then
                            --ACU building t1 power far from base - flag that we dont want it assisted
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryT1Power, oConstruction.UnitId) then
                                local oEngineerBrain = oEngineer:GetAIBrain()
                                if oEngineerBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 1.5 then
                                    local tEngineerLZData = AiBotMap.GetLandOrWaterZoneData(oConstruction:GetPosition())
                                    if AiBotUtilities.GetDistanceBetweenPositions(tEngineerLZData[AiBotMap.subrefMidpoint], oEngineer:GetPosition()) >= 25 then
                                        oConstruction[AiBotEngineer.refbDontIncludeAsPartCompleteBuildingForConstruction] = true
                                    end
                                end
                                --ACU building factory - if we have an engineer queued to build a factory in the same zone that hasnt started yet, and it is relatively early on, then clear that engineer's orders
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oConstruction.UnitId) and oConstruction:GetAIBrain():GetEconomyStoredRatio('MASS') <= 0.9 then
                                local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oConstruction:GetPosition(), true, oEngineer:GetAIBrain().AiBotTeam)
                                if tLZOrWZTeamData and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                    local toEngineersInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                    if AiBotUtilities.IsTableEmpty(toEngineersInZone) == false then
                                        for iEngi, oEngi in toEngineersInZone do
                                            if not(oEngi.Dead) and (oEngi[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionBuildLandFactory or oEngi[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionBuildAirFactory or oEngi[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionBuildNavalFactory) then
                                                --Clear queued engineers
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will clear engineers trying to build factory that havent started construction yet, oEngi='..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..'; Work progress='..oEngi:GetWorkProgress()) end
                                                if oEngi:GetWorkProgress() == 0 and not(oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subrefoOrderUnitTarget] == oConstruction) and not(oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subrefoOrderUnitTarget] == oEngineer) then
                                                    AiBotOrders.IssueTrackedClearCommands(oEngi)
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        AiBotBuilding.CheckIfUnitWantsFixedShield(oConstruction, true)
                        --If this is a fixed shield then instead update shield coverage
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oConstruction.UnitId) then
                            if bDebugMessages == true then LOG(sFunctionRef..': About to update shield coverage of units') end
                            AiBotBuilding.UpdateShieldCoverageOfUnits(oConstruction, false)
                        end

                        --Buildable locations - update for unit construction started (do form obile experimentals since the location is temporarily not buildable)
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure + categories.MOBILE - AiBotUnitInfo.refCategoryMex - AiBotUnitInfo.refCategoryHydro, oConstruction.UnitId) then
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oConstruction.UnitId) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Just started construction of unit '..oConstruction.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oConstruction)..'; Is it valid to build a T1 pgen at this location='..tostring(oEngineer:GetAIBrain():CanBuildStructureAt('ueb1101', oConstruction:GetPosition()))) end
                                ForkThread(AiBotEngineer.CheckIfBuildableLocationsNearPositionStillValid, oEngineer:GetAIBrain(), oConstruction:GetPosition(), false, AiBotUnitInfo.GetBuildingSize(oConstruction.UnitId) * 0.5)
                            else
                                --i.e. experimentalal started, the CanBuildStructureAt check doesnt work properly for this so first need to record a blacklist (will only have recorded for 4m) and then check for this
                                if bDebugMessages == true then LOG(sFunctionRef..': Just started construction of experimental mobile unit='..oConstruction.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oConstruction)..'; Is it valid to build a T1 pgen at this location='..tostring(oEngineer:GetAIBrain():CanBuildStructureAt('ueb1101', oConstruction:GetPosition()))) end
                                AiBotEngineer.RecordBlacklistLocation(oConstruction:GetPosition(), AiBotUnitInfo.GetBuildingSize(oConstruction.UnitId) * 0.5, 420, oConstruction)
                                ForkThread(AiBotEngineer.CheckIfBuildableLocationsNearPositionStillValid, oEngineer:GetAIBrain(), oConstruction:GetPosition(), true, AiBotUnitInfo.GetBuildingSize(oConstruction.UnitId) * 0.5)
                            end
                        end
                        --end
                        --Both structures and experimentals - clear any engineers trying to build something else that will be blocked by this
                        ForkThread(AiBotEngineer.ClearEngineersWhoseTargetIsNowBlockedByUnitConstructionStarted, oEngineer, oConstruction)
                    end
                else
                    --Mobile unit - special logic for navla factories for mini bombardment (raid) target
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryBombardment, oConstruction.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oEngineer.UnitId) then
                        AiBotNavy.ConsiderAssigningRaidingNavalUnit(oConstruction, oEngineer)
                    end
                end

            end
        else
            --Non-AiBot only
            if not(oConstruction[AiBotUnitInfo.refbConstructionStart]) then
                oConstruction[AiBotUnitInfo.refbConstructionStart] = true
                --If this is a fixed shield then instead update shield coverage (note - we also do this for AiBot brains above, but with some extra logic to decide if we want to try and shield, and using a more efficient emthod of identifying shields)
                if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oConstruction.UnitId) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Have a shield that we have just started ubilding so will update shield coverage') end
                    AiBotBuilding.UpdateShieldCoverageOfUnits(oConstruction, false)
                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryStructure - categories.MOBILE, oConstruction.UnitId) then
                    --Record if this unit is under fixed shield coverage if it's not owned by an AiBotAI brain (AiBotAI units will separately check this by using the LZ data info)
                    local tNearbyShields = oConstruction:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryFixedShield, oConstruction:GetPosition(), 60, 'Ally')
                    if bDebugMessages == true then LOG(sFunctionRef..': have just started construction of a building, will check for nearby shields, is tNearbyShields empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyShields))) end
                    if AiBotUtilities.IsTableEmpty(tNearbyShields) == false then
                        local iShieldRadius
                        for iShield, oShield in tNearbyShields do
                            iShieldRadius = oShield:GetBlueprint().Defense.Shield.ShieldSize * 0.5 -0.1 -- - 1
                            AiBotBuilding.RecordIfShieldIsProtectingUnit(oShield, oConstruction, iShieldRadius, true)
                        end
                    end

                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnConstructed(oEngineer, oJustBuilt)
    --WARNING: This doesnt seem to trigger for the ACU; it does trigger when untis are constructed by a factory

    --NOTE: This is called every time an engineer stops building a unit whose fractioncomplete is 100%, so can be called multiple times
    if AiBotUtilities.bAiBotAIInGame then
        --NonAiBot specific - dont set the AiBotOnConstructionCalled for this, so need to  be careful that any code here will not be run repeatedly
        --LOG('OnConstructed at time '..GetGameTimeSeconds()..' for unit '..oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)..' owned by brain '..oJustBuilt:GetAIBrain().Nickname..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; AiBotMap.bMapLandSetupComplete='..tostring(AiBotMap.bMapLandSetupComplete or false))
        if not(AiBotMap.bFirstAiBotTeamHasBeenInitialised) or not(AiBotMap.bWaterZoneInitialCreation) then
            local iWaitCount = 0
            local bDontCallAgain = false
            while not(AiBotMap.bFirstAiBotTeamHasBeenInitialised) or not(AiBotMap.bWaterZoneInitialCreation) do
                WaitTicks(1)
                iWaitCount = iWaitCount + 1
                if iWaitCount >= 300 then
                    AiBotUtilities.ErrorHandler('Waited more than 5m for map setup or team setup to complete, something has gone wrong, AiBotMap.bFirstAiBotTeamHasBeenInitialised='..tostring(AiBotMap.bFirstAiBotTeamHasBeenInitialised or false)..'; AiBotMap.bWaterZoneInitialCreation='..tostring(AiBotMap.bWaterZoneInitialCreation or false))
                    bDontCallAgain = true
                    break
                end
            end
            if not(bDontCallAgain) and AiBotUnitInfo.IsUnitValid(oJustBuilt) then
                OnConstructed(oEngineer, oJustBuilt)
            end
        else
            local sFunctionRef = 'OnConstructed'
            local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

            if not(oJustBuilt.UnitId) then --LOUD compatibility redundancy (OnCreate should also do this)
                if not(AiBotUtilities.bFAFActive) then
                    if not(oJustBuilt.EntityId) then oJustBuilt.EntityId = oJustBuilt:GetEntityId() end
                    oJustBuilt.UnitId = oJustBuilt:GetBlueprint().BlueprintId
                end
            end

            AiBotOrders.ClearAnyRepairingUnits(oJustBuilt)
            if AiBotUtilities.IsTableEmpty(oJustBuilt[AiBotLand.reftoUnitsToKillOnCompletion]) == false then
                for iUnit, oUnit in oJustBuilt[AiBotLand.reftoUnitsToKillOnCompletion] do
                    if AiBotUnitInfo.IsUnitValid(oUnit) and (not(oUnit[AiBotUnitInfo.refbCampaignTriggerAdded]) or not(AiBotMap.bIsCampaignMap)) and not(oUnit:IsUnitState('Upgrading')) then
                        AiBotOrders.IssueTrackedKillUnit(oUnit)
                    end
                end
                oJustBuilt[AiBotLand.reftoUnitsToKillOnCompletion] = nil
            end

            if EntityCategoryContains(categories.STRUCTURE, oJustBuilt.UnitId) then
                --If a building has just build a building, then make sure all AiBot are aware of it (since a player would be able to infer this)
                if EntityCategoryContains(categories.STRUCTURE - categories.ENGINEER, oEngineer.UnitId) then
                    local tTeamsUpdated = {}
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.subreftoEnemyBrains]) == false then
                        for iBrain, oBrain in AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.subreftoEnemyBrains] do
                            if oBrain.AiBotAI and not(tTeamsUpdated[oBrain.AiBotTeam]) then
                                tTeamsUpdated[oBrain.AiBotTeam] = true
                                AiBotTeam.AssignUnitToLandZoneOrPond(oBrain, oJustBuilt, false, false, true)
                            end
                        end
                    end
                    --Mex built by engineer - special case where player would be able to infer a mex has been built after a while
                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oJustBuilt.UnitId) then
                    ForkThread(AiBotTeam.ConsiderDelayedMexDetection, oJustBuilt)
                end
                --Also update the name
                if AiBotConfig.AiBotShowUnitNames then
                    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oJustBuilt:GetPosition(), false)

                    local sWZOrLZRef = ''
                    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oJustBuilt:GetPosition())
                    local iWaterZone
                    if (iLandZone or 0) == 0 then
                        iWaterZone = AiBotMap.GetWaterZoneFromPosition(oJustBuilt:GetPosition())
                        if (iWaterZone or 0) > 0 then
                            sWZOrLZRef = 'WZ'..iWaterZone
                        end
                    else
                        sWZOrLZRef = ':P='..(iPlateau or 0)..'LZ='..(iLandZone or 0)
                    end

                    if AiBotConfig.AiBotShowUnitNames then oJustBuilt:SetCustomName(oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)..sWZOrLZRef..': Built') end
                end

                --Redundnacy - If we have just built a radar then update radar logic (note that AssignUnitToLandZoneOrPond should already cover this when construction is started)
                if EntityCategoryContains(AiBotUnitInfo.refCategoryRadar, oJustBuilt.UnitId) then
                    ForkThread(AiBotLand.UpdateZoneIntelForRadar, oJustBuilt)
                    if EntityCategoryContains(categories.TECH2, oJustBuilt.UnitId) then
                        ForkThread(AiBotBuilding.ConsiderUpgradingT2Radar, oJustBuilt)
                    end
                elseif EntityCategoryContains(AiBotUnitInfo.refCategorySonar, oJustBuilt.UnitId) then
                    ForkThread(AiBotNavy.UpdateZoneIntelForSonar, oJustBuilt)

                    --Air staging - reset timer on when we last needed one
                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirStaging, oJustBuilt.UnitId) then
                    AiBotTeam.tTeamData[oJustBuilt:GetAIBrain().AiBotTeam][AiBotTeam.refiTimeOfLastAirStagingShortage] = 0
                end

                --Track non-AiBotAI wall segments
                if EntityCategoryContains(AiBotUnitInfo.refCategoryWall, oJustBuilt.UnitId) and not(oJustBuilt:GetAIBrain().AiBotAI) then
                    AiBotLand.TrackWallSegment(oJustBuilt, true)
                end
            elseif oJustBuilt[AiBotEngineer.reftUnitBlacklistSegmentXZ] then --EntityCategoryContains(categories.EXPERIMENTAL * categories.MOBILE - AiBotUnitInfo.refCategoryExperimentalArti, oJustBuilt.UnitId) then
                --Treat area around experimental under construction as available again
                AiBotEngineer.ClearBlacklistForUnitConstructed(oJustBuilt)
                AiBotEngineer.SearchForBuildableLocationsNearDestroyedBuilding(oJustBuilt)
            end

            AiBotBuilding.RecordUnitShieldCoverage(oJustBuilt)



            if not(oJustBuilt.AiBotOnConstructedCalled) then
                oJustBuilt.AiBotOnConstructedCalled = true


                local oBrainJustBuilt = oJustBuilt:GetAIBrain()
                if bDebugMessages == true then LOG(sFunctionRef..': First time calling for unit '..(oJustBuilt.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt) or 'nil')..' owned by '..oJustBuilt:GetAIBrain().Nickname..', was this AiBot brain='..tostring(oJustBuilt:GetAIBrain().AiBotAI or false)..'; Built at time='..GetGameTimeSeconds()) end

                --Both AiBot and Non-AiBot where not already run onconstructioncalled:
                --TML - flag to rerun logic for targeting as redundancy for cases where getunitsaroundpoint wont pickup under construction/upgrading units
                if oJustBuilt[AiBotBuilding.refbRecheckTMLAndTMDWhenConstructedByTeam] then
                    for iTMLTeam, bRecheck in oJustBuilt[AiBotBuilding.refbRecheckTMLAndTMDWhenConstructedByTeam] do
                        ForkThread(AiBotBuilding.RecordTMLAndTMDForEnemyUnitTargetJustDetected, oJustBuilt, iTMLTeam)
                    end
                    oJustBuilt[AiBotBuilding.refbRecheckTMLAndTMDWhenConstructedByTeam] = nil
                end

                --SMD - update with more accurate estimate of time when built
                if oJustBuilt[AiBotUnitInfo.refiTimeOfLastCheck] and EntityCategoryContains(AiBotUnitInfo.refCategorySMD, oJustBuilt.UnitId) then


                    oJustBuilt[AiBotUnitInfo.refiTimeOfLastCheck] = GetGameTimeSeconds() - AiBotBuilding.iTimeForSMDToBeConstructed
                    if bDebugMessages == true then LOG(sFunctionRef..': Just built SMD, oJustBuilt='..oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)..'; Owner='..oJustBuilt:GetAIBrain().Nickname..'; Time='..GetGameTimeSeconds()) end
                end

                --Mex tracking
                if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oJustBuilt.UnitId) then
                    AiBotBuilding.OnMexConstructionCompleted(oJustBuilt)
                end

                --AiBot specific
                if oJustBuilt:GetAIBrain().AiBotAI then

                    if bDebugMessages == true then LOG(sFunctionRef..': oEngineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' has just built '..oJustBuilt.UnitId) end
                    local iTeam = oBrainJustBuilt.AiBotTeam
                    --experimental level construction count, and paragon and yolona specific logic
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oJustBuilt.UnitId) then
                        --If this is a cheap experimental then only count as partial experimental
                        local iExpMassCost = AiBotUnitInfo.GetUnitMassCost(oJustBuilt)
                        if iExpMassCost <= 50000 and EntityCategoryContains(AiBotUnitInfo.refCategoryT2PlusPD, oJustBuilt.UnitId) then
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] + 0.2
                        elseif iExpMassCost <= 50000 and EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oJustBuilt.UnitId) then
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] + 0.35
                        elseif iExpMassCost < 20000 then
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] + 0.75 * iExpMassCost / 20000
                        else
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] + 1
                        end
                        local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oJustBuilt:GetPosition(), true, iTeam)
                        tLZTeamData[AiBotMap.refiZoneConstructedExperimentalCount] = (tLZTeamData[AiBotMap.refiZoneConstructedExperimentalCount] or 0) + 1
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryParagon, oJustBuilt.UnitId) then
                            ForkThread(AiBotBuilding.JustBuiltParagon, oJustBuilt)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategorySML * categories.EXPERIMENTAL, oJustBuilt.UnitId) then
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNeedResourcesForMissile] = true
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oJustBuilt.UnitId) or ((oJustBuilt[AiBotUnitInfo.refiDFRange] or 0) >= 80 and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oJustBuilt.UnitId)) then
                            --flag we have built long range unit so we prioritise building omni
                            oBrainJustBuilt[AiBotOverseer.refbBuiltLongRangeLandUnit] = true
                        end

                        if EntityCategoryContains(AiBotUnitInfo.refCategoryNovaxCentre, oJustBuilt.UnitId) then
                            ForkThread(AiBotAir.DelayedNovaxUnloadCheck, oJustBuilt)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNovaxCentre, oEngineer.UnitId) and oEngineer:GetAIBrain().AiBotAI then
                            ForkThread(AiBotAir.DelayedNovaxUnloadCheck, oEngineer)
                        end

                        if EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder, oJustBuilt.UnitId) then AiBotTeam.tTeamData[iTeam][AiBotTeam.refiFriendlyGameEnderCount] = (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiFriendlyGameEnderCount] or 0) + 1 end
                        if oJustBuilt[AiBotBuilding.reftArtiTemplateRefs] then
                            --Reassess the game-ender to build
                            local tTableRef = AiBotMap.tAllPlateaus[oJustBuilt[AiBotBuilding.reftArtiTemplateRefs][1]][AiBotMap.subrefPlateauLandZones][oJustBuilt[AiBotBuilding.reftArtiTemplateRefs][2]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.reftActiveGameEnderTemplates][oJustBuilt[AiBotBuilding.reftArtiTemplateRefs][3]]
                            if tTableRef then tTableRef[AiBotMap.subrefbForceRefreshOfArtiToBuild] = true end
                            if bDebugMessages == true then LOG(sFunctionRef..': Flagging that we want to refresh the Arti to build for GE template, P'..oJustBuilt[AiBotBuilding.reftArtiTemplateRefs][1]..'Z'..oJustBuilt[AiBotBuilding.reftArtiTemplateRefs][2]..'T'..oJustBuilt[AiBotBuilding.reftArtiTemplateRefs][3]..'; tTableRef[AiBotMap.subrefbForceRefreshOfArtiToBuild]='..tostring(tTableRef[AiBotMap.subrefbForceRefreshOfArtiToBuild] or false)..'; Is tTableRef nil='..tostring(tTableRef == nil)..'; Time='..GetGameTimeSeconds()) end
                        end
                        --QAI chat
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oJustBuilt.UnitId) and oBrainJustBuilt[AiBotChat.refiAssignedPersonality] == AiBotChat.refiQAI and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] < 8000 and AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt) == 1 then
                            ForkThread(AiBotChat.ConsiderQAIAboutToAttackMessage, oJustBuilt)
                        end

                        --Engineer owns a paragon and just built a mobile exp - have it keep building in same location
                        if oBrainJustBuilt[AiBotEconomy.refbBuiltParagon] and EntityCategoryContains(categories.MOBILE, oJustBuilt.UnitId) and oEngineer:CanBuild(oJustBuilt.UnitId) then
                            local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oJustBuilt:GetPosition(), true, iTeam)
                            if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftActiveGameEnderTemplates][1]) == false then
                                --Try and rebuild the same unit
                                AiBotOrders.IssueTrackedClearCommands(oEngineer)
                                local iAction
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oJustBuilt.UnitId) then
                                    iAction = AiBotEngineer.refActionBuildLandExperimental
                                else
                                    iAction = AiBotEngineer.refActionBuildExperimental
                                end
                                AiBotEngineer.TrackEngineerAction(oEngineer, iAction, true, 1, nil, nil, false)
                                AiBotOrders.IssueTrackedBuild(oEngineer, oJustBuilt:GetPosition(), oJustBuilt.UnitId, false, 'ParaRebldExp')
                                AiBotMicro.TrackTemporaryUnitMicro(oEngineer, 30)
                                if bDebugMessages == true then LOG(sFunctionRef..': Will try and rebuild the experimental we just built, oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; oJustBuilt='..oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)..'; iAction='..iAction) end
                            end
                        end

                        --Performance mode
                        AiBotUnitInfo.AdjustThreatThresholdsForConstructedExperimental(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount])
                        --Loud T2 sniperbots - consider enhancement
                    elseif (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and oJustBuilt.UnitId == 'ual0204' and (AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt) >= 15 or EntityCategoryContains(categories.TECH3, oEngineer.UnitId)) then
                        ForkThread(AiBotLand.DelayedGetFirstEnhancementOnUnit, oJustBuilt, 6)
                        --Sniperbots - if we have built 4+ by the same player then also prioritise omni
                    elseif (oJustBuilt[AiBotUnitInfo.refiDFRange] or 0) >= 55 and AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt) >= 4 then oBrainJustBuilt[AiBotOverseer.refbBuiltLongRangeLandUnit] = true
                    end

                    --Experimental air - no longer record in land/water zone
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAir - AiBotUnitInfo.refCategoryEngineer, oJustBuilt.UnitId) then
                        --Transport specific - tell the factory that just built the transport to build something else
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryTransport, oJustBuilt.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory * categories.TECH1, oEngineer.UnitId) then
                            oEngineer[AiBotFactory.refbWantNextUnitToBeEngineer] = true
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryBomber * categories.TECH3, oJustBuilt.UnitId) and not(oJustBuilt[AiBotAir.refbBomberUsingMexHunterLogic]) then
                            ForkThread(AiBotAir.ApplyMexHuntingLogicToBomber, oJustBuilt)
                        end

                        local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oJustBuilt:GetPosition())
                        if (iLandOrWaterZone or 0) > 0 then
                            local tLZOrWZData
                            local tLZOrWZTeamData
                            local sUnitTableRef

                            if iPlateauOrZero == 0 then
                                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                sUnitTableRef = AiBotMap.subreftoLZOrWZAlliedUnits
                            else
                                tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                sUnitTableRef = AiBotMap.subreftoLZOrWZAlliedUnits
                            end
                            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[sUnitTableRef]) == false then
                                for iUnit, oUnit in tLZOrWZTeamData[sUnitTableRef] do
                                    if oUnit == oJustBuilt then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Removing unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' from zone '..iLandOrWaterZone..' as it is a construction completed experimental') end
                                        table.remove(tLZOrWZTeamData[sUnitTableRef], iUnit)
                                        break
                                    end
                                end
                            end
                        end
                    --PD tracking
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryPD, oJustBuilt.UnitId) then
                        local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oJustBuilt:GetPosition(), true, oEngineer:GetAIBrain().AiBotTeam)
                        tLZTeamData[AiBotMap.refiTimeLastCompletedPD] = GetGameTimeSeconds()
                    end

                    --Logic based on the unit that was just built:

                    --Check build locations for units not built at a factory
                    local bDontClearEngineer = false
                    if bDebugMessages == true then LOG(sFunctionRef..': Will now consider logic for units not built at a factory, was this a structure or experimental='..tostring(EntityCategoryContains(categories.STRUCTURE + categories.EXPERIMENTAL, oJustBuilt.UnitId))..'; Upgradesto='..(oJustBuilt:GetBlueprint().UpgradesTo or 'nil')..'; is this a mass fab that can upgrade='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryMassFab, oJustBuilt.UnitId) and not((oJustBuilt:GetBlueprint().General.UpgradesTo or '') == ''))) end
                    if EntityCategoryContains(categories.STRUCTURE + categories.EXPERIMENTAL, oJustBuilt.UnitId) then

                        if not(oJustBuilt[AiBotUnitInfo.refbConstructionStart]) then
                            AiBotEngineer.CheckIfBuildableLocationsNearPositionStillValid(oBrainJustBuilt, oJustBuilt:GetPosition(), false, AiBotUnitInfo.GetBuildingSize(oJustBuilt.UnitId) * 0.5)
                        end
                        AiBotEconomy.UpdateHighestFactoryTechLevelForBuiltUnit(oJustBuilt) --includes a check to see if are dealing with a factory HQ
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oJustBuilt.UnitId) then
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiUpgradedMexCount] = (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiUpgradedMexCount] or 0) + 1
                            oJustBuilt[AiBotUnitInfo.refiTimeMexConstructed] = GetGameTimeSeconds()
                            ForkThread(AiBotEconomy.UpdateZoneAiBotMexByTechCount, oJustBuilt, false, 10)
                            --If this is a t3 mex and we have a paragon, then gift the mex to teammate, otherwise gift the storage from teammates to us
                            local bGiftingToTeammate = false
                            if oBrainJustBuilt[AiBotEconomy.refbBuiltParagon] and not((oJustBuilt:GetBlueprint().General.UpgradesTo or '') == '') then
                                local oAiBotBrainToGiftTo
                                local oOtherBrainToGiftTo
                                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
                                    if not(oBrain == oBrainJustBuilt) then
                                        if oBrain.AiBotAI then
                                            if not(oAiBotBrainToGiftTo) then
                                                oAiBotBrainToGiftTo = oBrain
                                                break
                                            end
                                        else
                                            if not(oOtherBrainToGiftTo) then oOtherBrainToGiftTo = oBrain end
                                        end
                                    end
                                end
                                if oOtherBrainToGiftTo or  oAiBotBrainToGiftTo then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will gift T3 mex we have just built to teammate as we have a paragon, oAiBotBrainToGiftTo='..(oAiBotBrainToGiftTo.Nickname or 'nil')..'; oOtherBrainToGiftTo='..(oOtherBrainToGiftTo.Nickname or 'nil')..'; Time='..GetGameTimeSeconds()) end
                                    bGiftingToTeammate = true
                                    ForkThread(AiBotTeam.DelayedUnitTransferToPlayer, { oJustBuilt }, (oAiBotBrainToGiftTo or oOtherBrainToGiftTo):GetArmyIndex(), 0.2)
                                end
                            else
                                --If have storage owned by AiBot on same team by this mex, gift it over
                                --All mexes - on construction check if we have allied AiBot mass storage nearby (e.g. we have rebuilt on a mex that they used to have) and if so then have that AiBot gift over their mass storage
                                AiBotTeam.GiftAdjacentStorageToMexOwner(oJustBuilt)
                            end

                            --Update part built t1 mex tracking
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryT1Mex, oJustBuilt.UnitId) then
                                AiBotEngineer.UpdatePartBuiltListForCompletedMex(oJustBuilt)
                                --Check if teammate has enough factories that we should give this to them - require mex to be closer to their base and for them to have factories in the zone, and for us to have no T2+ mexes
                                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) == false and table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) > 1 then
                                    local iMexPlateau, iMexZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oJustBuilt:GetPosition())
                                    local iTeam = oBrainJustBuilt.AiBotTeam
                                    local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oJustBuilt:GetPosition(), true, iTeam)
                                    if GetGameTimeSeconds() >= 100 and not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) and (tLZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount] or 0) > 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][1] <= math.max(3, (tLZData[AiBotMap.subrefLZOrWZMexCount] or 0) * 0.5) then
                                        local iClosestNonAiBotBrainDistBase = 100000
                                        local oClosestNonAiBotBrain
                                        local iClosestAiBotBrainDistBase = 100000
                                        local bInSameZoneAsNonAiBotAIStart
                                        local iBrainPlateau, iBrainZone

                                        local iCurDist
                                        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
                                            if not(oBrain:IsDefeated()) and (oBrain.AiBotAI or ScenarioInfo.Options.AiBotTeammate == 1) then
                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oJustBuilt:GetPosition(), AiBotMap.GetPlayerStartPosition(oBrain))
                                                if oBrain.AiBotAI then iClosestAiBotBrainDistBase = math.min(iClosestAiBotBrainDistBase, iCurDist)
                                                else
                                                    if iClosestNonAiBotBrainDistBase > iCurDist then
                                                        iClosestNonAiBotBrainDistBase = iCurDist
                                                        oClosestNonAiBotBrain = oBrain
                                                    end
                                                    if iClosestNonAiBotBrainDistBase <= 200 and not(bInSameZoneAsNonAiBotAIStart) then
                                                        iBrainPlateau, iBrainZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotMap.GetPlayerStartPosition(oBrain))
                                                        if iBrainPlateau == iMexPlateau and iBrainZone == iMexZone then
                                                            bInSameZoneAsNonAiBotAIStart = true
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to gift T1 mex '..oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)..' to a teammate, iClosestNonAiBotBrainDistBase='..iClosestNonAiBotBrainDistBase..'; iClosestAiBotBrainDistBase='..iClosestAiBotBrainDistBase) end
                                        if iClosestNonAiBotBrainDistBase <= 200 and (bInSameZoneAsNonAiBotAIStart or iClosestNonAiBotBrainDistBase + 50 <= iClosestAiBotBrainDistBase) then
                                            --Dont gift a human player's mexes in shared army mode, even if AiBot logic is active
                                            if AiBotOrders.bDontConsiderCombinedArmy or (oJustBuilt.AiBotActive and not(oBrainJustBuilt.BrainType == 'Human')) then
                                                --Check we have enough mexes to be able to gift
                                                local iOurMexes = oBrainJustBuilt:GetCurrentUnits(AiBotUnitInfo.refCategoryMex)
                                                local iTeammateMexes = oBrainJustBuilt:GetCurrentUnits(AiBotUnitInfo.refCategoryMex)
                                                if iOurMexes >= iTeammateMexes * 0.6 and iOurMexes >= 2 then
                                                    ForkThread(AiBotTeam.DelayedUnitTransferToPlayer, { oJustBuilt }, oClosestNonAiBotBrain:GetArmyIndex(), 0.2)
                                                    local sPotentialMessages = {
                                                        [1] = 'I guess this is one of your mexes '..oClosestNonAiBotBrain.Nickname..', try to claim it faster next time',
                                                        [2] = 'You look like you could use this mex more than me '..oClosestNonAiBotBrain.Nickname,
                                                        [3] = 'Transferred t1 mex to '..oClosestNonAiBotBrain.Nickname,
                                                        [4] = 'I\'ve just given you a mex '..oClosestNonAiBotBrain.Nickname,
                                                        [5] = 'Have this mex '..oClosestNonAiBotBrain.Nickname..', I hope this means we can be friends',
                                                        [6] = 'My master says I must help my team more, so have a mex '..oClosestNonAiBotBrain.Nickname,
                                                        [7] = 'Given you a mex '..oClosestNonAiBotBrain.Nickname,
                                                        [8] = 'Have this mex I\'ve just built '..oClosestNonAiBotBrain.Nickname
                                                    }
                                                    local sMessage = sPotentialMessages[math.random(1, table.getn(sPotentialMessages))] or sPotentialMessages[1]
                                                    --SendMessage(aiBrain, sMessageType, sMessage, iOptionalDelayBeforeSending, iOptionalTimeBetweenMessageType, bOnlySendToTeam, bWaitUntilHaveACU, sOptionalSoundCue, sOptionalSoundBank, oOptionalOnlyBrainToSendTo)
                                                    AiBotChat.SendMessage(oBrainJustBuilt, 'MexGiftF'..oBrainJustBuilt.AiBotTeam..'T'..oClosestNonAiBotBrain:GetArmyIndex(), sMessage, 1, 90, true, true)
                                                end
                                            end
                                            bGiftingToTeammate = true
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to apply special logic for upgrading further mex in the zone after this one, was this a T1 mex='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryT1Mex, oJustBuilt.UnitId))..'; bGiftingToTeammate='..tostring(bGiftingToTeammate or false)) end
                            if not(bGiftingToTeammate) then
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oJustBuilt.UnitId) then
                                    --If can upgrade then consider future upgrade
                                    local sUpgrade = oJustBuilt:GetBlueprint().General.UpgradesTo
                                    if sUpgrade and not(sUpgrade == '') then
                                        ForkThread(AiBotEconomy.ConsiderFutureMexUpgrade, oJustBuilt) --i.e. to cover cases where after this mex survives a while we want ot upgrade it some more
                                        if EntityCategoryContains(categories.TECH3, oJustBuilt.UnitId) then AiBotEconomy.bT3MexCanBeUpgraded = true end
                                    end
                                    --Unpause a paused mex if we are in a stall
                                    ForkThread(AiBotEconomy.UnpausePausedMexFollowingUpgrade, oJustBuilt, not((sUpgrade or '') == nil))
                                end
                                --COnsider upgrading another mex in this zone
                                ForkThread(AiBotEconomy.ConsiderUpgradingMexDueToCompletion, oJustBuilt, oEngineer) --i.e. intention is to cover cases where we have the eco from just completing a mex upgrade to then upgrade another of the same tech level (or in some cases upgrade this/a simialr tech to higher tech)
                            end
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMassStorage, oJustBuilt.UnitId) then
                            AiBotBuilding.ConsiderGiftingMassStorageToNearbyMexOwner(oJustBuilt)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryEnergyStorage, oJustBuilt.UnitId) then
                            AiBotTeam.TeamEconomyRefresh(iTeam)
                            AiBotTeam.ConsiderGiftingStorageToTeammate(oJustBuilt)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oJustBuilt.UnitId) then
                            --Clear the desire to build land facs by mexes - i.e. only want hte first one to be built as such (exception - LOUD if cant build mass storage)
                            if AiBotBuilding.iLowestMassStorageTechAvailable <= 2 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Have just build land factory so clearing adjacency desire for all AiBot brains; HighestFactoryTechLevel='..oBrainJustBuilt[AiBotEconomy.refiOurHighestFactoryTechLevel]..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Cur land factory units='..oBrainJustBuilt:GetCurrentUnits(AiBotUnitInfo.refCategoryLandFactory)) end
                                AiBotEngineer.tiActionAdjacentCategory[AiBotEngineer.refActionBuildLandFactory] = nil
                            end
                            if EntityCategoryContains(categories.COMMAND, oEngineer.UnitId) and EntityCategoryContains(categories.TECH1, oJustBuilt.UnitId) and (AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt) == 1 or (oBrainJustBuilt[AiBotEconomy.refiOurHighestAirFactoryTech] == 0 and oBrainJustBuilt:GetCurrentUnits(AiBotUnitInfo.refCategoryLandFactory) <= 1)) then
                                --Make first land factory built be a core base if it isnt already
                                local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oJustBuilt:GetPosition(), true, oBrainJustBuilt.AiBotTeam)
                                if bDebugMessages == true then LOG(sFunctionRef..': Just built our first land factory with our ACU, is this core base='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase])) end
                                if not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) then
                                    if AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt) == 1 then
                                        tLZTeamData[AiBotMap.subrefbCoreBaseOverride] = true
                                    else
                                        local iOriginalPlateau, iOriginalZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotMap.GetPlayerStartPosition(oBrainJustBuilt))
                                        if (iOriginalPlateau or 0) <= 0 or (iOriginalZone or 0) <= 0 then iOriginalPlateau, iOriginalZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tLZTeamData[AiBotMap.reftClosestFriendlyBase]) end
                                        if (iOriginalPlateau or 0) > 0 and iOriginalZone then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will reassess where we want to build our core base') end
                                            ForkThread(AiBotEconomy.ConsiderChangingCoreBase, oBrainJustBuilt, iOriginalPlateau, iOriginalZone)
                                        end
                                    end
                                end
                                --Set primary factory flag if on and island or plateau dif to our main base, and no other constructed factories here, and mod dist is >=0.2
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory - categories.TECH3, oJustBuilt.UnitId) then
                                local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oJustBuilt:GetPosition(), true, oBrainJustBuilt.AiBotTeam)
                                local NavUtils = AiBotUtilities.NavUtils
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering oJsutBuilt='..oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)..'; Mod dist%='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Island ref='..tLZData[AiBotMap.subrefLZIslandRef]..'; Island ref of nearest base='..NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestFriendlyBase])) end
                                if tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.2 and not(tLZData[AiBotMap.subrefLZIslandRef] == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestFriendlyBase])) then
                                    local iTotalLandFacsOfSameOrBetterTechInZoneOrAdjacent = 0
                                    local iTechLevelWanted = AiBotUnitInfo.GetUnitTechLevel(oJustBuilt)
                                    function ConsiderCurZone(tCurLZTeamData)
                                        if AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                            local tOtherFacs = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory, tCurLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                            if AiBotUtilities.IsTableEmpty(tOtherFacs) == false then
                                                for iFac, oFac in tOtherFacs do
                                                    if AiBotUnitInfo.IsUnitValid(oFac) and oFac:GetFractionComplete() >= 1 and AiBotUnitInfo.GetUnitTechLevel(oFac) >= iTechLevelWanted then
                                                        iTotalLandFacsOfSameOrBetterTechInZoneOrAdjacent = iTotalLandFacsOfSameOrBetterTechInZoneOrAdjacent + 1
                                                        if iTotalLandFacsOfSameOrBetterTechInZoneOrAdjacent >= 2 then break end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    ConsiderCurZone(tLZTeamData)
                                    if bDebugMessages == true then LOG(sFunctionRef..': iTotalLandFacsOfSameOrBetterTechInZoneOrAdjacent='..iTotalLandFacsOfSameOrBetterTechInZoneOrAdjacent) end
                                    if iTotalLandFacsOfSameOrBetterTechInZoneOrAdjacent <= 1 then
                                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                            local iPlateau, iLandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oJustBuilt:GetPosition())
                                            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                                local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                                ConsiderCurZone(tAdjLZTeamData)
                                            end
                                        end
                                        if iTotalLandFacsOfSameOrBetterTechInZoneOrAdjacent <= 1 then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Setting primary factory flag to true for factory '..oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)) end
                                            oJustBuilt[AiBotFactory.refbPrimaryFactoryForIslandOrPond] = true
                                        end
                                    end
                                end

                                --If have completed 4th T2 support land fac in a zone then get T3 land fac once we have sufficient gross mass
                                if tLZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt) >= 4 and EntityCategoryContains(categories.SUPPORTFACTORY, oJustBuilt.UnitId) then
                                    ForkThread(AiBotEconomy.UpgradeToT3LandOnceHaveLotsOfSupportFactories, oJustBuilt:GetAIBrain(), tLZTeamData)
                                end
                            end

                            AiBotEconomy.ConsiderImmediateUpgradeOfFactory(oJustBuilt)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oJustBuilt.UnitId) then
                            AiBotEconomy.ConsiderImmediateUpgradeOfFactory(oJustBuilt)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti, oJustBuilt.UnitId) then
                            ForkThread(AiBotBuilding.GetT3ArtiTarget, oJustBuilt)
                            ForkThread(AiBotEconomy.JustBuiltT2PlusPowerOrExperimentalInZone, oJustBuilt)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryPD * categories.TECH1 + AiBotUnitInfo.refCategoryWall, oJustBuilt.UnitId) then
                            --Build T1 walls around T1 PD
                            --GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryCondition,                                           oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences)
                            local sWallBP = AiBotFactory.GetBlueprintThatCanBuildOfCategory(oBrainJustBuilt, AiBotEngineer.tiActionCategory[AiBotEngineer.refActionBuildWall], oEngineer)
                            if sWallBP then
                                local tWallBuildLocation = AiBotEngineer.GetLocationToBuildWall(oEngineer, oJustBuilt, sWallBP)
                                if tWallBuildLocation and oEngineer:GetAIBrain().AiBotAI then
                                    --First generate list of other engineers to also help with wall building (as theyll potentially get cleared when we clear the original engineer)
                                    local tOtherEngineersHelpingConstruction = {}
                                    local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oJustBuilt:GetPosition(), true, oEngineer:GetAIBrain().AiBotTeam)
                                    local tEngineersInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                    if AiBotUtilities.IsTableEmpty(tEngineersInZone) == false then
                                        for iUnit, oUnit in tEngineersInZone do
                                            if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering other engineer in zone, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Assigned action='..(oUnit[AiBotEngineer.refiAssignedAction] or 'nil')) end
                                                if oUnit[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionBuildEmergencyPD then --dont need to do for walsl as eahc engi builds individually
                                                    local oFocusUnit = oUnit:GetFocusUnit()
                                                    if bDebugMessages == true then
                                                        LOG(sFunctionRef..': oFocusUnit='..(oFocusUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFocusUnit) or 'nil')..'; Last order='..reprs(oUnit[AiBotOrders.reftiLastOrders]))
                                                        if AiBotUtilities.IsTableEmpty(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition]) == false then
                                                            LOG(sFunctionRef..': Dist of last order to just built='..AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition], oJustBuilt:GetPosition())..'; Dist of last order to engineer='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oJustBuilt:GetPosition()))
                                                        end
                                                    end

                                                    if oFocusUnit == oEngineer or oFocusUnit == oJustBuilt or (not(oFocusUnit) and AiBotUtilities.IsTableEmpty(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition]) == false and AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition], oJustBuilt:GetPosition()) < 1 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oJustBuilt:GetPosition()) <= oUnit:GetBlueprint().Economy.MaxBuildDistance + 1) then
                                                        table.insert(tOtherEngineersHelpingConstruction, oUnit)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': have a supporting engineer that helped build the T1 PD') end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    AiBotOrders.IssueTrackedBuild(oEngineer, tWallBuildLocation, sWallBP, false, 'WallP')
                                    AiBotEngineer.TrackEngineerAction(oEngineer, AiBotEngineer.refActionBuildWall, true, 1)
                                    bDontClearEngineer = true
                                    if AiBotUtilities.IsTableEmpty(tOtherEngineersHelpingConstruction) == false then
                                        for iUnit, oUnit in tOtherEngineersHelpingConstruction do
                                            local tWallBuildLocation = AiBotEngineer.GetLocationToBuildWall(oUnit, oJustBuilt, sWallBP)
                                            if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; tWallBuildLocation='..repru(tWallBuildLocation)) end
                                            if tWallBuildLocation then
                                                AiBotOrders.IssueTrackedBuild(oUnit, tWallBuildLocation, sWallBP, false, 'WallS')
                                                AiBotEngineer.TrackEngineerAction(oUnit, AiBotEngineer.refActionBuildWall, true, 1)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will tell unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to build a wall at '..repru(tWallBuildLocation)) end
                                            end
                                        end
                                    end
                                end
                            end
                            --T2 PD - get TMD preemptively if built a number
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryPD * categories.TECH2, oJustBuilt.UnitId) then
                            ForkThread(AiBotBuilding.ConsiderGettingPreemptiveTMD, oJustBuilt)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryPower, oJustBuilt.UnitId) then --In LOUD t2 pgen upgrades to t3 are as efficient as t3 pgens
                            local sUpgrade = oJustBuilt:GetBlueprint().General.UpgradesTo
                            if sUpgrade and not(sUpgrade == '') then
                                ForkThread(AiBotEconomy.ConsiderPowerPgenUpgrade, oJustBuilt)
                            else
                                ForkThread(AiBotBuilding.ConsiderGiftingPowerToTeammateForAdjacency, oJustBuilt)
                            end
                            ForkThread(AiBotEconomy.JustBuiltT2PlusPowerOrExperimentalInZone, oJustBuilt)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMassFab, oJustBuilt.UnitId) and not((oJustBuilt:GetBlueprint().General.UpgradesTo or '') == '') then
                            ForkThread(AiBotEconomy.ConsiderMassFabUpgrade, oJustBuilt, 0)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryPower * categories.TECH2, oJustBuilt.UnitId) then
                            ForkThread(AiBotEconomy.JustBuiltT2PlusPowerOrExperimentalInZone, oJustBuilt)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategorySMD, oJustBuilt.UnitId) then
                            --If we have a paragon on the team then gift this to a paragon owner
                            local oBrainToTransferTo
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] and not(oBrainJustBuilt[AiBotEconomy.refbBuiltParagon]) then
                                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
                                    if not(oBrain == oBrainJustBuilt) then
                                        if oBrain.AiBotAI and oBrain[AiBotEconomy.refbBuiltParagon] then
                                            oBrainToTransferTo = oBrain
                                            break
                                        end
                                    end
                                end
                            end
                            if oBrainToTransferTo then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will gift SMD we have just built to teammate as they have a paragon, oBrainToTransferTo='..(oBrainToTransferTo.Nickname or 'nil')..'; Cur owner='..oBrainJustBuilt.Nickname..'; Time='..GetGameTimeSeconds()) end
                                ForkThread(AiBotTeam.DelayedUnitTransferToPlayer, { oJustBuilt }, oBrainToTransferTo:GetArmyIndex(), 0.2)
                            else
                                --If enemy has nuke then flag we need resources for missile
                                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]) == false then
                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNeedResourcesForMissile] = true
                                end
                            end

                            ForkThread(AiBotEconomy.JustBuiltT2PlusPowerOrExperimentalInZone, oJustBuilt)
                            --T2 arti - consider manual shot targets
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oJustBuilt.UnitId) then
                            ForkThread(AiBotBuilding.ConsiderManualT2ArtiTarget, oJustBuilt)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oJustBuilt.UnitId) then
                            --Cybran ED1 shields - upgrade if enemy has novax or t3 arti
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield * categories.BUILTBYTIER2ENGINEER * categories.CYBRAN, oJustBuilt.UnitId) then
                                if AiBotTeam.tTeamData[oBrainJustBuilt.AiBotTeam][AiBotTeam.refbDefendAgainstArti] then
                                    AiBotEconomy.UpgradeUnit(oJustBuilt, true)
                                end
                            end

                            --Shield tracking
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield  - categories.TECH2 - categories.TECH1, oJustBuilt.UnitId) then
                                local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oJustBuilt:GetPosition(), true, oBrainJustBuilt.AiBotTeam)
                                if tLZTeamData then
                                    tLZTeamData[AiBotMap.subrefiT3FixedShieldConstructedCount] = (tLZTeamData[AiBotMap.subrefiT3FixedShieldConstructedCount] or 0) + 1
                                    if oJustBuilt:GetBlueprint().Defense.Shield.ShieldMaxHealth >= AiBotBuilding.iExperimentalShieldHealthValue then
                                        tLZTeamData[AiBotMap.subrefiExperimentalShieldConstructedCount] = (tLZTeamData[AiBotMap.subrefiExperimentalShieldConstructedCount] or 0) + 1
                                    end
                                end
                            end
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oJustBuilt.UnitId) then
                            ForkThread(AiBotEconomy.JustBuiltT2PlusPowerOrExperimentalInZone, oJustBuilt)
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryEnergyStorage + AiBotUnitInfo.refCategoryParagon + AiBotUnitInfo.refCategoryQuantumOptics, oJustBuilt.UnitId) then
                                AiBotTeam.TeamEconomyRefresh(iTeam)
                            end
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryEnergyStorage + AiBotUnitInfo.refCategoryParagon + AiBotUnitInfo.refCategoryQuantumOptics, oJustBuilt.UnitId) then
                            --I.e. for energy storage units not caught by energy storage above or experimental level (paragon) - i.e. first two categories are just a redundancy
                            AiBotTeam.TeamEconomyRefresh(iTeam)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oJustBuilt.UnitId) then
                            --Navy personality - assign all naval facs to it if it is the primary brain for this zone
                            if not(EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oEngineer.UnitId)) and not(oBrainJustBuilt[AiBotOverseer.refbPrioritiseNavy]) then
                                local tWZData, tWZTeamData = AiBotMap.GetLandOrWaterZoneData(oJustBuilt:GetPosition(), true, oBrainJustBuilt.AiBotTeam)
                                if ArmyBrains[tWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotOverseer.refbPrioritiseNavy] then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will gift naval fac to the brain prioritising navy') end
                                    ForkThread(AiBotTeam.TransferUnitsToPlayer, { oJustBuilt }, tWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex], false)
                                end
                            end
                        end
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti - categories.MOBILE + AiBotUnitInfo.refCategorySML * categories.TECH3 + AiBotUnitInfo.refCategoryAirFactory * categories.TECH3 + AiBotUnitInfo.refCategoryMassFab * categories.TECH3 + AiBotUnitInfo.refCategoryT3Radar, oJustBuilt.UnitId) then
                            ForkThread(AiBotBuilding.ConsiderGiftingPowerToTeammateForAdjacency, oJustBuilt)
                        end
                        --Clear engineers that just built this
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryIndirect * categories.TECH1, oJustBuilt.UnitId) then
                        --Check if we have transports wanting combat drops
                        local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oJustBuilt:GetPosition(), true, oBrainJustBuilt.AiBotTeam)
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits]) == false then
                            for iTransport, oTransport in tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits] do
                                if (oTransport[AiBotAir.refiCombatUnitsWanted] or 0) > 0 then
                                    ForkThread(AiBotAir.LoadCombatUnitOntoTransport, oJustBuilt)
                                    break
                                end
                            end
                        end
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryIndirectT3, oJustBuilt.UnitId) then
                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltLotsOfT3Combat]) then
                            if AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryIndirectT3) >= 30 then
                                AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltLotsOfT3Combat] = true
                            end
                        end
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer * categories.TECH3, oJustBuilt.UnitId) then
                        --Late game - destroy lower tech engineers to help with pathing (up to 2 for every T3 engi built)
                        --ConsiderDestroyingLowTechEngineers(oJustBuilt, iOptionalMaxNumberToKill, toOptionalEngineersToConsderKilling, bDontReturnNumberKilled)
                        ForkThread(AiBotEngineer.ConsiderDestroyingLowTechEngineers, oJustBuilt, nil, nil, true)
                        --Moved below to 'oncreate'
                        --First engineer (for if want to check if can build certain modded units) - have done LC<=5 in case the first few engineers we try building die
                        --[[if AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt) <= 5 then
                            ForkThread(AiBotBuilding.AssessT3EngineerConstructionOptions, oJustBuilt)
                        end--]]
                    elseif EntityCategoryContains(categories.MOBILE * categories.SUBMERSIBLE, oJustBuilt.UnitId) then
                        ForkThread(AiBotNavy.DelayedCheckIfShouldSubmerge, oJustBuilt)
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout, oJustBuilt.UnitId) then
                        if not(AiBotTeam.tLandSubteamData[oBrainJustBuilt.AiBotLandSubteam][AiBotTeam.refbConsideredScoutFactionRestrictions]) then
                            AiBotTeam.UpdateFactionBlueprintBlacklist(oBrainJustBuilt.AiBotLandSubteam)
                        end
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryBomber * categories.TECH1, oJustBuilt.UnitId) then
                        if AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt) == 1 then
                            oEngineer[AiBotFactory.refbJustBuiltFirstT1Bomber] = true
                            AiBotUtilities.DelayChangeVariable(oEngineer, AiBotFactory.refbJustBuiltFirstT1Bomber, false, 5)
                        end
                    end

                    --Update economy tracking (this function will check if it is an economic unit as part of it)
                    AiBotEconomy.UpdateGrossIncomeForUnit(oJustBuilt)
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryScathis, oJustBuilt.UnitId) then
                        table.insert(AiBotEngineer.tAllScathis, oJustBuilt)
                    end

                    if EntityCategoryContains(AiBotUnitInfo.refCategorySatellite, oJustBuilt.UnitId) then
                        if bDebugMessages == true then LOG(sFunctionRef..'Novax created, reprs='..reprs(oUnit)) end
                        ForkThread(AiBotAir.DetachSatellite,oJustBuilt, 1)
                    end


                    --Logic based on the engineer
                    if oEngineer:GetAIBrain().AiBotAI then
                        if EntityCategoryContains(categories.COMMAND, oEngineer.UnitId) then
                            AiBotACU.GetACUOrder(oEngineer:GetAIBrain(), oEngineer)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryQuantumGateway + AiBotUnitInfo.refCategoryMobileLandFactory + AiBotUnitInfo.refCategorySpecialFactory + AiBotUnitInfo.refCategoryMobileAircraftFactory + categories.EXTERNALFACTORYUNIT, oEngineer.UnitId) then
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': A factory has just built a unit so will get the next order for the factory, oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer))
                            end
                            ForkThread(AiBotFactory.DecideAndBuildUnitForFactory, oEngineer:GetAIBrain(), oEngineer)
                            --Treat the unit just built as having micro active so it doesn't receive orders for a couple of seconds (so it can clear the factory)
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryNavalFactory + AiBotUnitInfo.refCategoryMobileLandFactory, oEngineer.UnitId) and EntityCategoryContains(categories.MOBILE - categories.AIR, oJustBuilt.UnitId) then
                                --Also give unit a move order (queued onto its existing order)
                                if AiBotUtilities.IsTableEmpty(oEngineer[AiBotFactory.reftFactoryRallyPoint]) then
                                    AiBotFactory.SetFactoryRallyPoint(oEngineer)
                                end

                                AiBotOrders.IssueTrackedMove(oJustBuilt, oEngineer[AiBotFactory.reftFactoryRallyPoint], 0.1, true, 'RollOff', false)

                                AiBotMicro.TrackTemporaryUnitMicro(oJustBuilt, 1.5) --i.e. want to increase likelihood that a unit has exited the land factory before it starts being given orders

                                if bDebugMessages == true then LOG(sFunctionRef..': Engineer parent='..reprs(oEngineer.Parent)..'; Unit ID = or parent'..(oEngineer.Parent.UnitId or 'nil')) end
                                if oEngineer.UnitId == 'uel0401ef' or (oEngineer.Parent.UnitId and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oEngineer.Parent.UnitId)) or EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oEngineer.UnitId) then
                                    --Want some MAA to stick by fatboy so theyre protected by its shield
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryMAA, oJustBuilt.UnitId) then
                                        local oUnitToAssignTo
                                        if oEngineer.Parent.UnitId and EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oEngineer.Parent.UnitId) then oUnitToAssignTo = oEngineer.Parent
                                        else oUnitToAssignTo = oEngineer
                                        end
                                        ForkThread(AiBotLand.ConsiderAssigningMAABodyguardToFatboy,oJustBuilt, oUnitToAssignTo)
                                    end
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory - categories.MOBILE, oEngineer.UnitId) then
                                    --Consider assigning T2 MAA to ACU
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryMAA, oJustBuilt.UnitId) then
                                        if EntityCategoryContains(categories.TECH2, oJustBuilt.UnitId) then
                                            ForkThread(AiBotLand.ConsiderAssigningMAABodyguardToACUOrLandExp, oJustBuilt, true)
                                        elseif EntityCategoryContains(categories.TECH3, oJustBuilt.UnitId) then
                                            ForkThread(AiBotLand.ConsiderAssigningMAABodyguardToACUOrLandExp, oJustBuilt, true, true)
                                        end

                                    end
                                end
                                --Raiding units
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryRaider, oJustBuilt.UnitId) then
                                    ForkThread(AiBotLand.ConsiderAssigningRaider, oEngineer, oJustBuilt)
                                end
                                --Atlantis - surface and release cargo if it has a number of air units
                            elseif oEngineer.UnitId == 'ues0401' and oEngineer.GetCargo then
                                ForkThread(AiBotMicro.ConsiderSurfacingAtlantisToReleaseCargo, oEngineer)
                            end


                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to clear refiFirstTimeOfLastOrder='..(oEngineer[AiBotFactory.refiFirstTimeOfLastOrder] or 'nil')..' for facotyr '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' at game time '..GetGameTimeSeconds()) end
                            if oEngineer[AiBotFactory.refiFirstTimeOfLastOrder] and GetGameTimeSeconds() - oEngineer[AiBotFactory.refiFirstTimeOfLastOrder] > 0.1 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Clearing refiFirstTimeOfLastOrder for the factory') end
                                oEngineer[AiBotFactory.refiFirstTimeOfLastOrder] = nil
                            end --Clear time as only want to use this to track incase have blocking unit
                            oEngineer[AiBotFactory.refiTotalBuildCount] = (oEngineer[AiBotFactory.refiTotalBuildCount] or 0) + 1
                            oEngineer:GetAIBrain()[AiBotFactory.refiHighestFactoryBuildCount] = math.max((oEngineer:GetAIBrain()[AiBotFactory.refiHighestFactoryBuildCount] or 0), (oEngineer[AiBotFactory.refiTotalBuildCount] or 0))
                            --If T3 support factory just built a T1 unit, then consider gifting it to a teammate
                            if EntityCategoryContains(AiBotUnitInfo.categories.SUPPORTFACTORY * categories.TECH3, oEngineer.UnitId) and EntityCategoryContains(categories.TECH1, oJustBuilt.UnitId) then
                                --Do we lack HQs for this brain and are dealing with an air or naval fac (since land fac should rebuild anyway)
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oEngineer.UnitId) then
                                    if oEngineer:GetAIBrain()[AiBotEconomy.refiOurHighestAirFactoryTech] == 0 then
                                        ForkThread(AiBotTeam.ConsiderGiftingSupportFactoriesToTeammateWithBetterHQ, oEngineer:GetAIBrain(), oEngineer.UnitId)
                                    end
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oEngineer.UnitId) then
                                    if oEngineer:GetAIBrain()[AiBotEconomy.refiOurHighestNavalFactoryTech] == 0 then
                                        ForkThread(AiBotTeam.ConsiderGiftingSupportFactoriesToTeammateWithBetterHQ, oEngineer:GetAIBrain(), oEngineer.UnitId)
                                    end
                                end
                            end

                            --External factories that have just built an air unit - unload the air unit
                            if EntityCategoryContains(categories.EXTERNALFACTORYUNIT, oEngineer.UnitId) and EntityCategoryContains(categories.AIR - categories.EXPERIMENTAL, oJustBuilt.UnitId) and oEngineer.Parent.UnitId then
                                local oParentUnit = oEngineer.Parent
                                if bDebugMessages == true then LOG(sFunctionRef..': Just built unit state='..AiBotUnitInfo.GetUnitState(oJustBuilt)..'; Will try and unload from the engineer; reprs='..reprs(oEngineer)..'; oParentUnit UnitID='..(oParentUnit.UnitId or 'nil')) end
                                local tCargo = oParentUnit:GetCargo()
                                if AiBotUtilities.IsTableEmpty(tCargo) == false then
                                    AiBotOrders.ReleaseStoredUnits(oParentUnit, false, 'Carrier', false)
                                end
                            end

                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oEngineer.UnitId) then
                            --Clear any engineers trying to build this unit if we just built a building or experimental
                            if not(bDontClearEngineer) and EntityCategoryContains(categories.STRUCTURE + categories.EXPERIMENTAL, oJustBuilt.UnitId) then
                                AiBotEngineer.ClearEngineersBuildingUnit(oEngineer, oJustBuilt, true)
                            end
                        end
                    end

                    --Logic based on the type of unit built
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryQuantumGateway + AiBotUnitInfo.refCategoryMobileLandFactory + AiBotUnitInfo.refCategorySpecialFactory + AiBotUnitInfo.refCategoryMobileAircraftFactory + categories.EXTERNALFACTORYUNIT, oJustBuilt.UnitId) then
                        if bDebugMessages == true then LOG(sFunctionRef..': A factory has just been built so will get the next order for the factory') end
                        --If our team has a paragon then add a 66% chance we xfer the factory to the paragon owner
                        local oParagonBrainToTransferTo
                        if (AiBotOrders.bDontConsiderCombinedArmy or oJustBuilt.AiBotActive) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] and not(oBrainJustBuilt[AiBotEconomy.refbBuiltParagon]) and math.random(1,3) < 3 and EntityCategoryContains(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryQuantumGateway - AiBotUnitInfo.refCategoryAllHQFactories, oJustBuilt.UnitId) then
                            local oParagonBrain
                            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                if oBrain[AiBotEconomy.refbBuiltParagon] then oParagonBrainToTransferTo = oBrain break end
                            end
                        end
                        if oParagonBrainToTransferTo then
                            ForkThread(AiBotTeam.TransferUnitsToPlayer, { oJustBuilt }, oParagonBrainToTransferTo:GetArmyIndex(), false)
                        else
                            ForkThread(AiBotFactory.DecideAndBuildUnitForFactory, oBrainJustBuilt, oJustBuilt)

                            if EntityCategoryContains(AiBotUnitInfo.refCategoryAllHQFactories, oJustBuilt.UnitId) then
                                oBrainJustBuilt[AiBotEconomy.refiOurHighestFactoryTechLevel] = math.max(AiBotUnitInfo.GetUnitTechLevel(oJustBuilt), oBrainJustBuilt[AiBotEconomy.refiOurHighestFactoryTechLevel])
                            end
                        end
                    elseif EntityCategoryContains(categories.STEALTH, oJustBuilt.UnitId) or (oJustBuilt:GetBlueprint().Intel.RadarStealth and oJustBuilt:GetBlueprint().General.OrderOverrides.RULEUTC_StealthToggle) then
                        --Make sure stealth is enabled
                        AiBotUnitInfo.EnableUnitStealth(oJustBuilt)
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryPower + AiBotUnitInfo.refCategoryT3Mex, oJustBuilt.UnitId) then
                        --Consider gifting power and t3 mexes to a teammate if we have a paragon
                        if bDebugMessages == true then LOG(sFunctionRef..': Just built mex or pgen for brain '..oBrainJustBuilt.Nickname..'; considering if we have paragon and (if so) will gift the unit, builtparagon='..tostring(oBrainJustBuilt[AiBotEconomy.refbBuiltParagon])..'; Brain type='..(oBrainJustBuilt.BrainType or 'nil')..'; Brain gross mass='..oBrainJustBuilt[AiBotEconomy.refiGrossMassBaseIncome]..'; Gross E='..oBrainJustBuilt[AiBotEconomy.refiGrossEnergyBaseIncome]) end
                        if oBrainJustBuilt[AiBotEconomy.refbBuiltParagon] and not(oBrainJustBuilt.BrainType == 'Human') and oBrainJustBuilt[AiBotEconomy.refiGrossMassBaseIncome] >= math.min(1000, 900 * oBrainJustBuilt[AiBotEconomy.refiBrainResourceMultiplier]) and oBrainJustBuilt[AiBotEconomy.refiGrossEnergyBaseIncome] >=  math.min(100000, 90000 * oBrainJustBuilt[AiBotEconomy.refiBrainResourceMultiplier]) then
                            local oParagonBrain = oBrainJustBuilt
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 then
                                for iBrain, oBrain in  AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                    if not(oBrain == oParagonBrain) and not(oBrain.AiBotIsDefeated) and oBrain[AiBotEconomy.refiGrossMassBaseIncome] < 1000 then
                                        ForkThread(AiBotTeam.TransferUnitsToPlayer, { oJustBuilt }, oParagonBrain:GetArmyIndex(), false)
                                        break
                                    end
                                end
                            end
                            --Check if we own any paused non-mexes that we own, and unpause them
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount] > 0 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority]) == false then
                                for iPriority, tUnits in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority] do
                                    for iPaused, oPaused in tUnits do
                                        if AiBotUnitInfo.IsUnitValid(oPaused) and oPaused:GetAIBrain() == oParagonBrain then
                                            AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oPaused, false, false, oParagonBrain.AiBotTeam)
                                        end
                                    end
                                end
                            end
                        end
                        --Remaining categories where have a paragon on team:
                    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] and (AiBotOrders.bDontConsiderCombinedArmy or oJustBuilt.AiBotActive) then
                        --Gift 66% of T3 engineers and SACUs built to paragon owner and all t1-t2 mexes
                        if not(oBrainJustBuilt[AiBotEconomy.refbBuiltParagon]) then
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer + categories.SUBCOMMANDER, oJustBuilt.UnitId) then
                                if math.random(1, 3) < 3 then
                                    local oParagonBrain = oBrainJustBuilt
                                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 then
                                        for iBrain, oBrain in  AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                            if not(oBrain == oParagonBrain) and not(oBrain.AiBotIsDefeated) and oBrain[AiBotEconomy.refiGrossMassBaseIncome] < 1000 then
                                                ForkThread(AiBotTeam.TransferUnitsToPlayer, { oJustBuilt }, oParagonBrain:GetArmyIndex(), false)
                                                break
                                            end
                                        end
                                    end
                                end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryT1Mex + AiBotUnitInfo.refCategoryT2Mex, oJustBuilt.UnitId) then
                                local oParagonBrain = oBrainJustBuilt
                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 then
                                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                        if not(oBrain == oParagonBrain) and not(oBrain.AiBotIsDefeated) and oBrain[AiBotEconomy.refiGrossMassBaseIncome] < 1000 then
                                            ForkThread(AiBotTeam.TransferUnitsToPlayer, { oJustBuilt }, oParagonBrain:GetArmyIndex(), false)
                                            break
                                        end
                                    end
                                end
                            end
                        else
                            --gift t3 mexes to non-paragon owner
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryT3Mex, oJustBuilt.UnitId) then
                                local oLeastMassNonParagonBrain
                                local iLeastNetMass = 500
                                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                    if not(oBrain[AiBotEconomy.refbBuiltParagon]) and oBrain[AiBotEconomy.refiNetMassBaseIncome] < iLeastNetMass then
                                        iLeastNetMass = oBrain[AiBotEconomy.refiNetMassBaseIncome]
                                        oLeastMassNonParagonBrain = oBrain
                                    end
                                end
                                if oLeastMassNonParagonBrain then
                                    ForkThread(AiBotTeam.TransferUnitsToPlayer, { oJustBuilt }, oLeastMassNonParagonBrain:GetArmyIndex(), false)
                                end
                            elseif oJustBuilt:GetBlueprint().General.UpgradesTo then
                                ForkThread(AiBotEconomy.UpgradeUnit, oJustBuilt, true)
                            end
                        end
                    end

                    --AiBotActive cybran destroyers amphibious toggle
                    if oJustBuilt.AiBotActive and oJustBuilt.UnitId == 'urs0201' and not(AiBotUnitInfo.bDontConsiderCombinedArmy) and oBrainJustBuilt.BrainType == 'Human' then
                        AiBotUnitInfo.EnableLandWalkingForDestroyerOwnedByPlayer(oJustBuilt)
                    end

                    --Mobile land units - give a micro move order so they dont block the factory
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryMobileLand, oJustBuilt.UnitId) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Telling oJustBuilt='..oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)..' to move away from factory '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)) end
                        ForkThread(AiBotMicro.MoveAwayFromFactory, oJustBuilt, oEngineer)
                    end

                    --Unit cap - refresh if are within 25 of the cap since it isnt accurate if have current units
                    if bDebugMessages == true then LOG(sFunctionRef..': will call function to refresh unit cap if we are close, is oJustBuilt valid='..tostring(AiBotUnitInfo.IsUnitValid(oJustBuilt))..'; Close to unit cap='..tostring(oBrainJustBuilt[AiBotOverseer.refbCloseToUnitCap] or false)..'; Expected remaining cap='..(oBrainJustBuilt[AiBotOverseer.refiExpectedRemainingCap] or 'nil')) end
                    if AiBotUnitInfo.IsUnitValid(oJustBuilt) and oBrainJustBuilt[AiBotOverseer.refbCloseToUnitCap] and oBrainJustBuilt[AiBotOverseer.refiExpectedRemainingCap] <= 25 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will check unit cap, time='..GetGameTimeSeconds()) end
                        AiBotOverseer.CheckUnitCap(oBrainJustBuilt)
                    end

                    --air fac restriction - review if campaign in case things have changed if are dealing with the player (dont do for campaign AI though as they sometimes have different settings)
                    if AiBotOverseer.bAirFactoriesCantBeBuilt and AiBotMap.bIsCampaignMap and not(oBrainJustBuilt.CampaignAI) then
                        local tACUs = oBrainJustBuilt:GetListOfUnits(categories.COMMAND, false, true)
                        if AiBotUtilities.IsTableEmpty(tACUs) == false then
                            local sAirFac = AiBotFactory.GetBlueprintThatCanBuildOfCategory(oBrainJustBuilt, AiBotUnitInfo.refCategoryAirFactory, tACUs[1])
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': Just built '..oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)..'; Time='..GetGameTimeSeconds()..'; sAirFac='..(sAirFac or 'nil'))
                                if sAirFac then LOG(sFunctionRef..': Is sAirFac restricted='..tostring(AiBotUnitInfo.IsUnitRestricted(sAirFac, oBrainJustBuilt:GetArmyIndex()))) end
                            end
                            if sAirFac and not(AiBotUnitInfo.IsUnitRestricted(sAirFac, oBrainJustBuilt:GetArmyIndex())) then
                                AiBotOverseer.bAirFactoriesCantBeBuilt = false
                            end
                        end
                    end
                else
                    --Non-AiBot only units

                    --If build an AiBot unit then will record its plateau and LZ; so for non-AiBot AI also want to do this so we have a backup for pathfinding if dont already have something
                    if AiBotUtilities.IsTableEmpty(oJustBuilt[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam]) and not(EntityCategoryContains(categories.AIR, oJustBuilt.UnitId)) then
                        local iPlateau, iLandZone = AiBotMap.GetPathingOverridePlateauAndLandZone(oJustBuilt:GetPosition(), true, oJustBuilt)
                        if not(oJustBuilt[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam]) then oJustBuilt[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam] = {} end
                        if not(oBrainJustBuilt.AiBotTeam) then AiBotUtilities.ErrorHandler('Dont have an assigned team ref for brain '..oBrainJustBuilt.Nickname)
                        else
                            local bRecordedInWaterZone = false
                            if iPlateau and not(iLandZone) then
                                --May be on water
                                local iSegmentX, iSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oJustBuilt:GetPosition())
                                local iWaterZone = AiBotMap.tWaterZoneBySegment[iSegmentX][iSegmentZ]
                                if iWaterZone then
                                    if not(oJustBuilt[AiBotUnitInfo.reftAssignedWaterZoneByTeam]) then oJustBuilt[AiBotUnitInfo.reftAssignedWaterZoneByTeam] = {} end
                                    oJustBuilt[AiBotUnitInfo.reftAssignedWaterZoneByTeam][oBrainJustBuilt.AiBotTeam] = iWaterZone
                                    bRecordedInWaterZone = true
                                end
                            end
                            if not(bRecordedInWaterZone) then
                                if not(iPlateau) or not(iLandZone) then iPlateau, iLandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oJustBuilt:GetPosition()) end
                                if iPlateau == 0 and iLandZone then
                                    if not(oJustBuilt[AiBotUnitInfo.reftAssignedWaterZoneByTeam]) then oJustBuilt[AiBotUnitInfo.reftAssignedWaterZoneByTeam] = {} end
                                    oJustBuilt[AiBotUnitInfo.reftAssignedWaterZoneByTeam][oBrainJustBuilt.AiBotTeam] = iLandZone
                                    bRecordedInWaterZone = true
                                elseif iLandZone and iPlateau then
                                    oJustBuilt[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][oBrainJustBuilt.AiBotTeam] = {iPlateau, iLandZone}
                                else
                                    AiBotUtilities.ErrorHandler('Just built a unit with no valid plateau or zone')
                                end
                            end
                            --[[if (iPlateau or 0) > 0 then
                                if not(oJustBuilt[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam]) then oJustBuilt[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam] = {} end
                                oJustBuilt[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][oBrainJustBuilt.AiBotTeam] = {iPlateau, iLandZone}
                            end--]]
                        end
                    end
                    --Tracking of under construction experimentals
                    if oJustBuilt[AiBotUnitInfo.refbNonAiBotExpConstruction] then
                        local iTeam = oBrainJustBuilt.AiBotTeam
                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoNonAiBotConstructingExpAndT3Navy]) == false then
                            for iRecordedUnit, oRecordedUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoNonAiBotConstructingExpAndT3Navy] do
                                if oRecordedUnit == oJustBuilt then
                                    table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoNonAiBotConstructingExpAndT3Navy], iRecordedUnit)
                                    break
                                end
                            end
                        end
                        oJustBuilt[AiBotUnitInfo.refbNonAiBotExpConstruction] = false
                    end

                end

            else
                --AiBot unit has finished construction, but we have alreayd called the main onconstruction event - have any special logic here that we want to run where this isn't the first time onconstructed has been called?
                --(note - wall building logic - engineers get cleared when the first one completes construction, so will have wall building logic as part of that, so no need to go here)
            end

            --Logic to run every time whether have called onconstruction or not
            --Upgrade tracking (even if have run this already)
            if bDebugMessages == true then LOG(sFunctionRef..': Will refresh upgrade tracking for buildings that have just built a building (i.e. upgrading buildings, was unit just built a structure='..tostring(EntityCategoryContains(categories.STRUCTURE, (oJustBuilt.UnitId or oJustBuilt:GetBlueprint().BlueprintId)))) end
            if oEngineer.GetAIBrain and EntityCategoryContains(categories.STRUCTURE, oEngineer.UnitId) and EntityCategoryContains(categories.STRUCTURE, (oJustBuilt.UnitId or oJustBuilt:GetBlueprint().BlueprintId)) then
                if bDebugMessages == true then LOG(sFunctionRef..': Was just built owned by AiBotAI='..tostring(oJustBuilt:GetAIBrain().AiBotAI or false)) end
                if oJustBuilt:GetAIBrain().AiBotAI or (AiBotUnitInfo.IsUnitValid(oEngineer) and oEngineer:GetAIBrain().AiBotAI) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will update upgrade tracking of the unit that has just been built, oJustBuilt='..(oJustBuilt.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt) or 'nil')..'; oEngineer='..(oEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineer) or 'nil')) end
                    AiBotTeam.UpdateUpgradeTrackingOfUnit(oEngineer, true)
                end
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        end
    end
end

function OnReclaimStarted(oEngineer, oReclaim)
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'OnReclaimStarted'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if oEngineer[AiBotOrders.refiMoveAndBuildStuckCount] then oEngineer[AiBotOrders.refiMoveAndBuildStuckCount] = 0 end
        if AiBotUnitInfo.IsUnitValid(oReclaim) and oReclaim:GetFractionComplete() == 1 and oReclaim:GetAIBrain().AiBotAI and not(oEngineer:GetAIBrain().AiBotAI) and IsAlly(oReclaim:GetAIBrain():GetArmyIndex(), oEngineer:GetAIBrain():GetArmyIndex()) then
            if AiBotOrders.bDontConsiderCombinedArmy or oReclaim.AiBotActive then
                AiBotChat.SendUnitReclaimedMessage(oEngineer, oReclaim)
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnReclaimFinished(oEngineer, oReclaim)
    if AiBotUtilities.bAiBotAIInGame then
        --Update the segment that the reclaim is at, or the engineer if hte reclaim doesnt have one
        local sFunctionRef = 'OnReclaimFinished'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



        if bDebugMessages == true then LOG(sFunctionRef..': oEngineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' has just finished reclaiming; gametime='..GetGameTimeSeconds())
            if not(oEngineer.Dead) then
                local oFocusObject = oEngineer:GetFocusUnit()
                LOG(sFunctionRef..': unit state='..AiBotUnitInfo.GetUnitState(oEngineer)..'; oFocusObject='..(oFocusObject.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFocusObject) or 'nil'))
            end
        end
        if oReclaim and oReclaim.CachePosition then
            --LOG('OnReclaimFinished temp log - remove once confirmed this works - about to update reclaim data near location='..repru(oReclaim.CachePosition))
            ForkThread(AiBotMap.RecordThatWeWantToUpdateReclaimAtLocation, oReclaim.CachePosition, 0)
        else
            --LOG('OnReclaimFinished alt temp log - couldnt find reclaim position so will use engineer position')
            ForkThread(AiBotMap.RecordThatWeWantToUpdateReclaimAtLocation, oEngineer:GetPosition(), 1)
        end

        --AiBot specific
        if AiBotUnitInfo.IsUnitValid(oEngineer) and oEngineer:GetAIBrain().AiBotAI then
            --Was the engineer reclaiming an area? if so check if still nearby reclaim
            if bDebugMessages == true then LOG(sFunctionRef..': oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; oEngineer[AiBotEngineer.refiAssignedAction]='..(oEngineer[AiBotEngineer.refiAssignedAction] or 'nil')..'; Is table of units reclaiming the now reclaimed wreck empty='..tostring(AiBotUtilities.IsTableEmpty(oReclaim[AiBotEngineer.reftUnitsReclaimingUs]))..'; Eng seq count='..(oEngineer[AiBotEngineer.refiSequentialReclaimCount] or 0)) end
            oEngineer[AiBotEngineer.refiSequentialReclaimCount] = (oEngineer[AiBotEngineer.refiSequentialReclaimCount] or 0) + 1
            if oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionReclaimArea then
                local oEngineerBrain = oEngineer:GetAIBrain()
                local bDualGapReclaimAlways = oEngineerBrain.AiBotDualGapReclaimAlways == true
                --Only keep reclaiming if we dont have lots of mass, unless doing low value amounts and been a while since we got new orders
                if bDualGapReclaimAlways or (AiBotTeam.tTeamData[oEngineerBrain.AiBotTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.7 and (oEngineer[AiBotEngineer.refiSequentialReclaimCount] or 0) <= 20) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Engineer sequential reclaim count='..(oEngineer[AiBotEngineer.refiSequentialReclaimCount] or 'nil')) end

                    if bDualGapReclaimAlways and (not oEngineerBrain.AiBotDualGapLastReclaimContinueLog or GetGameTimeSeconds() - oEngineerBrain.AiBotDualGapLastReclaimContinueLog >= 30) then
                        oEngineerBrain.AiBotDualGapLastReclaimContinueLog = GetGameTimeSeconds()
                        LOG('AiBot Dual Gap reclaim continue: army='..tostring(oEngineerBrain:GetArmyIndex())..'; role='..tostring(oEngineerBrain.AiBotDualGapRole)..'; engineer='..tostring(oEngineer.UnitId)..'; sequential='..tostring(oEngineer[AiBotEngineer.refiSequentialReclaimCount])..'; time='..tostring(GetGameTimeSeconds()))
                    end

                    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oEngineer:GetPosition(), true, oEngineer)
                    if (iLandZone or 0) > 0 then
                        local iTeam =  oEngineer:GetAIBrain().AiBotTeam
                        local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam]
                        local iMinReclaimValue = AiBotMap.iSignificantMassThreshold
                        --Do we have unclaimed mexes in this zone?
                        if tLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] then iMinReclaimValue = iMinReclaimValue * 2 end
                        local bWantEnergy = AiBotConditions.WantToReclaimEnergyNotMass(iTeam, iPlateau, iLandZone)
                        if bWantEnergy then
                            if EntityCategoryContains(categories.COMMAND, oEngineer.UnitId) and (AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.5 or oEngineer:GetAIBrain():GetEconomyStored('ENERGY') >= 2000 or oEngineer:GetAIBrain()[AiBotEconomy.refiGrossEnergyBaseIncome] >= 50) then
                                iMinReclaimValue = 150 --only want a tree group
                            elseif not(EntityCategoryContains(categories.COMMAND, oEngineer.UnitId)) then
                                iMinReclaimValue = 12
                            end
                        end
                        if not(EntityCategoryContains(categories.COMMAND, oEngineer.UnitId)) and oEngineer[AiBotEngineer.refiLastReclaimTargetValue] then
                            if (oEngineer[AiBotEngineer.refiSequentialReclaimCount] or 0) <= 6 or oEngineer[AiBotEngineer.refiLastReclaimTargetValue] >= 20 then
                                iMinReclaimValue = math.min(iMinReclaimValue, (oEngineer[AiBotEngineer.refiLastReclaimTargetValue] or 0))
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Just finished reclaiming, will check for high value reclaim near engi, P'..iPlateau..'Z'..iLandZone..'; iMinReclaimValue='..iMinReclaimValue..'; Dist from engi to LZ midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefMidpoint])..'; Engi pos='..repru(oEngineer:GetPosition())..'; LZ midpoint='..repru(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefMidpoint])..'; bWantEnergy='..tostring(bWantEnergy)) end
                        --GetEngineerToReclaimNearbyArea(oEngineer, iPriorityOverride, tLZOrWZTeamData, iPlateauOrPond, iLandOrWaterZone, bWantEnergyNotMass,                   bOnlyConsiderReclaimInRangeOfEngineer, iMinIndividualValueOverride, bIsWaterZone)
                        -- Keep continuous reclaim local to the engineer. A
                        -- full-zone synchronous scan after every wreck was
                        -- the trigger for the late-game simulation stall.
                        AiBotEngineer.GetEngineerToReclaimNearbyArea(oEngineer, nil,              tLZTeamData,        iPlateau,   iLandZone, bWantEnergy, true, iMinReclaimValue)--(tLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] or GetGameTimeSeconds() <= 300 or GetUnitLifetimeCount(oEngineer) <= 5 or AiBotUnitInfo.GetUnitTechLevel(oEngineer) >= 3), iMinReclaimValue)
                    end
                end
            elseif EntityCategoryContains(categories.COMMAND, oEngineer.UnitId) then
                --Only try getting more reclaim if we havent wanted to run recently and we arent trying to move somewhere else
                if GetGameTimeSeconds() - (oEngineer[AiBotACU.refiTimeLastWantedToRun] or 0) >= 2 or (AiBotUnitInfo.GetUnitHealthAndShieldPercent(oEngineer) >= 0.99 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.reftEnemyLandExperimentals]) and AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.refiEnemyT3ArtiCount] <= 1) then
                    AiBotOrders.UpdateRecordedOrders(oEngineer)
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to give a new reclaim order to oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Last order type='..(oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] or 'nil')) end
                    if not(oEngineer[AiBotOrders.reftiLastOrders][1]) or oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueReclaim then
                        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oEngineer:GetPosition(), true, oEngineer)
                        if (iLandZone or 0) > 0 then
                            local iTeam =  oEngineer:GetAIBrain().AiBotTeam
                            local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                            local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                            if bDebugMessages == true then LOG(sFunctionRef..': Will consider giving a reclaim order to the ACU') end
                            AiBotACU.ConsiderNearbyReclaimForACUOrEngineer(iPlateau, iLandZone, tLZData, tLZTeamData, oEngineer, true)
                        end
                    end
                end
            elseif AiBotUtilities.IsTableEmpty(oReclaim[AiBotEngineer.reftUnitsReclaimingUs]) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': about to cancel reclaiming oReclaim if it doesnt exist, IsDestroyed='..tostring(IsDestroyed(oReclaim))..'; is oReclaim.GetHealth nil='..tostring(oReclaim.GetHealth == nil)) end
                local tEngineersToClear = {}
                --Stop engineers 'stop-starting' reclaim order - drafted below in v297 but found different cause of the issue so left in for now as presuming wanted to have all reclaiming units stop and reassess orders in case they all want to e.g. retreat
                --[[if not(IsDestroyed(oReclaim)) and ((oReclaim.GetHealth and oReclaim:GetHealth() > 0) or not(oReclaim.GetHealth)) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Wont clear other engineers') end
                else--]]
                for iEngineer, oEngineer in oReclaim[AiBotEngineer.reftUnitsReclaimingUs] do
                    if AiBotUnitInfo.IsUnitValid(oEngineer) then
                        --Dont include ACU, as in one case had 40% upgraded ACU get cleared
                        if not(EntityCategoryContains(categories.COMMAND, oEngineer.UnitId)) then
                            table.insert(tEngineersToClear, oEngineer)
                        end
                    end
                end
                for iEngineer, oEngineer in tEngineersToClear do
                    AiBotOrders.IssueTrackedClearCommands(oEngineer)
                end
                --end
            end
        end

        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnCreateWreck(tPosition, iMass, iEnergy, oOptionalWreck)
    --Dont check if AiBotbrains are in game yet as can be called at start of game before we have recorded any aiBrain
    if AiBotUtilities.bAiBotAIInGame then
        local bContinue = true
        if oOptionalWreck then iMass = (oOptionalWreck.MaxMassReclaim or iMass) end --issue where iMass shows as being 1 when this is called in some cases
        if not(AiBotMap.bReclaimManagerActive) then
            if GetGameTimeSeconds() >= 20 then
                bContinue = false
            else
                local iWaitCount = 0
                while not(AiBotMap.bReclaimManagerActive) do
                    WaitTicks(1)
                    iWaitCount = iWaitCount + 1
                    if iWaitCount >= 50 and (iWaitCount >= 60 or AiBotUtilities.bFAFActive) then AiBotUtilities.ErrorHandler('Map setup not complete') break end
                end
            end
        end
        if bContinue then
            --High value wrecks (experimentals) - activate special engi logic
            --LOG('TEMPCODE wreck created, iMass='..(iMass or 'nil')..'; oOptionalWreck.MaxMassReclaim='..(oOptionalWreck.MaxMassReclaim or 'nil'))
            if iMass >= 8000 and oOptionalWreck then
                for iCurTeam = 1, AiBotTeam.iTotalTeamCount do
                    if AiBotTeam.tTeamData[iCurTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                        --LOG('TEMPCODE Starting high value reclaim order for team '..iCurTeam)
                        ForkThread(AiBotEngineer.HighValueReclaimOrder, iCurTeam, oOptionalWreck, tPosition)
                    end
                end
            end
            --[[if iMass >= 35 then
                local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tPosition)
                local iReclaimSegmentX, iReclaimSegmentZ = AiBotMap.GetReclaimSegmentsFromLocation(tPosition)
                LOG('OnCreateWreck: Time='..GetGameTimeSeconds()..'; iMass='..iMass..'; tPosition='..repru(tPosition)..'; will record we want to update reclaim at this location, iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; iReclaimSegmentX='..iReclaimSegmentX..'; iReclaimSegmentZ='..iReclaimSegmentZ)
            end--]]
            ForkThread(AiBotMap.RecordThatWeWantToUpdateReclaimAtLocation, tPosition, 0)
        end
    end
end

function OnTransportLoad(oUnit, oTransport, bone)
    if AiBotUtilities.bAiBotAIInGame then
        local aiBrain = oTransport:GetAIBrain()
        if aiBrain.AiBotAI then
            --Reduce engis wanted (in case of delay between this being updated and engineer logic running)
            if EntityCategoryContains(AiBotUnitInfo.refCategoryTransport, oTransport.UnitId) then
                if EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) then
                    if oTransport[AiBotAir.refiEngisWanted] then
                        oTransport[AiBotAir.refiEngisWanted] = math.max(0, oTransport[AiBotAir.refiEngisWanted] - 1)
                    end
                else
                    oTransport[AiBotAir.refiCombatUnitsWanted] = math.max(0, (oTransport[AiBotAir.refiCombatUnitsWanted] or 0) - 1)
                end
                --Clear the last assigned unit
                oTransport[AiBotAir.refoTransportUnitTryingToLoad] = nil
                --Clear any LZTeamData tracking
                if oUnit[AiBotAir.reftCombatDropPlateauAndZone] then
                    local tLZData = AiBotMap.tAllPlateaus[oUnit[AiBotAir.reftCombatDropPlateauAndZone][1]][AiBotMap.subrefPlateauLandZones][oUnit[AiBotAir.reftCombatDropPlateauAndZone][2]]
                    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam]
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport]) == false then
                        for iEntry, oEntry in tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport] do
                            if oEntry == oUnit then
                                table.remove(tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport], iEntry)
                                break
                            end
                        end
                    end
                    oUnit[AiBotAir.reftCombatDropPlateauAndZone] = nil
                    oUnit[AiBotEngineer.refiAssignedAction] = nil
                end
            end

        end
    end
end

function OnTransportUnload(oUnit, oTransport, bone)
    if AiBotUtilities.bAiBotAIInGame then
        if AiBotUnitInfo.IsUnitValid(oTransport) and oTransport:GetAIBrain().AiBotAI then
            oTransport[AiBotAir.refiTransportTimeSpentWaiting] = 0
            oTransport[AiBotAir.refbEmergencyDropActive] = nil
            if oTransport[AiBotAir.refiTargetIslandForDrop] then
                oUnit[AiBotAir.refiLastIslandDrop] = oTransport[AiBotAir.refiTargetIslandForDrop]
                oUnit[AiBotAir.refiTimeLastDropped] = GetGameTimeSeconds()
                if AiBotUnitInfo.IsUnitValid(oUnit) and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) then
                    local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, oUnit:GetAIBrain().AiBotTeam)
                    if tLZOrWZTeamData then tLZOrWZTeamData[AiBotMap.refiTimeLastDroppedEngi] = GetGameTimeSeconds() end
                end
            end
        end
        if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionLoadOntoTransport then oUnit[AiBotEngineer.refiAssignedAction] = nil end
    end
end

function OnDetectedBy(oUnitDetected, iBrainIndex)
    --Appears to be called when iBrainIndex detects oUnitDetected, triggers for teammate units but not own units?
    --For now used to make sure we have up to date unit info

    if AiBotUtilities.bAiBotAIInGame then
        if not(EntityCategoryContains(categories.INSIGNIFICANTUNIT, oUnitDetected.UnitId)) then --redundancy, doesnt look like ubnits like cybran build drones cause this to happen
            local aiBrain = ArmyBrains[iBrainIndex]
            AiBotTeam.ConsiderAssigningUnitToZoneForBrain(aiBrain, oUnitDetected) --This function includes check of whether this is an AiBot brain, and updates last known position

            if aiBrain.AiBotAI then
                if aiBrain.AiBotTeam and not(oUnitDetected[AiBotUnitInfo.refbHaveSeenUnitByTeam][aiBrain.AiBotTeam]) then
                    if not(oUnitDetected[AiBotUnitInfo.refbHaveSeenUnitByTeam]) then oUnitDetected[AiBotUnitInfo.refbHaveSeenUnitByTeam] = {} end
                    oUnitDetected[AiBotUnitInfo.refbHaveSeenUnitByTeam][aiBrain.AiBotTeam] = true
                    if oUnitDetected[AiBotAir.refiTimeLastWantedPriorityAirScout] and EntityCategoryContains(AiBotUnitInfo.refCategoryTMD + AiBotUnitInfo.refCategorySML, oUnitDetected.UnitId) then
                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
                            local tbAirSubteamConsidered = {}
                            for iBrain, oBrain in AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                if not(tbAirSubteamConsidered[oBrain.AiBotAirSubteam]) then
                                    AiBotAir.RemoveUnitFromPriorityScoutTable(oUnitDetected, oBrain.AiBotAirSubteam)
                                    tbAirSubteamConsidered[oBrain.AiBotAirSubteam] = true
                                end
                            end
                            oUnitDetected[AiBotAir.refiTimeLastWantedPriorityAirScout] = nil --redundancy
                        end
                    end
                end
                --Update highest enemy ground unti health
                if AiBotMap.bFirstAiBotTeamHasBeenInitialised and AiBotUnitInfo.IsUnitValid(oUnitDetected) and EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat - categories.COMMAND - categories.SUBCOMMANDER - AiBotUnitInfo.refCategoryLandScout, oUnitDetected.UnitId) then
                    local iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnitDetected)
                    local iMaxHealth = oUnitDetected:GetMaxHealth() + iMaxShield
                    if iMaxHealth > (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyHighestMobileLandHealth] or 0) and AiBotMap.bWaterZoneInitialCreation then
                        AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyHighestMobileLandHealth] = iMaxHealth
                    end
                end
            end
        end
    end
end

function OnCreate(oUnit, bIgnoreMapSetup)
    --LOG('OnCreate pre AiBotInGamecheck, AiBotUtilities.bAiBotAIInGame='..tostring(AiBotUtilities.bAiBotAIInGame))
    if AiBotUtilities.bAiBotAIInGame then
        if not(oUnit.UnitId) then --LOUD compatibility
            if not(AiBotUtilities.bFAFActive) then
                if not(oUnit.EntityId) then oUnit.EntityId = oUnit:GetEntityId() end
                oUnit.UnitId = oUnit:GetBlueprint().BlueprintId
            end
        end

        if AiBotUnitInfo.IsUnitValid(oUnit) and not(EntityCategoryContains(categories.INSIGNIFICANTUNIT, oUnit.UnitId)) then --redundancy, doesnt look like units like cybran build drones cause this to happen

            local sFunctionRef = 'OnCreate'
            local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

            if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time'..GetGameTimeSeconds()..'; oUnit[AiBotOnCrRn]='..tostring(oUnit['AiBotOnCrRn'] or false)..'; AiBotMap.bWaterZoneInitialCreation='..tostring(AiBotMap.bWaterZoneInitialCreation or false)..'; Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; AiBotMap.bWaterZoneInitialCreation='..tostring(AiBotMap.bWaterZoneInitialCreation)..'; Unit brain='..oUnit:GetAIBrain().Nickname..'; Is civliain brain='..tostring(AiBotConditions.IsCivilianBrain(oUnit:GetAIBrain()))..'; Unit fraction complete='..oUnit:GetFractionComplete()..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; UnitID='..(oUnit.UnitId or 'nil')..'; Parent='..(oUnit.Parent.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit.Parent) or 'nil')) end
            if (not(AiBotMap.bMapLandSetupComplete) or not(AiBotMap.bWaterZoneInitialCreation)) and not(bIgnoreMapSetup) then --Start of game ACU creation happens before we have setup the map
                while not(AiBotMap.bMapLandSetupComplete) or not(AiBotMap.bWaterZoneInitialCreation) do
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitTicks(1)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    if GetGameTimeSeconds() >= 5 and AiBotMap.bMapLandSetupComplete and (GetGameTimeSeconds() >= 6 or AiBotUtilities.bFAFActive) then
                        AiBotUtilities.ErrorHandler('Water zone initial creation still not done, will stop waiting now')
                        break
                    end
                end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitTicks(1)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                if AiBotUnitInfo.IsUnitValid(oUnit) then OnCreate(oUnit, true) end
            else
                if not(oUnit['AiBotOnCrRn']) then
                    oUnit['AiBotOnCrRn'] = true
                    oUnit[AiBotUnitInfo.refiTimeCreated] = math.floor(GetGameTimeSeconds())
                    AiBotOverseer.refiRoughTotalUnitsInGame = AiBotOverseer.refiRoughTotalUnitsInGame + 1
                    AiBotUnitInfo.GetUnitLifetimeCount(oUnit) --essential so lifetimecount logic works

                    --All units (not just AiBot specific):
                    AiBotUnitInfo.RecordUnitRange(oUnit)

                    AiBotTeam.ConsiderAssigningUnitToZoneForBrain(oUnit:GetAIBrain(), oUnit) --This function includes check of whether this is an AiBot brain
                    if AiBotMap.bIsCampaignMap then
                        local tiTeamsConsidered = {[(oUnit:GetAIBrain().AiBotTeam or 0)] = true}
                        for iBrain, oBrain in ArmyBrains do
                            if oBrain.AiBotAI and not(tiTeamsConsidered[oBrain.AiBotTeam]) then
                                tiTeamsConsidered[oBrain.AiBotTeam] = true
                                AiBotTeam.ConsiderAssigningUnitToZoneForBrain(oBrain, oUnit)
                            end
                        end
                    end

                    if bDebugMessages == true then LOG(sFunctionRef..': First time AiBotOnCreate has run, just recorded unit ranges for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..'; DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; Unit fraction complete='..oUnit:GetFractionComplete()) end
                    if AiBotConfig.AiBotShowEnemyUnitNames then
                        local sWZOrLZRef = ''
                        if EntityCategoryContains(categories.STRUCTURE, oUnit.UnitId) then
                            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
                            local iWaterZone
                            if (iLandZone or 0) == 0 then
                                iWaterZone = AiBotMap.GetWaterZoneFromPosition(oUnit:GetPosition())
                                if (iWaterZone or 0) > 0 then
                                    sWZOrLZRef = 'P0WZ'..iWaterZone
                                end
                            else
                                sWZOrLZRef = 'P'..(iPlateau or 'x')..'LZ'..iLandZone
                            end
                        end
                        if AiBotConfig.AiBotShowUnitNames then oUnit:SetCustomName(oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..sWZOrLZRef) end
                    end

                    --Units with upgrade - update the base threat value
                    if EntityCategoryContains(categories.SUBCOMMANDER, oUnit.UnitId) or (oUnit.HasEnhancement and EntityCategoryContains(categories.COMMAND, oUnit.UnitId) and (oUnit:HasEnhancement('ResourceAllocation') or oUnit:HasEnhancement('ResourceAllocationAdvanced'))) then
                        AiBotUnitInfo.UpdateUnitCombatMassRatingForUpgrades(oUnit) --Will check if unit has enhancements as part of this
                        if oUnit:GetAIBrain().CheatEnabled then ForkThread(AiBotUnitInfo.FixUnitResourceCheatModifiers, oUnit) end
                    elseif oUnit:GetAIBrain().CheatEnabled and (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive or (not(tonumber(ScenarioInfo.Options.AiBotOvwR or tostring(0)) == 0) and ScenarioInfo.Options.AiBotOvwT)) then
                        ForkThread(AiBotUnitInfo.FixUnitResourceCheatModifiers, oUnit)
                    end

                    --Hydro resource locations
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryHydro, oUnit.UnitId) then
                        --Treat location as no longer having no buildings on it
                        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition(), true, oUnit)
                        if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefHydroUnbuiltLocations]) == false then
                            --LOG('About to loop through hydro locations; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; reprs='..reprs(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefHydroUnbuiltLocations]))
                            for iHydroLocation, tHydroLocation in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefHydroUnbuiltLocations] do
                                if AiBotUtilities.GetDistanceBetweenPositions(tHydroLocation, oUnit:GetPosition()) <= 2 then
                                    table.remove(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefHydroUnbuiltLocations], iHydroLocation)
                                    break
                                end
                            end
                        end
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnit.UnitId) then
                        --Treat location as having buildings on it (if we were treating it as unbuilt previously)
                        ForkThread(AiBotBuilding.OnMexConstructionStarted, oUnit)
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oUnit.UnitId) then
                        AiBotBuilding.RecordUnitsInRangeOfTMLAndAnyTMDProtection(oUnit, nil, true)
                        if oUnit:GetAIBrain().AiBotAI then
                            local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, oUnit:GetAIBrain().AiBotTeam)
                            if tLZTeamData then
                                tLZTeamData[AiBotMap.subrefiTMLLifetimeBuildCount] = (tLZTeamData[AiBotMap.subrefiTMLLifetimeBuildCount] or 0) + 1
                            end
                        end
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryTMD, oUnit.UnitId) then
                        if bDebugMessages == true then LOG(sFunctionRef..': will call TMDJustBuilt for tmd '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..', time='..GetGameTimeSeconds()) end
                        AiBotBuilding.TMDJustBuilt(oUnit)
                    end
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryProtectFromTML, oUnit.UnitId) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will call RecordTMLAndTMDForUnitJustBuilt, time='..GetGameTimeSeconds()) end
                        AiBotBuilding.RecordTMLAndTMDForUnitJustBuilt(oUnit)
                    end

                    --AiBot team specific for constructed units - e.g. radar and sonar that are constructed
                    if (AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or 0) > 0 and oUnit:GetFractionComplete() == 1 then
                        local iTeam = oUnit:GetAIBrain().AiBotTeam
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryRadar, oUnit.UnitId) then
                            AiBotLand.UpdateZoneIntelForRadar(oUnit)
                            if EntityCategoryContains(categories.TECH2, oUnit.UnitId) then
                                ForkThread(AiBotBuilding.ConsiderUpgradingT2Radar, oUnit)
                            end
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategorySonar, oUnit.UnitId) then
                            AiBotNavy.UpdateZoneIntelForSonar(oUnit)
                        elseif EntityCategoryContains(categories.EXPERIMENTAL * categories.MASSFABRICATION, oUnit.UnitId) then
                            if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
                                ForkThread(AiBotBuilding.RecordExperimentalResourceGen, oUnit)
                            end
                        end
                    end

                    --Constructed units (general, i.e. all AI not just AiBot)
                    if oUnit:GetFractionComplete() == 1 then
                        AiBotBuilding.RecordUnitShieldCoverage(oUnit)
                        if EntityCategoryContains(AiBotUnitInfo.refCategorySMD, oUnit.UnitId) then
                            --Cover off scenario where loaded SMD is xferred between players, since AiBot will think an SMD has died and a new one created, i.e. want to avoid abuse of AiBots logic by making it think they have no SMD coverage (when it knows htey do)
                            if oUnit.GetTacticalSiloAmmoCount and oUnit:GetTacticalSiloAmmoCount() > 1 or oUnit:GetWorkProgress() >= 0.8 then
                                oUnit[AiBotUnitInfo.refiTimeOfLastCheck] = GetGameTimeSeconds() - 240 - AiBotBuilding.iTimeForSMDToBeConstructed
                            end
                            --Wall segments created at start of game in large numbers - i.e. for scenario where large parts of map are walled off
                        elseif GetGameTimeSeconds() <= 10 and EntityCategoryContains(AiBotUnitInfo.refCategoryWall, oUnit.UnitId) and AiBotUnitInfo.GetUnitLifetimeCount(oUnit) >= 8 then
                            AiBotLand.TrackWallSegment(oUnit, true)
                        end
                        --Below in case capturedunits function doesnt trigger for a unit transferred toa nother player - so we can track upgrade count (mainly intended to track upgrades on SACUs, for which shield SACUs is the main logic dependent on it)
                        local iUpgradeableUnitsCategory = categories.COMMAND + categories.SUBCOMMANDER
                        if AiBotUtilities.bQuietModActive or AiBotUtilities.bLoudModActive then iUpgradeableUnitsCategory = iUpgradeableUnitsCategory + AiBotUnitInfo.refCategoryFactory * categories.TECH3 end --LOUD and quiet allow factories to upgrade
                        if EntityCategoryContains(iUpgradeableUnitsCategory, oUnit.UnitId) then AiBotACU.UpdateUnitUpgradeCountTrackingIfNotSet(oUnit) end
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnit.UnitId) then
                            AiBotBuilding.OnMexConstructionCompleted(oUnit)
                        end
                    end




                    --AiBot specific:
                    if oUnit:GetAIBrain().AiBotAI then
                        --Set Easy flag
                        if oUnit:GetAIBrain().AiBotEasy then oUnit[AiBotUnitInfo.refbEasyBrain] = true end
                        --AiBotActive flag (enable for all AiBotAI units)
                        if bDebugMessages == true then LOG('Considering if we want to set AiBotActive flag, tonumber(ScenarioInfo.Options.AiBotCombinedArmy or 2)='..tonumber(ScenarioInfo.Options.AiBotCombinedArmy or 2)..'; Is unit an ACU='..tostring(EntityCategoryContains(categories.COMMAND, oUnit.UnitId))..'; Is brain human='..tostring(oUnit:GetAIBrain().BrainType == 'Human')..'; AiBotOrders.bDontConsiderCombinedArmy='..tostring(AiBotOrders.bDontConsiderCombinedArmy or false)) end
                        if not(AiBotOrders.bDontConsiderCombinedArmy) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Toggling AiBotCombinedArmiesShowUI option via consideringcombinedarmy') end
                            oUnit:UpdateStat('AiBotCombinedArmiesShowUI', 1)
                            if not(oUnit:GetAIBrain().BrainType == 'Human') then
                                if bDebugMessages == true then LOG(sFunctionRef..': Set .AiBotActive to true for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by brain '..oUnit:GetAIBrain().Nickname) end
                                oUnit.AiBotActive = true
                                oUnit:UpdateStat('AiBotActive', 1)
                            elseif oUnit:GetAIBrain().AiBotAdminEnabled then
                                oUnit.AiBotActive = true
                                oUnit:UpdateStat('AiBotActive', 1)
                            elseif tonumber(ScenarioInfo.Options.AiBotCombinedArmy or 2) == 3 then
                                --MOBA mode
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if are in MOBA mode or not, and (if in MOBA) then will enable AiBotAI logic for all non-ACU units') end
                                if not(EntityCategoryContains(categories.COMMAND, oUnit.UnitId)) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Enabled AiBotAI logic for the unit') end
                                    oUnit.AiBotActive = true
                                    oUnit:UpdateStat('AiBotActive', 1)
                                    if oUnit.UnitId == 'urs0201' then
                                        AiBotUnitInfo.EnableLandWalkingForDestroyerOwnedByPlayer(oUnit) --for AI it seems to automatically move on land, for players it doesnt
                                    end
                                end
                            elseif tonumber(ScenarioInfo.Options.AiBotCombinedArmy or 2) == 4 then
                                --Sim city mode
                                if EntityCategoryContains(categories.MOBILE - AiBotUnitInfo.refCategoryEngineer - categories.COMMAND + categories.SUBCOMMANDER -AiBotUnitInfo.refCategoryTransport, oUnit.UnitId) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Enabled AiBotAI logic for the unit') end
                                    oUnit.AiBotActive = true
                                    oUnit:UpdateStat('AiBotActive', 1)
                                    if oUnit.UnitId == 'urs0201' then
                                        AiBotUnitInfo.EnableLandWalkingForDestroyerOwnedByPlayer(oUnit) --for AI it seems to automatically move on land, for players it doesnt
                                    end
                                end
                            elseif oUnit:GetFractionComplete() == 1 and oUnit.Parent and oUnit.Parent.AiBotActive and not(oUnit.AiBotActive) and oUnit:GetAIBrain().BrainType == 'Human' and tonumber(ScenarioInfo.Options.AiBotCAInherit or 2) == 1 and not(EntityCategoryContains(categories.COMMAND, oUnit.UnitId)) then --e.g. novax will create a 100% complete unit
                                oUnit.AiBotActive = true
                                oUnit:UpdateStat('AiBotActive', 1)
                                if oUnit.UnitId == 'urs0201' then
                                    AiBotUnitInfo.EnableLandWalkingForDestroyerOwnedByPlayer(oUnit) --for AI it seems to automatically move on land, for players it doesnt
                                end
                            else
                                oUnit:UpdateStat('AiBotActive', 0)
                            end
                        elseif not(ScenarioInfo.Options.AiBotCombinedArmy == 5) then --if is option 4, then user wants the UI button hidden
                            if bDebugMessages == true then LOG(sFunctionRef..': Toggling AiBotCombinedArmiesShowUI option') end
                            oUnit:UpdateStat('AiBotCombinedArmiesShowUI', 1)
                        end

                        --Check for upgrading unit transferred to us
                        if oUnit.IsUpgrade then
                            local aiBrain = oUnit:GetAIBrain()
                            if bDebugMessages == true then LOG(sFunctionRef..': Upgrading hidden unit detected, Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; aiBrain='..aiBrain.Nickname..'; Is table of mexes and factories empty='..tostring(AiBotUtilities.IsTableEmpty(aiBrain[AiBotOverseer.reftoTransferredUnitMexesAndFactoriesByCount]))) end
                            if AiBotUtilities.IsTableEmpty(aiBrain[AiBotOverseer.reftoTransferredUnitMexesAndFactoriesByCount]) == false then
                                local iClosestUnitRef
                                local iClosestUnitTransferCount
                                local iClosestDist = 2
                                local iCurDist


                                for iTransferCount, tUnitTable in aiBrain[AiBotOverseer.reftoTransferredUnitMexesAndFactoriesByCount] do
                                    iClosestUnitRef = nil
                                    if AiBotUtilities.IsTableEmpty(tUnitTable) == false then
                                        for iCompletedUnit, oCompletedUnit in tUnitTable do
                                            if AiBotUnitInfo.IsUnitValid(oCompletedUnit) then
                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oCompletedUnit:GetPosition(), oUnit:GetPosition())
                                                if iCurDist < iClosestDist then
                                                    iClosestDist = iCurDist
                                                    iClosestUnitRef = iCompletedUnit
                                                    iClosestUnitTransferCount = iTransferCount
                                                end
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Finished searching completed units near to unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..', iClosestUnitRef='..(iClosestUnitRef or 'nil')..'; iClosestDist='..iClosestDist) end
                                    if iClosestUnitRef then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will track completed unit '..aiBrain[AiBotOverseer.reftoTransferredUnitMexesAndFactoriesByCount][iClosestUnitTransferCount][iClosestUnitRef].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(aiBrain[AiBotOverseer.reftoTransferredUnitMexesAndFactoriesByCount][iClosestUnitTransferCount][iClosestUnitRef])..' as an upgrading unit, given unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is upgrading and nearby') end
                                        AiBotTeam.UpdateUpgradeTrackingOfUnit(aiBrain[AiBotOverseer.reftoTransferredUnitMexesAndFactoriesByCount][iClosestUnitTransferCount][iClosestUnitRef], false, oUnit.UnitId)
                                        table.remove(aiBrain[AiBotOverseer.reftoTransferredUnitMexesAndFactoriesByCount][iClosestUnitTransferCount], iClosestUnitRef)
                                    end
                                end
                            end
                        end

                        --Penetration fighters - disable airaa micro
                        --[[if oUnit.UnitId == 'uea0303' or oUnit.UnitId == 'ura0303' or oUnit.UnitId == 'uaa0303' or oUnit.UnitId == 'xsa0303' then
                            oUnit[AiBotAir.refbDisableAirAAAttackMicro] = true
                        end--]]

                        --Cover units transferred to us or cheated in or presumably that we have captured - will leave outside the OnCreate flag above in case the oncreate variable transfers over when a unit is captured/gifted
                        --First handle units that are important enough we have logic for while they are part-constructed
                        if oUnit:GetFractionComplete() >= 0.1 and not(oUnit[AiBotUnitInfo.refbConstructionStart]) and EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovaxCentre + AiBotUnitInfo.refCategoryFixedShield, oUnit.UnitId) then
                            --Gameender/t3 arti and fixed shields and SMD - consider shielding/game ender template usage
                            if not(oUnit[AiBotUnitInfo.refbConstructionStart]) and EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovaxCentre + AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategorySMD + AiBotUnitInfo.refCategoryGroundAA * categories.TECH3 + AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryPD - categories.FACTORY - categories.EXTERNALFACTORYUNIT - categories.TECH1, oUnit.UnitId) then
                                --Work out if we are already in a special game ender template area
                                if not(oUnit[AiBotBuilding.reftArtiTemplateRefs]) then
                                    local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, oUnit:GetAIBrain().AiBotTeam)
                                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates]) == false then
                                        local bLikelyInTemplatePosition = false
                                        local bArti = EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovaxCentre, oUnit.UnitId)
                                        for iTemplate, tSubtable in tLZTeamData[AiBotMap.reftActiveGameEnderTemplates] do
                                            if bArti then
                                                if AiBotUtilities.IsTableEmpty(tSubtable[AiBotMap.subrefGEArtiLocations]) == false then
                                                    for iArtiLoc, tArtiLoc in tSubtable[AiBotMap.subrefGEArtiLocations] do
                                                        if AiBotUtilities.GetDistanceBetweenPositions(tArtiLoc, oUnit:GetPosition()) < 2.5 then
                                                            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
                                                            oUnit[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTemplate}
                                                            --Check not already in the table
                                                            local bAlreadyRecorded = false
                                                            if AiBotUtilities.IsTableEmpty(tSubtable[AiBotMap.subrefGEArtiUnits]) == false then
                                                                for iRecordedArti, oRecordedArti in tSubtable[AiBotMap.subrefGEArtiUnits] do
                                                                    if oRecordedArti == oUnit then
                                                                        bAlreadyRecorded = true
                                                                        break
                                                                    end
                                                                end
                                                            end
                                                            if not(bAlreadyRecorded) then
                                                                table.insert(tSubtable[AiBotMap.subrefGEArtiUnits], oUnit)
                                                            end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Added arti unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to template ref='..iTemplate..'; in iLandZone='..iLandZone..'; bAlreadyRecorded='..tostring(bAlreadyRecorded)) end
                                                        end
                                                    end
                                                end
                                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oUnit.UnitId) then --dealing with fixed shield
                                                if AiBotUtilities.IsTableEmpty(tSubtable[AiBotMap.subrefGEShieldLocations]) == false then
                                                    for iShieldLoc, tShieldLoc in tSubtable[AiBotMap.subrefGEShieldLocations] do
                                                        if AiBotUtilities.GetDistanceBetweenPositions(tShieldLoc, oUnit:GetPosition()) < 1 then
                                                            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
                                                            oUnit[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTemplate}
                                                            --Check not already in the table (redundancy)
                                                            local bAlreadyRecorded = false
                                                            if AiBotUtilities.IsTableEmpty(tSubtable[AiBotMap.subrefGEShieldUnits]) == false then
                                                                for iRecordedShield, oRecordedShield in tSubtable[AiBotMap.subrefGEShieldUnits] do
                                                                    if oRecordedShield == oUnit then
                                                                        bAlreadyRecorded = true
                                                                        break
                                                                    end
                                                                end
                                                            end
                                                            if not(bAlreadyRecorded) then
                                                                table.insert(tSubtable[AiBotMap.subrefGEShieldUnits], oUnit)
                                                            else
                                                                if bDebugMessages == true then LOG(sFunctionRef..': Wont add shield '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' against GE template as it was already recorded') end
                                                            end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Added shiled unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to template ref='..iTemplate..'; in iLandZone='..iLandZone..' unless already recorded, bAlreadyRecorded='..tostring(bAlreadyRecorded)) end
                                                        end
                                                    end
                                                end
                                            elseif EntityCategoryContains(AiBotUnitInfo.refCategorySMD, oUnit.UnitId) then
                                                if AiBotUtilities.IsTableEmpty(tSubtable[AiBotMap.subrefGESMDLocation]) == false and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(),tSubtable[AiBotMap.subrefGESMDLocation]) < 1 then
                                                    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
                                                    oUnit[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTemplate}
                                                    tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplate][AiBotMap.subrefGESMDUnit] = oUnit
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Recorded SMD as being in arti template location, SMD Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iTemplate='..iTemplate..'; Time='..GetGameTimeSeconds()) end
                                                end
                                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryGroundAA + AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryPD, oUnit.UnitId) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': will add unit to table of defences for this reference') end
                                                local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
                                                oUnit[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTemplate}
                                                if not(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplate][AiBotMap.subrefGEDefenceUnits]) then tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplate][AiBotMap.subrefGEDefenceUnits] = {} end
                                                table.insert(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplate][AiBotMap.subrefGEDefenceUnits], oUnit)
                                            else AiBotUtilities.ErrorHandler('Unrecognised category when checking if constructed unit is in arti template area', true)
                                            end
                                        end
                                    end
                                    --Special shielding and air defence logic
                                    if not(oUnit[AiBotBuilding.reftArtiTemplateRefs]) and EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti, oUnit.UnitId) then
                                        AiBotBuilding.ReserveLocationsForGameEnder(oUnit)
                                        AiBotAir.AddPriorityAirDefenceTarget(oUnit)
                                    end
                                end
                            end
                        end

                        --Land scout special logic for AiBotAI units - consider making a combat land scout
                        if oUnit[AiBotUnitInfo.refiCombatRange] >= 26 and oUnit:GetAIBrain()[AiBotOverseer.refiCombatLandScoutThreshold] > 0 and EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout, oUnit.UnitId) and AiBotUnitInfo.GetUnitLifetimeCount(oUnit) <= oUnit:GetAIBrain()[AiBotOverseer.refiCombatLandScoutThreshold]  then
                            local aiBrain = oUnit:GetAIBrain()
                            if aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 2 or AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestEnemyGroundTech] >= 2 then
                                aiBrain[AiBotOverseer.refiCombatLandScoutThreshold] = 0
                            else
                                oUnit[AiBotUnitInfo.refbScoutCombatOverride] = true
                            end
                        end

                        if bDebugMessages == true then LOG(sFunctionRef..': Considering special logic for units created via cheat or transfer, fraction complete='..oUnit:GetFractionComplete()) end
                        if oUnit:GetFractionComplete() == 1 then
                            if EntityCategoryContains(AiBotUnitInfo.refCategorySML + AiBotUnitInfo.refCategoryTML, oUnit.UnitId) then
                                --put here as extra redundancy since the 'unpause unit on transfer' code which has something similar didnt fix an issue with a loaded yolona being transferred not then firing
                                --LOG('Forked consideration of launching missile Delay5')
                                ForkThread(AiBotBuilding.DelayedConsiderLaunchingMissile, oUnit, 15, true)
                            end


                            AiBotEconomy.UpdateHighestFactoryTechLevelForBuiltUnit(oUnit) --this includes a check to see if are dealing with a factory HQ
                            AiBotEconomy.UpdateGrossIncomeForUnit(oUnit, false) --This both includes a check of the unit type, and cehcks we havent already recorded
                            if EntityCategoryContains(categories.STEALTH, oUnit.UnitId) or (oUnit:GetBlueprint().Intel.RadarStealth and oUnit:GetBlueprint().General.OrderOverrides.RULEUTC_StealthToggle) then
                                --Make sure stealth is enabled
                                AiBotUnitInfo.EnableUnitStealth(oUnit)
                            end
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnit.UnitId) and not(oUnit.AiBotOnConstructedCalled) then
                                if bDebugMessages == true then LOG(sFunctionRef..': we have just built a mex so will call logic relating to that') end
                                ForkThread(AiBotEconomy.UpdateZoneAiBotMexByTechCount, oUnit) --we run the same logic via onconstructed
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryParagon, oUnit.UnitId) and not(oUnit.AiBotOnConstructedCalled) then
                                if bDebugMessages == true then LOG(sFunctionRef..': We have just built a paragon, will call special paragon logic') end
                                ForkThread(AiBotBuilding.JustBuiltParagon, oUnit)
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMassStorage, oUnit.UnitId) and not(oUnit.AiBotOnConstructionCalled) then
                                AiBotBuilding.ConsiderGiftingMassStorageToNearbyMexOwner(oUnit)
                                --Campaign specific - expand core zones for campaign AI
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandHQ + AiBotUnitInfo.refCategoryAirHQ + categories.COMMAND, oUnit.UnitId) and AiBotMap.bIsCampaignMap and oUnit:GetAIBrain().CampaignAI then
                                local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, oUnit:GetAIBrain().AiBotTeam)
                                tLZTeamData[AiBotMap.subrefbCoreBaseOverride] = true
                                if bDebugMessages == true then
                                    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                                    LOG(sFunctionRef..': Will set core baes override to true for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' for brain '..oUnit:GetAIBrain().Nickname..' team, iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone)
                                end
                                if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) and oUnit:GetAIBrain().CampaignAI and (not(AiBotUnitInfo.IsUnitValid(oUnit:GetAIBrain()[AiBotACU.refoPrimaryACU])) or not(EntityCategoryContains(categories.COMMAND, oUnit:GetAIBrain()[AiBotACU.refoPrimaryACU]))) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will run ACU thread for this unit') end
                                    ForkThread(AiBotACU.ManageACU, oUnit:GetAIBrain(), oUnit)
                                end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryBomber * categories.TECH3, oUnit.UnitId) then
                                if AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 1 and not(oUnit[AiBotAir.refbBomberUsingMexHunterLogic]) then
                                    ForkThread(AiBotAir.ApplyMexHuntingLogicToBomber, oUnit)
                                end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryPower, oUnit.UnitId) then --In LOUD t2 pgen upgrades to t3 are as efficient as t3 pgens
                                local sUpgrade = oUnit:GetBlueprint().General.UpgradesTo
                                if sUpgrade and not(sUpgrade == '') then
                                    ForkThread(AiBotEconomy.ConsiderPowerPgenUpgrade, oUnit)
                                end
                            end

                            --Nuke launcher - if have 5+ non-experimental then consider unpausing all existing ones
                            if EntityCategoryContains(AiBotUnitInfo.refCategorySML, oUnit.UnitId) then
                                ForkThread(AiBotOverseer.ConsiderUnpausingAllCreatedNukes, oUnit:GetAIBrain().AiBotTeam)
                            end
                            --Consider unpausing this unit regardless of whether it's an SML
                            ForkThread(AiBotOverseer.DelayedUnpauseOfUnits, {oUnit}, 1)
                            if EntityCategoryContains(AiBotUnitInfo.refCategorySatellite, oUnit.UnitId) then
                                if bDebugMessages == true then LOG(sFunctionRef..'Novax created, reprs='..reprs(oUnit)) end
                                ForkThread(AiBotAir.DetachSatellite,oUnit, 1)
                            end

                            --If we have paragon and unit can upgrade (e.g. we have just had units xfer to us from teammate) then start upgrade
                            if oUnit:GetAIBrain()[AiBotEconomy.refbBuiltParagon] then
                                if oUnit:GetBlueprint().General.UpgradesTo then
                                    ForkThread(AiBotEconomy.UpgradeUnit, oUnit, true)
                                end
                            end
                        end
                        --General logic that want to make sure runs on AiBot units even if theyre not constructed yet or to ensure we cover scenarios where we are gifted units
                        local aiBrain = oUnit:GetAIBrain()
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel - AiBotUnitInfo.refCategorySatellite, oUnit.UnitId) then
                            AiBotAir.AddPriorityAirDefenceTarget(oUnit)
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId) then
                                AiBotUnitInfo.SetUnitWeaponTargetPriorities(oUnit, AiBotUnitInfo.refWeaponPriorityFatboy, true)
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMegalith, oUnit.UnitId) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Setting weapon priorities for megalith') end
                                AiBotUnitInfo.SetUnitWeaponTargetPriorities(oUnit, AiBotUnitInfo.refWeaponPriorityMegalith, true)
                            end
                            --Track priority units for mobile stealth (want to consider stealthing even if under construction, hence do at this stage)
                            if AiBotMap.iMapSize >= 500 and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental - categories.STEALTHFIELD - categories.url0402, oUnit.UnitId) then
                                --Want to build mobile stealth if we have cybran on the team
                                local iLandSubteam = oUnit:GetAIBrain().AiBotLandSubteam
                                if (AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionCybran][3] or 0) > 0 or (AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionCybran][2] or 0) > 0 then
                                    if not(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingMobileStealth]) then AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingMobileStealth] = {} end
                                    table.insert(AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.reftoPriorityUnitsWantingMobileStealth], oUnit)
                                end
                            end
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnit.UnitId) then
                            --Check for rare case where enemy base is taken over by us but enemy isnt dead (doing here instead of onconstructed as onconstructed wouldnt trigger consistently)
                            local iMexPlateau, iMexZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                            local iTeam = oUnit:GetAIBrain().AiBotTeam
                            local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                            --Redundancy for case where enemy nearest us loses their base
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have built on enemy base even if they arent dead, P'..iMexPlateau..'Z'..iMexZone..';mod dist%='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Enemy total mass='..(tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 'nil')..'; Dist from midpoint to closest enemy base='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase])..'; Number of enemy brains='..table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains])..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Brain owner='..oUnit:GetAIBrain().Nickname..'; Enemy combat='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; Our combat='..(tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 'nil')) end
                            if tLZTeamData[AiBotMap.refiModDistancePercent] == 1 and GetGameTimeSeconds() >= 60 and not(AiBotMap.bIsCampaignMap) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains]) == false and table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains]) >= 2 and AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]) <= 5 then
                                if (tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) == 0 then
                                    --Enemy base is likely destroyed since they have no mass here
                                    if bDebugMessages == true then LOG(sFunctionRef..': No enemy buildings, so will update nearest enemy base') end
                                    ForkThread(AiBotMap.RecordClosestAllyAndEnemyBaseForEachLandZone, iTeam, true)
                                end
                                --Either way do a check, in case we didnt update to ignore the brain
                                if tLZTeamData[AiBotMap.subrefLZSValue] >= (tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) and (tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) <= 1000 and tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 500 and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] < math.min(200, tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] * 0.1) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy still has some buildings, so will do a delayed check if we want to update nearest base and iTicksPerLandCycle is relatively high, iTicksPerLandCycle='..AiBotLand.iTicksPerLandCycle) end
                                    ForkThread(AiBotMap.DelayedConsiderationOfWhetherToIgnoreEnemyBase, tLZData, tLZTeamData, iTeam, iMexPlateau, iMexZone, 30)
                                end
                            end

                            --WEAPON PRIORITIES
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryGunship, oUnit.UnitId) then
                            AiBotUnitInfo.SetUnitWeaponTargetPriorities(oUnit, AiBotUnitInfo.refWeaponPriorityGunship, true)
                            oUnit[AiBotUnitInfo.refbUsingDefaultWeaponPriority] = true
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryDestroyer, oUnit.UnitId) then
                            AiBotUnitInfo.SetUnitWeaponTargetPriorities(oUnit, AiBotUnitInfo.refWeaponPriorityDestroyer, true)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMissileShip + AiBotUnitInfo.refCategoryCruiser, oUnit.UnitId) then
                            AiBotUnitInfo.SetUnitWeaponTargetPriorities(oUnit, AiBotUnitInfo.refWeaponPriorityMissileShip, true)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryBattleship, oUnit.UnitId) then
                            AiBotUnitInfo.SetUnitWeaponTargetPriorities(oUnit, AiBotUnitInfo.refWeaponPriorityBattleShip, true)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oUnit.UnitId) then
                            AiBotUnitInfo.SetUnitWeaponTargetPriorities(oUnit, AiBotUnitInfo.refWeaponPriorityT2Arti, true)
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryQuantumOptics, oUnit.UnitId) then
                            local iTeam = aiBrain.AiBotTeam
                            local bAlreadyRecorded = false
                            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoAlliedQuantumOptics]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoAlliedQuantumOptics] = {}
                            else
                                for iRecorded, oRecorded in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoAlliedQuantumOptics] do
                                    if oRecorded == oUnit then
                                        bAlreadyRecorded = true
                                        break
                                    end
                                end
                            end
                            if not(bAlreadyRecorded) then
                                table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoAlliedQuantumOptics], oUnit)
                                ForkThread(AiBotBuilding.QuantumOpticsManager, aiBrain, oUnit)
                            end
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategorySubmarine, oUnit.UnitId) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Setting weapon priority for submarinte='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                            AiBotUnitInfo.SetUnitWeaponTargetPriorities(oUnit, AiBotUnitInfo.refWeaponPrioritySub, false) --Dont want to check if can attack ground

                            --1st T3 Engineer - check building construction options
                        elseif AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 1 and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer * categories.TECH3, oUnit.UnitId) then
                            AiBotBuilding.AssessT3EngineerConstructionOptions(oUnit)
                        end


                            --Non-weapon priority logic
                            if bDebugMessages == true then LOG(sFunctionRef..': Is this an external factory='..tostring(EntityCategoryContains(categories.EXTERNALFACTORYUNIT, oUnit.UnitId))..'; Is this an aircraft factory='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryMobileAircraftFactory, oUnit.UnitId))..'; Is it a special factory='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategorySpecialFactory, oUnit.UnitId))) end
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryQuantumGateway + AiBotUnitInfo.refCategoryMobileLandFactory + AiBotUnitInfo.refCategorySpecialFactory + AiBotUnitInfo.refCategoryMobileAircraftFactory + categories.EXTERNALFACTORYUNIT, oUnit.UnitId) then
                        --If have been gifted factory or created via cheat then want to start building something
                            oUnit[AiBotFactory.refiTotalBuildCount] = 0
                            if oUnit:GetFractionComplete() >= 1 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Calling logic to try and build something from this factory') end
                                ForkThread(AiBotFactory.DecideAndBuildUnitForFactory, oUnit:GetAIBrain(), oUnit)
                            end
                        end
                        --Check unit cap
                        if bDebugMessages == true then LOG(sFunctionRef..': Checking if we have too many units, expected remaining cap='..(aiBrain[AiBotOverseer.refiExpectedRemainingCap] or 0)) end
                        if (aiBrain[AiBotOverseer.refiExpectedRemainingCap] or 0) <= 100 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will check the unit cap') end
                            AiBotOverseer.CheckUnitCap(aiBrain)
                        else
                            aiBrain[AiBotOverseer.refiExpectedRemainingCap] = aiBrain[AiBotOverseer.refiExpectedRemainingCap] - 1
                        end
                    elseif AiBotOrders.bDontConsiderCombinedArmy and ScenarioInfo.Options.AiBotCombinedArmy == 2 then --Non-AiBotAI brain, but combined armies is disabled with UI button still to be shown (so people aware of hte option), so flag so the button gets shown
                        oUnit:UpdateStat('AiBotCombinedArmiesShowUI', 1)
                    end
                end
            end
        end
    end
end

function OnCreateBrain(aiBrain, planName, bIsHuman)
    local sFunctionRef = 'OnCreateBrain'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUtilities.bSteamActive then import('/lua/AiBot/AI/Steam/SteamCompatibility.lua').OtherSteamCompatibilityInformation() end
    if bDebugMessages == true then LOG(sFunctionRef..': aiBrain has just been created at time '..GetGameTimeSeconds()..'; Brain nickname='..(aiBrain.Nickname or 'nil')..'; Has setup been run='..tostring(aiBrain['AiBotBrainSetupRun'] or false)..'; Brain type='..(aiBrain.BrainType or 'nil')..'; AiBotTeam (if brain setup)='..(aiBrain.AiBotTeam or 'nil')..'; aiBrain.Civilian='..tostring(aiBrain.Civilian or false)..'; .AiBotAI='..tostring(aiBrain.AiBotAI or false)..'; .M27AI='..tostring(aiBrain.M27AI or false)..'; AiBotOverseer.iTimeOfLatestBrainToCheckForAiBotLogic='..(AiBotOverseer.iTimeOfLatestBrainToCheckForAiBotLogic or 'nil')..'; brain current plan first 6 chars='..string.sub(aiBrain.CurrentPlan or 'nil', 1, 6)..'; Army index='..aiBrain:GetArmyIndex()..';  ScenarioInfo.ArmySetup='..reprs( ScenarioInfo.ArmySetup)..'; reprs for player2='..reprs(ScenarioInfo.ArmySetup['Player2'])..'; AiBotUtilities.bSteamActive='..tostring(AiBotUtilities.bSteamActive or false)) end
    if AiBotOverseer.iTimeOfLatestBrainToCheckForAiBotLogic >= 0 then
        while GetGameTimeSeconds() < AiBotOverseer.iTimeOfLatestBrainToCheckForAiBotLogic + 1 do
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished waiting for AiBotOverseer.iTimeOfLatestBrainToCheckForAiBotLogic (if applicable), Brain='..(aiBrain.Nickname or 'nil')..'; .AiBotAI='..tostring(aiBrain.AiBotAI or false)) end
    if not(aiBrain['AiBotBrainSetupRun']) then
        if AiBotConfig.AiBotRunProfiling then ForkThread(AiBotProfiler.ProfilerActualTimePerTick) end
        if bIsHuman == nil then
            if aiBrain.BrainType == "AI" or not(aiBrain.BrainType) or string.find(aiBrain.BrainType, "AI") then bIsHuman = false else bIsHuman = true end
        end
        if bIsHuman and aiBrain.AiBotAI then
            -- Defensive cleanup for legacy hooks or custom game options.  A
            -- human AiBot brain is valid only after the authenticated admin
            -- request has been recorded in the synchronized allowlist.
            local adminPlayers = ScenarioInfo.Options and ScenarioInfo.Options.AiBotAdminPlayers
            if not(aiBrain.AiBotAdminRequested == true
                and type(adminPlayers) == 'table'
                and adminPlayers[aiBrain.Nickname] == true) then
                WARN('Clearing unauthorized AiBotAI flag from human brain '..tostring(aiBrain.Nickname))
                aiBrain.AiBotAI = false
                aiBrain.AiBotAdminEnabled = false
            end
        end
        if bIsHuman then
            AiBotOverseer.SetAiBotActiveFlag()
        end
        if not(bIsHuman) and AiBotConditions.IsAiBotAIPersonality(aiBrain) then
            aiBrain.AiBotAI = true
            AiBotUtilities.bAiBotAIInGame = true
            --LOG('AiBot in game 1')
        end

        aiBrain['AiBotBrainSetupRun'] = true

        -- Admin-hybrid mode is disabled by default.  It is enabled only after
        -- an authorized admin uses the UI callback/hotkey.

        if bDebugMessages == true then LOG(sFunctionRef..': First time running OnCreateBrain for brain '..(aiBrain.Nickname or 'nil')..'; reprs='..reprs(aiBrain)..'; Brain name='..aiBrain.Name) end
        if not(AiBotUtilities.bAiBotAIInGame) then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        if AiBotUtilities.bAiBotAIInGame then

            while (not(AiBotOverseer.bBeginSessionTriggered) and GetGameTimeSeconds() < 4) do
                if bDebugMessages == true then LOG(sFunctionRef..': bBeginSessionTriggered not true yet, GameTime='..GetGameTimeSeconds()..'; will wait 1 tick; aiBrain='..aiBrain.Nickname) end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitTicks(1)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
            --Make sure we have checked if this is a scenario map (run for each AI to be safe since minimal load and ensures this happens ahead of any other AiBot code)
            AiBotOverseer.CheckIfScenarioMap()
            if bDebugMessages == true then LOG(sFunctionRef..': AiBotMap.bIsCampaignMap='..tostring(AiBotMap.bIsCampaignMap or false)) end

            --Logic to run for all brains
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            -- The global setup normally records every army start before a
            -- human admin can press the hotkey. Reuse that cached result and
            -- avoid a second nav/pathing lookup during activation.
            if not(AiBotMap.PlayerStartPoints[aiBrain:GetArmyIndex()]) then
                AiBotMap.RecordBrainStartPoint(aiBrain)
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

            if bIsHuman then
                LOG('Human player brain '..aiBrain.Nickname..' created; Index='..aiBrain:GetArmyIndex()..'; start position='..repru(AiBotMap.PlayerStartPoints[aiBrain:GetArmyIndex()]))
            else
                --Logic to run just for AiBotAI
                if aiBrain.AiBotAI then
                    --Redundancy - if have M27 brain then change this back to false
                    if aiBrain.M27AI then aiBrain.AiBotAI = false end
                    if bDebugMessages == true then LOG(sFunctionRef..': AiBot brain created, aiBrain.Nickname='..(aiBrain.Nickname or 'nil')) end

                    --Copy of parts of aiBrain OnCreateAI that still want to retain
                    if planName and (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or aiBrain.CreateBrainShared) then
                        aiBrain:CreateBrainShared(planName)
                    end
                    --aiBrain:InitializeEconomyState()
                    aiBrain.BrainType = 'AI'
                    local per = ScenarioInfo.ArmySetup[aiBrain.Name].AIPersonality
                    local cheatPos = string.find(per, 'cheat')
                    if cheatPos then
                        if not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) then
                            local AIUtils = import('/lua/ai/aiutilities.lua')
                            AIUtils.SetupCheat(aiBrain, true)
                            ScenarioInfo.ArmySetup[aiBrain.Name].AIPersonality = string.sub(per, 1, cheatPos - 1)
                        end
                    end

                    --AiBotAIBrainClass.OnCreateAI(aiBrain, planName)
                    ForkThread(AiBotOverseer.AiBotBrainCreated, aiBrain)
                else
                    --LOG('OnCreateBrain hook for Non-AiBot ai with personality '..(ScenarioInfo.ArmySetup[aiBrain.Name].AIPersonality or 'nil'))
                    --Reundancy - check M27 isn't being treated as AiBotAI
                    ForkThread(AiBotOverseer.DelayedM27AiBotBrainCheck, aiBrain)
                end
            end
        end
    elseif aiBrain.AiBotAI and aiBrain.M27AI then
        aiBrain.AiBotAI = false
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function OnMissileImpactTerrain(self, target, position)
    if AiBotUtilities.bAiBotAIInGame then
        --LOG('Missile impact terrain at time '..GetGameTimeSeconds()..'; self='..reprs(self))
        --Was this an AiBot unit?
        --Wait 1 tick to give a chance for damage to process
        WaitTicks(1)
        if AiBotUnitInfo.IsUnitValid(self) and self:GetAIBrain().AiBotAI then
            local sFunctionRef = 'OnMissileImpactTerrain'
            local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

            local tLastOrder = self[AiBotOrders.reftiLastOrders][self[AiBotOrders.refiOrderCount]]

            if bDebugMessages == true then LOG(sFunctionRef..': self='..(self.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(self) or 'nil')..'; target='..reprs(target)..'; position='..repru(position)..'; tLastOrder='..reprs(tLastOrder)..'; self[AiBotBuilding.refiLastTMLMassKills]='..(self[AiBotBuilding.refiLastTMLMassKills] or 'nil')..'; Acual XP='..(self.VetExperience or self.Sync.totalMassKilled or 0)) end
            --Mobile missile logic tracking
            if EntityCategoryContains(categories.MOBILE, self.UnitId) and not( tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueTMLMissile) then
                --(Removed check about if dealt damage recently, as we mightve damaged a shield protruding over the terrain, leaving to us thinking we are dealing damage when we arent)
                if bDebugMessages == true then LOG(sFunctionRef..': Mobile missile launcher that didnt have a luanch TML order, time of last unblocked shot='..GetGameTimeSeconds() - (self[AiBotUnitInfo.refiTimeOfLastUnblockedShot] or 0)) end
                --if not(self[AiBotUnitInfo.refiTimeOfLastUnblockedShot]) or GetGameTimeSeconds() - self[AiBotUnitInfo.refiTimeOfLastUnblockedShot] >= 1.5 then
                    --If we have a target and the angle to the target is similar to the angle to where the missile impacted (suggesting we havent switched targets) then track the shots
                    if bDebugMessages == true then LOG(sFunctionRef..': Is target empty='..tostring(AiBotUtilities.IsTableEmpty(target))..'; tLastOrder[AiBotOrders.subrefoOrderUnitTarget]='..(tLastOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) or 'nil')..'; tLastOrder[AiBotOrders.subrefiOrderType]='..(tLastOrder[AiBotOrders.subrefiOrderType] or 'nil')) end
                    if AiBotUtilities.IsTableEmpty(target) == false and AiBotUnitInfo.IsUnitValid(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) and (EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, tLastOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId) or tLastOrder[AiBotOrders.subrefoOrderUnitTarget]:GetFractionComplete() < 1) and (tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack or tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueGroundAttack) then
                        --Check the target position isn't far from the current unit target
                        if bDebugMessages == true then LOG(sFunctionRef..': Dist between target and unit target position='..AiBotUtilities.GetDistanceBetweenPositions(target, tLastOrder[AiBotOrders.subrefoOrderUnitTarget]:GetPosition())) end
                        if AiBotUtilities.GetDistanceBetweenPositions(target, tLastOrder[AiBotOrders.subrefoOrderUnitTarget]:GetPosition()) <= 5 then
                            tLastOrder[AiBotOrders.subrefoOrderUnitTarget][AiBotUnitInfo.refiMissileShotBlockedCount] = (tLastOrder[AiBotOrders.subrefoOrderUnitTarget][AiBotUnitInfo.refiMissileShotBlockedCount] or 0) + 1
                            if not(self[AiBotUnitInfo.reftoTargetBlockedMissileCountByEntityId]) then self[AiBotUnitInfo.reftoTargetBlockedMissileCountByEntityId] = {} end
                            self[AiBotUnitInfo.reftoTargetBlockedMissileCountByEntityId][tLastOrder[AiBotOrders.subrefoOrderUnitTarget].EntityId] = (self[AiBotUnitInfo.reftoTargetBlockedMissileCountByEntityId][tLastOrder[AiBotOrders.subrefoOrderUnitTarget].EntityId] or 0) + 1
                            if bDebugMessages == true then LOG(sFunctionRef..': Increasing missile shot blocked count by 1, tLastOrder[AiBotOrders.subrefoOrderUnitTarget][AiBotUnitInfo.refiMissileShotBlockedCount]='..tLastOrder[AiBotOrders.subrefoOrderUnitTarget][AiBotUnitInfo.refiMissileShotBlockedCount]) end
                        end
                    end
                --end
                --TML logic tracking
            elseif tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueTMLMissile or AiBotUtilities.IsTableEmpty(target) == false then
                --Did we not gain any mass kills (e.g. mightve hit the ground deliberately for aoe)
                if (self[AiBotBuilding.refiLastTMLMassKills] or 0) == (self.VetExperience or self.Sync.totalMassKilled or 0) then
                    --Have we dealt damage via the ondamaged callback recently?
                    if not(self[AiBotUnitInfo.refiTimeOfLastUnblockedShot]) or GetGameTimeSeconds() - self[AiBotUnitInfo.refiTimeOfLastUnblockedShot] >= 1.5 then
                        if not(self[AiBotBuilding.reftTerrainBlockedTargets]) then self[AiBotBuilding.reftTerrainBlockedTargets] = {} end
                        local tLastTarget = tLastOrder[AiBotOrders.subreftOrderPosition]

                        if AiBotUtilities.IsTableEmpty(tLastTarget) == false then table.insert(self[AiBotBuilding.reftTerrainBlockedTargets], {tLastTarget[1], tLastTarget[2], tLastTarget[3]}) end
                        if AiBotUtilities.IsTableEmpty(tLastTarget) or AiBotUtilities.GetDistanceBetweenPositions(tLastTarget, target) >= 1 then table.insert(self[AiBotBuilding.reftTerrainBlockedTargets], {target[1], target[2], target[3]}) end
                        if bDebugMessages == true then LOG(sFunctionRef..': Added locations to blackist, repru of blacklist='..repru(self[AiBotBuilding.reftTerrainBlockedTargets])) end
                    end
                end
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        end
    end
end

function OnMissileImpact(self, targetType, targetEntity)
    if AiBotUtilities.bAiBotAIInGame then
        --LOG('Missile impact at time '..GetGameTimeSeconds()..'; self='..reprs(self))
        local launcher = self.Launcher
        --AiBot Specific launcher
        if launcher and AiBotUnitInfo.IsUnitValid(launcher) and launcher:GetAIBrain().AiBotAI then
            --Nukes
            if EntityCategoryContains(AiBotUnitInfo.refCategorySML, launcher.UnitId) then
                AiBotBuilding.UpdateForNukeMissileDeath(launcher, self:GetPosition())
            end
        end
    end
end

function OnMapResizeFORSEARCHONLY()  end --So can find onplayableareachange easier
function OnPlayableAreaChange(rect, voFlag)
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'OnPlayableAreaChange'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if bDebugMessages == true then LOG(sFunctionRef..': Playable area change detected, rect='..repru(rect)..'; voFlag='..reprs(voFlag)..'; Time='..GetGameTimeSeconds()..'; bIsCampaignMap='..tostring(AiBotMap.bIsCampaignMap or false)) end
        local ScenarioUtils = import("/lua/sim/scenarioutilities.lua")
        if type(rect) == 'string' then
            rect = ScenarioUtils.AreaToRect(rect)
        end
        if AiBotUtilities.bAiBotAIInGame or GetGameTimeSeconds() <= 5 then
            --Check actually have playable area (to cover bug in a LOUD map where playable area is set to 0,0,0,0
            if not((rect[1] or rect['x0']) == 0 and (rect[2] or rect['y0']) == 0 and (rect[3] or rect['x1']) == 0 and (rect[4] or rect['y1']) == 0) then
                if bDebugMessages == true then LOG(sFunctionRef..': Will call SetupPlayableAreaAndSegmentSizes, rect[1]='..(rect[1] or 'nil')..'; rect[2]='..(rect[2] or 'nil')..'; rect[3]='..(rect[3] or 'nil')..'; rect[4]='..(rect[4] or 'nil')..'; rect[1] == 0='..tostring((rect[1] == 0))..'; rect='..repru(rect)) end
                AiBotMap.SetupPlayableAreaAndSegmentSizes(rect)
            end
        end
        if AiBotMap.bIsCampaignMap or not(ScenarioInfo.type == "skirmish") then
            ForkThread(AiBotOverseer.UpdateMaxUnitCapForRelevantBrains)
            ForkThread(AiBotEngineer.CheckForSpecialCampaignCaptureTargets)
            --Wait 5s then consider campaign special objectives
            ForkThread(AiBotOverseer.ConsiderSpecialCampaignObjectives, nil, nil, nil, nil, nil, nil, nil, nil,  5)
            --Update location of nearest friendly base (intended to help if we are applying AiBotAI to hostile AI)
            ForkThread(AiBotMap.RefreshCampaignStartPositionsAfterDelay, 5)
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function CaptureTriggerAdded(FunctionForOldUnit, FunctionForNewUnit, oUnit)
    --Intended for campaign maps where a capture objective gets captured by the enemy, e.g. black sun control centre
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'CaptureTriggerAdded'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if AiBotUtilities.bAiBotAIInGame and AiBotMap.bIsCampaignMap then
            oUnit[AiBotUnitInfo.refbCampaignTriggerAdded] = true
            if not(EntityCategoryContains(categories.MOBILE, oUnit.UnitId)) then

                if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
                if AiBotUnitInfo.IsUnitValid(oUnit) then
                    local aiBrain
                    if AiBotUtilities.IsTableEmpty(AiBotOverseer.tAllActiveAiBotBrains) == false then
                        for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
                            aiBrain = oBrain
                            if not(oBrain.CampaignAI) then break end
                        end
                        if not(IsAlly(aiBrain:GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex())) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Unit is not an ally so will record as a capture target') end
                            AiBotEngineer.RecordUnitAsCaptureTarget(oUnit)
                        end
                    end
                end
            end
            oUnit[AiBotUnitInfo.refbCampaignTriggerAdded] = true
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function DeathTriggerAdded(oUnit)
    if AiBotUtilities.bAiBotAIInGame then
        oUnit[AiBotUnitInfo.refbCampaignTriggerAdded] = true
        --UEF M2 - research facility gets transferred over meaning old tracking to repair it gets lost
        if oUnit.UnitId == 'uec1201' and ScenarioInfo.ResearchFacility == oUnit and not(oUnit.Dead) and AiBotUnitInfo.GetUnitHealthPercent(oUnit) < 1 and oUnit:GetAIBrain().BrainType == 'Human' then
            --Add to table of units to repair subreftoUnitsToRepair, as it has been transferred from civilian to player 1
            AiBotOverseer.AddCampaignUnitToUnitsToRepair(oUnit, oUnit:GetAIBrain().AiBotTeam)
            --UEF M5 - Send trucks to gateway
        elseif ScenarioInfo.M2TruckGroup1Delay and ScenarioInfo.NumUEFTrucksThroughGate and ScenarioInfo.NumUEFTrucksThroughGate < ScenarioInfo.RequiredUEFTrucks and ScenarioInfo.M3P2.Active and oUnit.UnitId == 'uec0001' then
            WaitSeconds(10) --just in case the trucks move to their starting position
            if not(oUnit.Dead) then
                local rTargetRect = import("/lua/sim/scenarioutilities.lua").AreaToRect('CDR_Gate_Area')
                local tTargetMidpoint = {(rTargetRect['x0'] + rTargetRect['x1'])*0.5 , 0, (rTargetRect['y0'] + rTargetRect['y1'])*0.5}
                ForkThread(AiBotOverseer.UEFMissionSendTruckToTarget, {oUnit}, tTargetMidpoint, 'M3P2')
            end
            --Cybran M3 - only a few trucks get picked up by main logic
        elseif oUnit.UnitId == 'urc0001' and ScenarioInfo.M2BrackmanTrucksCreated and ScenarioInfo.M2BrackmanTrucksDestroyed and ScenarioInfo.M2P2Complete and ScenarioInfo.M2P1Complete and not(ScenarioInfo.M2P3Complete) then
            if not(oUnit[AiBotOverseer.refbCampaignSpecialLoopActive]) then
                local rTargetRect = import("/lua/sim/scenarioutilities.lua").AreaToRect('M2_Gate_Delete_Area')
                local tTargetMidpoint = {(rTargetRect['x0'] + rTargetRect['x1'])*0.5 , 0, (rTargetRect['y0'] + rTargetRect['y1'])*0.5}
                ForkThread(AiBotOverseer.UEFMissionSendTruckToTarget, {oUnit}, tTargetMidpoint, 'M2P3Obj', 600)
            end
        end
    end
end
function CreateUnitReclaimedTrigger(oUnit)
    if AiBotUtilities.bAiBotAIInGame then
        oUnit[AiBotUnitInfo.refbCampaignTriggerAdded] = true
    end
end

function ObjectiveAdded(oObjective, Type, Complete, Title, Description, ActionImage, Target, IsLoading, loadedTag)
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'ObjectiveAdded'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time '..GetGameTimeSeconds()..'; if map setup not complete then will wait for it to be complete, AiBotUtilities.bAiBotAIInGame='..tostring(AiBotUtilities.bAiBotAIInGame or false)) end
        --Wait until map setup complete
        while not(AiBotMap.bMapLandSetupComplete) or not(AiBotMap.bWaterZoneInitialCreation) do
            if GetGameTimeSeconds() >= 10 then break end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end


        if AiBotUtilities.bAiBotAIInGame then
            --Record capture missions
            if bDebugMessages == true then LOG('Have a mission, Title='..Title..'; Description='..Description..'; Target.captured='..(Target.captured or 'nil')..'; reprs of Target='..reprs(Target)) end
            if Target.captured == 0 then
                if bDebugMessages == true then  LOG('Have a capture mission, is target empty='..tostring(AiBotUtilities.IsTableEmpty(Target))) end
                --Record every unit to be captured
                if AiBotUtilities.IsTableEmpty(Target.Units) == false then
                    for iEntry, oUnit in Target.Units do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iEntry='..iEntry..' in Target; Is valid unit='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            AiBotEngineer.RecordUnitAsCaptureTarget(oUnit)
                            if bDebugMessages == true then LOG(sFunctionRef..': WIll record unit as capture target assuming it is in a land zone') end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': size of target units='..table.getn(Target.Units)) end
                    --If only have 1 unit (i.e. is a key location) then flag to fortify
                    if table.getn(Target.Units) == 1 then
                        local oFirstAiBotBrain
                        for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
                            oFirstAiBotBrain = oBrain
                            if not(oBrain.CampaignAI) then
                                break
                            end
                        end
                        local iTeam = oFirstAiBotBrain.AiBotTeam
                        local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(Target.Units[1]:GetPosition())
                        AiBotMap.MarkZoneForFortification(iPlateauOrZero, iLandOrWaterZone, iTeam)
                        if bDebugMessages == true then LOG(sFunctionRef..': flagged to fortify zone for unit '..Target.Units[1].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(Target.Units[1])..' at position '..repru(Target.Units[1]:GetPosition())..'; iTeam='..iTeam) end
                    end
                end
            elseif AiBotUtilities.IsTableEmpty(Target.Units) == false then
                local bOnlyHaveAllies = true
                local bHaveLowHealthAlly = true
                local oFirstAiBotBrain
                for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
                    oFirstAiBotBrain = oBrain
                    if not(oBrain.CampaignAI) then
                        break
                    end
                end
                local iTeam = oFirstAiBotBrain.AiBotTeam
                local tUnitsToRepair = {}
                for iUnit, oUnit in Target.Units do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit)))
                        if AiBotUnitInfo.IsUnitValid(oUnit) then LOG(sFunctionRef..': Unit is valid, Health%='..AiBotUnitInfo.GetUnitHealthPercent(oUnit)..'; Is enemy='..tostring(IsEnemy(oFirstAiBotBrain:GetArmyIndex(),  oUnit:GetAIBrain():GetArmyIndex()))..'; IsAlly='..tostring(IsAlly(oFirstAiBotBrain:GetArmyIndex(),  oUnit:GetAIBrain():GetArmyIndex()))) end
                    end

                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        if IsAlly(oFirstAiBotBrain:GetArmyIndex(),  oUnit:GetAIBrain():GetArmyIndex()) then
                            if bDebugMessages == true then LOG(sFunctionRef..'; Unit is an ally, health%='..AiBotUnitInfo.GetUnitHealthPercent(oUnit)) end
                            if AiBotUnitInfo.GetUnitHealthPercent(oUnit) < 1 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Adding unit to table of units to repair') end
                                table.insert(tUnitsToRepair, oUnit)
                            else
                                bHaveLowHealthAlly = false
                            end
                        else
                            bOnlyHaveAllies = false
                            if IsEnemy(oFirstAiBotBrain:GetArmyIndex(),  oUnit:GetAIBrain():GetArmyIndex()) then
                                --Make sure we are tracking this unit
                                if bDebugMessages == true then LOG(sFunctionRef..': Sent enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to be recorded in case we lack intel of it, is oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam] true for first AiBotbrain='..tostring(oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam][oFirstAiBotBrain.AiBotTeam] or false)) end
                                AiBotTeam.AssignUnitToLandZoneOrPond(oFirstAiBotBrain, oUnit, nil, nil, true)
                                --Track air experimentals as special targets

                                if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAir * categories.EXPERIMENTAL, oUnit.UnitId) then
                                    local bAlreadyIncluded = false
                                    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives] = {}
                                    else
                                        for iRecordedUnit, oRecordedUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives] do
                                            if oRecordedUnit == oUnit then bAlreadyIncluded = true break end
                                        end
                                    end
                                    if not(bAlreadyIncluded) then
                                        table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives], oUnit)
                                    end
                                end
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': bHaveLowHealthAlly='..tostring(bHaveLowHealthAlly)..'; Is table of units to repair empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToRepair))) end
                if bHaveLowHealthAlly and AiBotUtilities.IsTableEmpty(tUnitsToRepair) == false then
                    local iPlateauOrZero, iLandOrWaterZone
                    local iTeam
                    for iBrain, oBrain in ArmyBrains do
                        if oBrain.AiBotAI then
                            iTeam = oBrain.AiBotTeam
                            if not(oBrain.CampaignAI) then
                                break
                            end
                        end
                    end
                    for iEntry, oUnit in tUnitsToRepair do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iEntry='..iEntry..' in tUnitsToRepair; Is valid unit='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            AiBotOverseer.AddCampaignUnitToUnitsToRepair(oUnit, iTeam)
                        end
                    end
                    --If only have 1 unit (i.e. is a key location) then flag to fortify
                    if table.getn(Target.Units) == 1 then
                        local oFirstAiBotBrain
                        for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
                            oFirstAiBotBrain = oBrain
                            if not(oFirstAiBotBrain.CampaignAI) then
                                break
                            end
                        end
                        local iTeam = oFirstAiBotBrain.AiBotTeam
                        local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(Target.Units[1]:GetPosition())
                        AiBotMap.MarkZoneForFortification(iPlateauOrZero, iLandOrWaterZone, iTeam)
                        if bDebugMessages == true then
                            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(Target.Units[1]:GetPosition())
                            LOG(sFunctionRef..': flagged to fortify zone for repair target, ='..Target.Units[1].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(Target.Units[1])..' at position '..repru(Target.Units[1]:GetPosition())..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; Fortify zone flag='..tostring(AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZFortify] or false))
                        end
                    end
                elseif bOnlyHaveAllies then
                    if bDebugMessages == true then LOG(sFunctionRef..': Only have allies so setting priority air defence target and will make sure we arent going to try and reclaim them') end
                    for iUnit, oUnit in Target.Units do
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            AiBotAir.AddPriorityAirDefenceTarget(oUnit)
                            oUnit[AiBotUnitInfo.refbIsReclaimTarget] = false
                            if AiBotUtilities.IsTableEmpty(oUnit[AiBotUnitInfo.refiTeamsWithThisAsReclaimTarget]) == false then
                                if bDebugMessages == true then LOG(sFunctionRef..': We had recorded this as a reclaim target for the following teams - will now remove.'..repru(oUnit[AiBotUnitInfo.refiTeamsWithThisAsReclaimTarget])) end
                                for _, iRecordedTeam in oUnit[AiBotUnitInfo.refiTeamsWithThisAsReclaimTarget] do
                                    local tUnitLZData, tUnitLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iRecordedTeam)
                                    if AiBotUtilities.IsTableEmpty(tUnitLZTeamData[AiBotMap.subreftoUnitsToReclaim]) == false then
                                        for iRecordedUnit, oRecordedUnit in tUnitLZTeamData[AiBotMap.subreftoUnitsToReclaim] do
                                            if oRecordedUnit == oUnit then
                                                table.remove(tUnitLZTeamData[AiBotMap.subreftoUnitsToReclaim], iRecordedUnit)
                                                break
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': If we have a single allied unit, so might be an objective to defend it, size of target.Units='..table.getn(Target.Units)) end
                    if table.getn(Target.Units) == 1 then
                        --Flag to fortify the zone (e.g. cover cases like Cybran Mission 4)
                        if AiBotUnitInfo.IsUnitValid(Target.Units[1]) then
                            local oUnit = Target.Units[1]
                            local iTeam
                            for iBrain, oBrain in ArmyBrains do
                                if oBrain.AiBotAI and not(AiBotConditions.IsCivilianBrain(oBrain)) then
                                    iTeam = oBrain.AiBotTeam
                                    if not(oBrain.CampaignAI) then
                                        break
                                    end
                                end
                            end
                            local tUnitLZData, tUnitLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                            if tUnitLZTeamData then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will record we want to fortify this LZ') end
                                tUnitLZTeamData[AiBotMap.subrefLZFortify] = true
                            end
                        end
                    end
                end
            elseif bDebugMessages == true then LOG(sFunctionRef..': Target.Units is empty; Target.UnitId='..(Target.UnitId or 'nil'))
            end

            --Record units as objective targets generally (used to trigger onkilled callback from upgrades)
            if AiBotUtilities.IsTableEmpty(Target.Units) == false then
                local iTotalTargetUnitCounts = 0
                local iDeadUpgradingTargetUnitCount = 0
                local toDeadUpgradingTargetUnits = {}
                for iUnit, oUnit in Target.Units do
                    iTotalTargetUnitCounts = iTotalTargetUnitCounts + 1
                    if bDebugMessages == true then LOG(sFunctionRef..': Recording we have an objective for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; oUnit[AiBotUnitInfo.refbIssuedUpgrade]='..tostring(oUnit[AiBotUnitInfo.refbIssuedUpgrade] or false)..'; Is Unit.EventCallbacks.OnKilled nil='..tostring(oUnit.EventCallbacks.OnKilled == nil)..'; iTotalTargetUnitCounts='..iTotalTargetUnitCounts) end
                    oUnit[AiBotUnitInfo.refbObjectiveUnit] = true
                    if oUnit.EventCallbacks.OnKilled then
                        --Trigger the on-death for the unit if it is an external factory unit
                        if EntityCategoryContains(categories.EXTERNALFACTORYUNIT, oUnit.UnitId) then
                            oUnit:DoUnitCallbacks('OnKilled')
                            --Also trigger if it is a building unit that can upgrade to another unit, and is showing as dead, was an AiBot unit, and we have a building of a higher tech levle in its place (e.g. for UEF mission 1 where we can upgrade the air factory)
                        elseif oUnit[AiBotUnitInfo.refbIssuedUpgrade] and not(AiBotUnitInfo.IsUnitValid(oUnit)) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Running onkilled clalback') end
                            oUnit:DoUnitCallbacks('OnKilled')
                        end
                    elseif oUnit[AiBotUnitInfo.refbIssuedUpgrade] and oUnit.Dead then
                        iDeadUpgradingTargetUnitCount = iDeadUpgradingTargetUnitCount + 1
                        table.insert(toDeadUpgradingTargetUnits, oUnit)
                    end
                end
                --Issue if upgraded the unit fully before objective called, then it might not have an EventCallback.OnKilled for it; added for UEF SC M1 but didnt solve the problem, left in though as the error message may be useful and it's possible in another scenario it might work
                if bDebugMessages == true then LOG(sFunctionRef..': Checking for redundancy from upgrades canceling objective, oObjective.Active='..tostring(oObjective.Active)..'; Type='..Type..'; iTotalTargetUnitCounts='..iTotalTargetUnitCounts..'; iDeadUpgradingTargetUnitCount='..iDeadUpgradingTargetUnitCount..'; Is oObjective.OnUnitKilled nil='..tostring(oObjective.OnUnitKilled == nil)) end
                if iTotalTargetUnitCounts > 0 and iDeadUpgradingTargetUnitCount == iTotalTargetUnitCounts and Type == 'primary' and oObjective.OnUnitKilled and AiBotUtilities.IsTableEmpty(toDeadUpgradingTargetUnits) == false then
                    AiBotUtilities.ErrorHandler('All primary objective units are dead due to upgrading them, will attempt to trigger onkilled callback, is objective active='..tostring(oObjective.Active or false), true, true)
                    if oObjective.Active then
                        for iUnit, oUnit in toDeadUpgradingTargetUnits do
                            if bDebugMessages == true then LOG(sFunctionRef..': will call OnUnitKilled for oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                            oObjective.OnUnitKilled(oUnit)
                        end
                    end
                end
            end

            --Manual objective checks (e.g. where campaign doesnt use the function for adding objectives)
            AiBotEngineer.CheckForSpecialCampaignCaptureTargets()
            if bDebugMessages == true then LOG(sFunctionRef..': About to check for special campaign objectives') end
            ForkThread(AiBotOverseer.ConsiderSpecialCampaignObjectives,Type, Complete, Title, Description, ActionImage, Target, IsLoading, loadedTag)
        end

        ForkThread(AiBotOverseer.UpdateMaxUnitCapForRelevantBrains)

        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function ReclaimTargetObjectiveAdded(Type, Complete, Title, Description, Target)
    --Triggers when SimObjectives.Reclaim function is called
    --Note that objectiveadded function above will also be triggered
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'ReclaimTargetObjectiveAdded'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time '..GetGameTimeSeconds()..'; if map setup not complete then will wait for it to be complete') end
        --Wait until map setup complete
        while not(AiBotMap.bMapLandSetupComplete) or not(AiBotMap.bWaterZoneInitialCreation) do
            if GetGameTimeSeconds() >= 10 then break end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end


        if AiBotUtilities.bAiBotAIInGame then
            if AiBotUtilities.IsTableEmpty(Target.Units) == false then
                local oFirstAiBotBrain
                for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
                    oFirstAiBotBrain = oBrain
                    if not(oBrain.CampaignAI) then
                        break
                    end
                end
                local iPlateauOrZero, iLandOrWaterZone
                local iTeam = oFirstAiBotBrain.AiBotTeam

                for iEntry, oUnit in Target.Units do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iEntry='..iEntry..' in units to reclaim; Is valid unit='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                        local tLZOrWZData
                        if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; Unit position='..repru(oUnit:GetPosition())) end
                        if iLandOrWaterZone > 0 then
                            local tLZOrWZTeamData
                            if iPlateauOrZero == 0 then --Waterzone
                                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                            else
                                tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                            end
                            if not(tLZOrWZTeamData[AiBotMap.subreftoUnitsToReclaim]) then tLZOrWZTeamData[AiBotMap.subreftoUnitsToReclaim] = {} end
                            table.insert(tLZOrWZTeamData[AiBotMap.subreftoUnitsToReclaim], oUnit)
                            oUnit[AiBotUnitInfo.refbIsReclaimTarget] = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to table of units to reclaim for team '..iTeam..' in iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; iTeam='..iTeam..'; oFirstAiBotBrain='..oFirstAiBotBrain.Nickname..'; Is tLZOrWZTeamData[AiBotMap.subreftoUnitsToReclaim] empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoUnitsToReclaim]))) end
                        end
                    end
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnMissileIntercepted(oLauncher, target, oTMD, position, oProjectile)
    --AiBotAI specific - also exclude if TMD is owned by the same team, as as of 24/09/2023 there's a bug with FAF where this callback triggers with oTMD being another or the same MML
    if AiBotUtilities.bAiBotAIInGame then
        if not(oLauncher.Dead) and AiBotUnitInfo.IsUnitValid(oTMD) and not(oLauncher:GetAIBrain().AiBotTeam == oTMD:GetAIBrain().AiBotTeam) then
            local sFunctionRef = 'OnMissileIntercepted'
            local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            local oLauncherBrain = oLauncher:GetAIBrain()

            --MML - record time that were last intercepted if dealing with non-aeo TMD (used to build more MML) for both the MML and the TMD land zones
            if bDebugMessages == true then LOG('Missile intercepted, oLauncher='..oLauncher.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLauncher)..'; is launcher a nuke='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategorySML, oLauncher.UnitId))..'; is launcher valid='..tostring(AiBotUnitInfo.IsUnitValid(oLauncher))) end
            if EntityCategoryContains(AiBotUnitInfo.refCategoryMML, oLauncher.UnitId) then --and not(EntityCategoryContains(categories.AEON, oTMD.UnitId)) and EntityCategoryContains(AiBotUnitInfo.refCategoryTMD, oTMD.UnitId) then
                local iLauncherTeam = oLauncher:GetAIBrain().AiBotTeam
                if bDebugMessages == true then LOG('MML intercepted by tmd, oLauncher='..(oLauncher.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oLauncher) or 'nil')..'; oTMD='..(oTMD.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTMD) or 'nil')..'; Launcher team='..iLauncherTeam..'; Launcher brain='..oLauncher:GetAIBrain().Nickname..'; TMD nickname='..oTMD:GetAIBrain().Nickname) end
                local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oLauncher:GetPosition(), true, oLauncher)
                if oLauncherBrain.AiBotAI and (iLandZone or 0) > 0 and iPlateau > 0 then
                    local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iLauncherTeam]
                    tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] = GetGameTimeSeconds()
                end
                local iTMDPlateau, iTMDLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oTMD:GetPosition())
                if (iTMDLandZone or 0) > 0 and iTMDPlateau > 0 then
                    if oLauncherBrain.AiBotAI and not(iTMDLandZone == iLandZone and iTMDPlateau == iPlateau) then
                        local tLZTeamData = AiBotMap.tAllPlateaus[iTMDPlateau][AiBotMap.subrefPlateauLandZones][iTMDLandZone][AiBotMap.subrefLZTeamData][iLauncherTeam]
                        tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] = GetGameTimeSeconds()
                    end
                    local oBrainTMD = oTMD:GetAIBrain()
                    if oBrainTMD.AiBotAI then
                        --Replace team data since want to get from TMD team perspective now
                        local tLZTeamData = AiBotMap.tAllPlateaus[iTMDPlateau][AiBotMap.subrefPlateauLandZones][iTMDLandZone][AiBotMap.subrefLZTeamData][oBrainTMD.AiBotTeam]
                        tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] = GetGameTimeSeconds()
                        oTMD[AiBotBuilding.refiTimeTMDHitMissile] = GetGameTimeSeconds()
                        if AiBotUnitInfo.IsUnitValid(oLauncher) then --redundancy
                            local bRecordedAlready = false
                            if not(oTMD[AiBotBuilding.toLaunchersIntercepted]) then oTMD[AiBotBuilding.toLaunchersIntercepted] = {}
                            elseif AiBotConditions.IsTableOfUnitsStillValid(oTMD[AiBotBuilding.toLaunchersIntercepted]) then
                                for iRecordedLauncher, oRecordedLauncher in oTMD[AiBotBuilding.toLaunchersIntercepted] do
                                    if oRecordedLauncher == oLauncher then
                                        bRecordedAlready = true
                                        break
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': About to record oLauncher against TMD table of launchers intercepted if not already recorded, bRecordedAlready='..tostring(bRecordedAlready)..'; oTMD[AiBotBuilding.refiTimeTMDHitMissile]='..(oTMD[AiBotBuilding.refiTimeTMDHitMissile] or 'nil')..'; oTMD='..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)) end
                            if not(bRecordedAlready) then table.insert(oTMD[AiBotBuilding.toLaunchersIntercepted], oLauncher) end
                        end
                    end
                end
                --sometimes the launcher is receiving its orders from an adjacent zone, so want that adjacnet zone's combat logic to recognise this when deciding whether to syncrhonise shots
                if oLauncher.AiBotAI and oLauncher[AiBotLand.refiCurrentAssignmentPlateauAndLZ][2] and not( oLauncher[AiBotLand.refiCurrentAssignmentPlateauAndLZ][2] == iLandZone and oLauncher[AiBotLand.refiCurrentAssignmentPlateauAndLZ][1] == iPlateau) and not( oLauncher[AiBotLand.refiCurrentAssignmentPlateauAndLZ][2] == iTMDLandZone and oLauncher[AiBotLand.refiCurrentAssignmentPlateauAndLZ][1] == iTMDPlateau) then
                    local tAssignedLZTeamData = AiBotMap.tAllPlateaus[oLauncher[AiBotLand.refiCurrentAssignmentPlateauAndLZ][1]][AiBotMap.subrefPlateauLandZones][oLauncher[AiBotLand.refiCurrentAssignmentPlateauAndLZ][2]][AiBotMap.subrefLZTeamData][iLauncherTeam]
                    tAssignedLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] = GetGameTimeSeconds()
                end
            elseif EntityCategoryContains(AiBotUnitInfo.refCategorySML, oLauncher.UnitId) and AiBotUnitInfo.IsUnitValid(oLauncher) then
                if bDebugMessages == true then LOG('Will call nuke missile death logic') end
                AiBotBuilding.UpdateForNukeMissileDeath(oLauncher)
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryTMD, oTMD.UnitId) then
                if oProjectile[AiBotBuilding.refoLastTMLTarget] then oProjectile[AiBotBuilding.refoLastTMLTarget][AiBotBuilding.refbRecheckTMLAndTMDWhenConstructedByTeam] = nil end

                local oBrainTMD = oTMD:GetAIBrain()
                if oBrainTMD.AiBotAI then
                    local iTMDPlateau, iTMDLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oTMD:GetPosition())
                    if (iTMDLandZone or 0) > 0 and iTMDPlateau > 0 then
                        local tLZTeamData = AiBotMap.tAllPlateaus[iTMDPlateau][AiBotMap.subrefPlateauLandZones][iTMDLandZone][AiBotMap.subrefLZTeamData][oBrainTMD.AiBotTeam]
                        tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] = GetGameTimeSeconds()
                        oTMD[AiBotBuilding.refiTimeTMDHitMissile] = GetGameTimeSeconds()
                        if AiBotUnitInfo.IsUnitValid(oLauncher) then --redundancy
                            local bRecordedAlready = false
                            if not(oTMD[AiBotBuilding.toLaunchersIntercepted]) then oTMD[AiBotBuilding.toLaunchersIntercepted] = {}
                            elseif AiBotConditions.IsTableOfUnitsStillValid(oTMD[AiBotBuilding.toLaunchersIntercepted]) then
                                for iRecordedLauncher, oRecordedLauncher in oTMD[AiBotBuilding.toLaunchersIntercepted] do
                                    if oRecordedLauncher == oLauncher then
                                        bRecordedAlready = true
                                        break
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': About to record oLauncher against TMD table of launchers intercepted if not already recorded, bRecordedAlready='..tostring(bRecordedAlready)..'; oTMD[AiBotBuilding.refiTimeTMDHitMissile]='..(oTMD[AiBotBuilding.refiTimeTMDHitMissile] or 'nil')..'; oTMD='..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)) end
                            if not(bRecordedAlready) then
                                table.insert(oTMD[AiBotBuilding.toLaunchersIntercepted], oLauncher)
                                AiBotBuilding.RecordUnitsInRangeOfTMLAndAnyTMDProtection(oLauncher, { oTMD }, false)
                            end
                        end
                    end
                end
                if AiBotUnitInfo.IsUnitValid(oLauncher) and oLauncher:GetAIBrain().AiBotAI and AiBotUtilities.IsTableEmpty(target) == false then
                    --Make sure we have recorded this TMD as a blogking TMD if not already for the launcher/unit
                    local tUnitsNearTarget = oTMD:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryProtectFromTML, target, 3, 'Ally')
                    if AiBotUtilities.IsTableEmpty(tUnitsNearTarget) == false then
                        if bDebugMessages == true then
                            LOG(sFunctionRef..': TMD has intercepted TML missile, so will make sure all units near the target of the missile record that the TMD is protecting them, is tUnitsNearTarget empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsNearTarget))..'; target='..reprs(target)..'; oTMD='..oTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMD)..'; TMD position='..repru(oTMD:GetPosition())..'; position='..repru(position)..'; Is oProjectile[AiBotBuilding.refoLastTMLTarget] nil='..tostring(oProjectile[AiBotBuilding.refoLastTMLTarget] == nil)..'; oProjectile[AiBotBuilding.refoLastTMLTarget]='..(oProjectile[AiBotBuilding.refoLastTMLTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oProjectile[AiBotBuilding.refoLastTMLTarget]) or 'nil'))
                        end
                        for iUnit, oUnit in tUnitsNearTarget do
                            if bDebugMessages == true then LOG(sFunctionRef..': Will record that the TMD is protecting oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' unless will already have covered via oProjectile[AiBotBuilding.refoLastTMLTarget]') end
                            if not(oUnit == oProjectile[AiBotBuilding.refoLastTMLTarget]) then
                                AiBotBuilding.RecordThatTMDProtectsUnitFromTML(oTMD, oUnit, oLauncher)
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is the last TML target valid='..tostring(AiBotUnitInfo.IsUnitValid(oProjectile[AiBotBuilding.refoLastTMLTarget]))..'; Last target='..(oProjectile[AiBotBuilding.refoLastTMLTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oProjectile[AiBotBuilding.refoLastTMLTarget]) or 'nil')) end
                    if AiBotUnitInfo.IsUnitValid(oProjectile[AiBotBuilding.refoLastTMLTarget]) then
                        AiBotBuilding.RecordThatTMDProtectsUnitFromTML(oTMD, oProjectile[AiBotBuilding.refoLastTMLTarget], oLauncher)
                    end
                end
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        end
    end

end

function DelayedUnpauseOfTransferredUnits(toCapturedUnits, iArmyIndex)
    --Tracks transferred units (to help with spotting upgrades for those already in progress), and also unpauses all units
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'DelayedUnpauseOfTransferredUnits'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


        local iCapturedUnitCount
        local aiBrain
        local tFactoriesAndMexes = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryMex, toCapturedUnits)
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code, is tFactoriesAndMexes empty='..tostring(AiBotUtilities.IsTableEmpty(tFactoriesAndMexes))..'; iArmyIndex='..iArmyIndex..'; Time='..GetGameTimeSeconds()) end
        if AiBotUtilities.IsTableEmpty(tFactoriesAndMexes) == false then
            for iBrain, oBrain in ArmyBrains do
                if oBrain:GetArmyIndex() == iArmyIndex then
                    aiBrain = oBrain
                    break
                end
            end
            if aiBrain then
                local tCompletedUnits = {}
                local tUpgradingUnit = {}
                for iUnit, oUnit in tFactoriesAndMexes do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; IsUpgrade='..tostring(oUnit.IsUpgrade or false)..'; Fraction complete='..oUnit:GetFractionComplete()..'; Unit tech level='..AiBotUnitInfo.GetUnitTechLevel(oUnit)) end
                    --if oUnit.IsUpgrade then table.insert(tUpgradingUnit, oUnit)
                    if oUnit:GetFractionComplete() == 1 and  AiBotUnitInfo.GetUnitTechLevel(oUnit) <= 2 then
                        table.insert(tCompletedUnits, oUnit)
                    end
                end
                if AiBotUtilities.IsTableEmpty(tCompletedUnits) == false then
                    aiBrain[AiBotOverseer.refiTransferedUnitCount] = (aiBrain[AiBotOverseer.refiTransferedUnitCount] or 0) + 1
                    iCapturedUnitCount = aiBrain[AiBotOverseer.refiTransferedUnitCount]
                    if not(aiBrain[AiBotOverseer.reftoTransferredUnitMexesAndFactoriesByCount]) then aiBrain[AiBotOverseer.reftoTransferredUnitMexesAndFactoriesByCount] = {} end
                    aiBrain[AiBotOverseer.reftoTransferredUnitMexesAndFactoriesByCount][iCapturedUnitCount] = {}
                    for iUnit, oUnit in tCompletedUnits do
                        table.insert(aiBrain[AiBotOverseer.reftoTransferredUnitMexesAndFactoriesByCount][iCapturedUnitCount], oUnit)
                        --Delayed consideration of launching a missile
                    end
                    local tMissileLaunchers = EntityCategoryFilterDown(categories.SILO, tCompletedUnits)
                    if AiBotUtilities.IsTableEmpty(tMissileLaunchers) == false then
                        local iCurMissiles
                        for iLauncher, oLauncher in tMissileLaunchers do
                            --LOG('Forked consideration of launching missile Delay6')
                            if oLauncher:GetAIBrain().AiBotAI then --redundancy
                                AiBotConditions.DelayedConsiderLaunchingMissile(oLauncher, 1, bCheckHaveMissile)
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of completed units empty='..tostring(AiBotUtilities.IsTableEmpty(tCompletedUnits))..'; Is table of upgrading units empty='..tostring(AiBotUtilities.IsTableEmpty(tUpgradingUnit))) end
                if AiBotUtilities.IsTableEmpty(tCompletedUnits) == false and AiBotUtilities.IsTableEmpty(tUpgradingUnit) == false then
                    local iClosestUnitRef, iClosestDist, iCurDist
                    for iUnit, oUnit in tUpgradingUnit do
                        iClosestDist = 2
                        iClosestUnitRef = nil
                        for iCompletedUnit, oCompletedUnit in tCompletedUnits do
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oCompletedUnit:GetPosition(), oUnit:GetPosition())
                            if iCurDist < iClosestDist then
                                iClosestDist = iCurDist
                                iClosestUnitRef = iCompletedUnit
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Finished searching completed units near to unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..', iClosestUnitRef='..(iClosestUnitRef or 'nil')..'; iClosestDist='..iClosestDist) end
                        if iClosestUnitRef then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will track completed unit '..tCompletedUnits[iClosestUnitRef].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tCompletedUnits[iClosestUnitRef])..' as an upgrading unit, given unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is upgrading and nearby') end
                            AiBotTeam.UpdateUpgradeTrackingOfUnit(tCompletedUnits[iClosestUnitRef], false, oUnit.UnitId)
                            table.remove(tCompletedUnits, iClosestUnitRef)
                        end
                    end
                end
                --Track upgrade count on SACUs and ACUs
                local iUpgradeableUnitsCategory = categories.COMMAND + categories.SUBCOMMANDER
                --LOUD and quiet allow factories to upgrade
                if AiBotUtilities.bQuietModActive or AiBotUtilities.bLoudModActive then iUpgradeableUnitsCategory = iUpgradeableUnitsCategory + AiBotUnitInfo.refCategoryFactory * categories.TECH3 end
                local tUpgradableUnits = EntityCategoryFilterDown(iUpgradeableUnitsCategory, toCapturedUnits)
                if AiBotUtilities.IsTableEmpty(tUpgradableUnits) == false then
                    for iUnit, oUnit in tUpgradableUnits do
                        AiBotACU.UpdateUnitUpgradeCountTrackingIfNotSet(oUnit)
                    end
                end
            end
        end
        --Also flag for every unit that it has been transferred
        for iUnit, oUnit in toCapturedUnits do
            oUnit[AiBotUnitInfo.refbTransferredUnit] = true
        end
        ForkThread(AiBotOverseer.DelayedUnpauseOfUnits,toCapturedUnits, 1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1) --tried 1 tick but it didnt help
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        --[[for iUnit, oUnit in toCapturedUnits do --covered via DelayedUnpauseOfUnits now
            if AiBotUnitInfo.IsUnitValid(oUnit) then
                AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oUnit, false)
            end
        end--]]
        if aiBrain and iCapturedUnitCount then
            aiBrain[AiBotOverseer.reftoTransferredUnitMexesAndFactoriesByCount][iCapturedUnitCount] = nil
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnCaptured(toCapturedUnits, iArmyIndex, bCaptured)
    --looks like if multiple engineers are trying to capture a unit at once this triggers for each engineer
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'OnCaptured'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time'..GetGameTimeSeconds()..', is toCapturedUnits empty='..tostring(AiBotUtilities.IsTableEmpty(toCapturedUnits))..'; Army='..reprs(iArmyIndex)..'; Captured='..reprs(bCaptured)) end
        if AiBotUtilities.bAiBotAIInGame then
            if bCaptured and AiBotUtilities.IsTableEmpty(toCapturedUnits) == false then
                --Below is to cover scenarios like FA Mission 6 where a capture target can be captured by the enemy
                if bDebugMessages == true then
                    LOG(sFunctionRef..': Will cycle through each captured unit')
                    for iUnit, oUnit in toCapturedUnits do
                        LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; owned by '..oUnit:GetAIBrain().Nickname)
                    end
                end

                --Is the unit owned by an enemy to the first AiBotAI in the game?
                local oAiBotBrain
                local oCapturingBrain
                for iBrain, oBrain in ArmyBrains do
                    if not(oAiBotBrain) then
                        if oBrain.AiBotAI then
                            oAiBotBrain = oBrain

                        end
                    end
                    if oBrain:GetArmyIndex() == iArmyIndex then oCapturingBrain = oBrain end
                end


                local bCheckForBlackSun = AiBotMap.bIsCampaignMap
                for iUnit, oUnit in toCapturedUnits do
                    if bDebugMessages == true then LOG(sFunctionRef..': Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; bCheckForBlackSun='..tostring(bCheckForBlackSun)..'; Is M3P2 active='..tostring(ScenarioInfo.M3P2.Active)..'; Unit brain='..oUnit:GetAIBrain().Nickname) end
                    if not(oAiBotBrain.AiBotTeam == oUnit:GetAIBrain().AiBotTeam) and not(IsAlly(oAiBotBrain:GetArmyIndex(), iArmyIndex)) then
                        AiBotEngineer.RecordUnitAsCaptureTarget(oUnit, true)
                        --Cybran M6 - fire black sun if we have just captured it
                    elseif bCheckForBlackSun and oUnit.UnitId == 'uec1901' and ScenarioInfo.M3P2.Active and oUnit:GetAIBrain().AiBotAI and oUnit:GetAIBrain():GetFactionIndex() == AiBotUnitInfo.refFactionCybran then
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to fire black sun to complete cybran campaign - will fire in a bit') end
                        ForkThread(AiBotOverseer.DelayedCybranFireBlackSun, oUnit:GetAIBrain())
                    end
                end
                --Aeon M4 - flag the zone to be fortified (redundancy)
                if bDebugMessages == true then LOG(sFunctionRef..': Aeon M4 check, ScenarioInfo.PlayerCapturedMainframe='..tostring(ScenarioInfo.PlayerCapturedMainframe or false)..'; toCapturedUnits[1].UnitId='..(toCapturedUnits[1].UnitId or 'nil'))
                    LOG(sFunctionRef..': Aeon M6 check - treat as core zone if captured control centre, toCapturedUnits[1].UnitId='..(toCapturedUnits[1].UnitId or 'nil')..'; oCapturingBrain.Nickname='..(oCapturingBrain.Nickname or 'nil'))
                end
                if AiBotMap.bIsCampaignMap then
                    if ScenarioInfo.PlayerCapturedMainframe and (toCapturedUnits[1].UnitId == 'urc1901' or toCapturedUnits[1].UnitId == 'urc1902') then
                        if bDebugMessages == true then LOG(sFunctionRef..': Have captured the mainframe, will cycle through brains to find a human brain to check if it is aeon, and hence if this is likely to be Aeon M4') end
                        for iBrain, oBrain in ArmyBrains do
                            if oBrain.BrainType == 'Human' then
                                if bDebugMessages == true then LOG(sFunctionRef..': Is human brain aeon='..tostring(oBrain:GetFactionIndex() == AiBotUnitInfo.refFactionAeon)) end
                                if oBrain:GetFactionIndex() == AiBotUnitInfo.refFactionAeon then
                                    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(toCapturedUnits[1]:GetPosition())
                                    AiBotMap.MarkZoneForFortification(iPlateauOrZero, iLandOrWaterZone, oBrain.AiBotTeam)
                                    if bDebugMessages == true then
                                        LOG(sFunctionRef..': Have flagged zone to be fortified, iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iCaptureZone='..(iCaptureZone or 'nil'))
                                    end

                                end
                                break
                            end
                        end
                        --Aeon M6 - fortify the black sun control centre
                    elseif toCapturedUnits[1].UnitId == 'uec1902' and oCapturingBrain.AiBotAI and not(oCapturingBrain.HostileCampaignAI) and oCapturingBrain:GetFactionIndex() == AiBotUnitInfo.refFactionAeon then
                        local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(toCapturedUnits[1]:GetPosition(), true, oCapturingBrain.AiBotTeam)
                        if bDebugMessages == true then LOG(sFunctionRef..': Fortify zone being set for the black sun control centre') end
                        if tLZOrWZTeamData then
                            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(toCapturedUnits[1]:GetPosition())
                            AiBotMap.MarkZoneForFortification(iPlateauOrZero, iLandOrWaterZone, oCapturingBrain.AiBotTeam)
                        end
                    end

                end
            elseif not(bCaptured) then
                if AiBotUtilities.IsTableEmpty(toCapturedUnits) == false then
                    ForkThread(DelayedUnpauseOfTransferredUnits, toCapturedUnits, iArmyIndex)
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function ScenarioPlatoonCreated(oPlatoon, strArmy, strGroup, formation, tblNode, platoon, balance)
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'ScenarioPlatoonCreated'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if bDebugMessages == true then LOG(sFunctionRef..': Scenario platoon created') end
        local tPlatoonUnits = oPlatoon:GetPlatoonUnits()

        if AiBotUtilities.IsTableEmpty(tPlatoonUnits) == false then
            for iUnit, oUnit in tPlatoonUnits do
                if AiBotUnitInfo.IsUnitValid(oUnit) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Calling onCreate for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                    OnCreate(oUnit)
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnTeleportComplete(self, teleporter, location, orientation)
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'OnTeleportComplete'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        self[AiBotUnitInfo.reftActiveTeleportLocation] = nil
        --if bDebugMessages == true then LOG('OnTeleportComplete - self='..reprs(self)..'; teleporter='..reprs(teleporter)..'; location='..reprs(location)) end
        if self:GetAIBrain().AiBotAI and self[AiBotACU.refbACUHasTeleport] then
            --If we arent in a core base then teleport back
            local iTeam = self:GetAIBrain().AiBotTeam
            local tCurLZData, tCurLZTeamData = AiBotMap.GetLandOrWaterZoneData(self:GetPosition(), true, iTeam)
            if bDebugMessages == true then LOG(sFunctionRef..': tCurLZTeamData[AiBotMap.subrefLZbCoreBase]='..tostring(tCurLZTeamData[AiBotMap.subrefLZbCoreBase] or false)) end
            if not(tCurLZTeamData[AiBotMap.subrefLZbCoreBase]) then
                local tLocationToTeleportTo
                if AiBotUtilities.IsTableEmpty(self[AiBotUnitInfo.reftLastLocationWhenGaveTeleportOrder]) == false then
                    local tPrevLZData, tPrevLZTeamData = AiBotMap.GetLandOrWaterZoneData(self[AiBotUnitInfo.reftLastLocationWhenGaveTeleportOrder], true, iTeam)
                    if tPrevLZTeamData[AiBotMap.subrefLZbCoreBase] then
                        tLocationToTeleportTo = {self[AiBotUnitInfo.reftLastLocationWhenGaveTeleportOrder][1], self[AiBotUnitInfo.reftLastLocationWhenGaveTeleportOrder][2], self[AiBotUnitInfo.reftLastLocationWhenGaveTeleportOrder][3]}
                    end
                end
                if not(tLocationToTeleportTo) then
                    tLocationToTeleportTo = {tCurLZTeamData[AiBotMap.reftClosestFriendlyBase][1], tCurLZTeamData[AiBotMap.reftClosestFriendlyBase][2], tCurLZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Will teleport back to '..repru(tLocationToTeleportTo)) end
                --Add to existing queue due to issue where this callback can take place even though the ACU hasn't compelted its teleport
                if AiBotUtilities.GetDistanceBetweenPositions(self:GetPosition(), tLocationToTeleportTo) >= 50 then
                    --Check we are relatively near the last location we were trying to teleport to
                    if AiBotUtilities.IsTableEmpty(self[AiBotUnitInfo.reftLastLocationWhenGaveTeleportOrder]) == false and AiBotUtilities.GetDistanceBetweenPositions(self[AiBotUnitInfo.reftLastLocationWhenGaveTeleportOrder], self:GetPosition()) <= 100 then
                        AiBotOrders.IssueTrackedTeleport(self, tLocationToTeleportTo, 5, true, 'TelRet', true)
                    end
                end
            end
        end

        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnStartTeleport(self, teleporter, locationorbp, orientationorlocation,  teledistance, teleRange, LOUDorientation, telecostpaid)
    --FAF function(self, teleporter, location, orientation)
    --LOUD function(self, teleporter, bp, location, teledistance, teleRange, orientation, telecostpaid)
    if AiBotUtilities.bAiBotAIInGame then
        local sFunctionRef = 'OnStartTeleport'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        local location
        if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then location = orientationorlocation
        else location = locationorbp
        end

        if AiBotUnitInfo.IsUnitValid(self) then
            local iTeleportTeam = self:GetAIBrain().AiBotTeam
            self[AiBotUnitInfo.reftActiveTeleportLocation] = {location[1], location[2], location[3]}
            if bDebugMessages == true then LOG(sFunctionRef..': Teleport attempt detected by unit '..self.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(self)..'; location='..repru(location)..'; brain owner='..self:GetAIBrain().Nickname) end
            for iCurTeam = 1, AiBotTeam.iTotalTeamCount do
                if not(iCurTeam == iTeleportTeam) and AiBotTeam.tTeamData[iCurTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                    if not(AiBotTeam.tTeamData[iCurTeam][AiBotTeam.reftRecentEnemyTeleportDetails]) then
                        AiBotTeam.tTeamData[iCurTeam][AiBotTeam.reftRecentEnemyTeleportDetails] = {}
                    end
                    table.insert(AiBotTeam.tTeamData[iCurTeam][AiBotTeam.reftRecentEnemyTeleportDetails], {[AiBotTeam.subrefoTeleportUnit] = self, [AiBotTeam.subreftTeleportTarget] = {location[1], math.max(location[2], GetTerrainHeight(location[1], location[3])), location[3]}, [AiBotTeam.subrefiTeleportTime] = GetGameTimeSeconds()})
                    AiBotTeam.tTeamData[iCurTeam][AiBotTeam.refbEnemyHasTeleport] = true
                    ForkThread(AiBotBuilding.GEMobileShieldTeleDefence, self, location, iCurTeam)
                end
            end
        end

        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function OnGameStart()
    --Called vai hook of simInit
    if import('/lua/AiBot/AiBotConfig.lua').AiBotRunSimpleProfiling then
        ForkThread(AiBotProfiler.SimpleProfiler, 10)
    end

    --Check if we have AiBot in game at this stage (in addition to setting this to true whenever an AiBot brain is created):
    if not(AiBotUtilities.bAiBotAIInGame) then
        if AiBotUtilities.IsTableEmpty(ScenarioInfo.ArmySetup) == false then
            for sEntry, tData in ScenarioInfo.ArmySetup do
                --LOG('Considering sEntry='..sEntry..'; tData.AIPersonality='..(tData.AIPersonality or 'nil'))
                if tData.AIPersonality and string.find(tData.AIPersonality, 'aibot') then
                    AiBotUtilities.bAiBotAIInGame = true
                    --LOG('AiBot in game 2')
                    break
                end
            end
        end
        --[aiBrain.Name].AIPersonality
    end

    if AiBotConfig.AiBotRunGamePerformanceCheck then
        ForkThread(AiBotProfiler.LogGamePerformanceData)
    end
    ForkThread(AiBotOverseer.DelayedArmyChangeForPings)
end

