end

function ShieldDisabled(oUnit)
    --LOUD specific - used becuase LOUD doesnt have FAF code for shield.enabled
    oUnit[AiBotUnitInfo.refbShieldDown] = true
end
function ShieldEnabled(oUnit)
    --LOUD specific - used becuase LOUD doesnt have FAF code for shield.enabled
