function PingCreated(data)
    local sFunctionRef = 'PingCreated'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG('Ping created, reprs='..reprs(data)..'; Is this a marker='..tostring(data.Type == 'Marker')) end
    local bEngiMarkerPing = false
    local bSMDPing = false
    --Check for marker ping and get the message and brain creator
    local iIndex = data.Owner + 1
    local aiBrain
    for iBrain, oBrain in ArmyBrains do
        if iBrain == iIndex then
            if not(oBrain.AiBotIsDefeated) and not(oBrain:IsDefeated()) then
                aiBrain = oBrain
            end
            break
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Brain creating ping='..(aiBrain.Nickname or 'nil')..' on team '..(aiBrain.AiBotTeam or 'nil')..'; Is table of friendly active brains empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam or 1][AiBotTeam.subreftoFriendlyActiveAiBotBrains]))) end
    if aiBrain and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
        local iTeam = aiBrain.AiBotTeam
        local iTimeSinceLastRequest = GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeSinceLastEngiRequest] or 0)
        local oFirstAiBotBrain
        local oFirstAnyBrain
        for iBrain, oBrain in AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            if oBrain.AiBotAI then
                if not(oFirstAnyBrain) then oFirstAnyBrain = oBrain end
                if not(oBrain.BrainType == 'Human') then
                    oFirstAiBotBrain = oBrain
                    break
                end
            end
        end
        if data.Type == 'Marker' or data.Type == 'marker' then --(QUIET is lowercase marker)
            local oBrainForMessage = oFirstAiBotBrain or oFirstAnyBrain
            if bDebugMessages == true then LOG(sFunctionRef..': oBrainForMessage='..(oBrainForMessage.Nickname or 'nil')..'; iTimeSinceLastRequest='..iTimeSinceLastRequest) end
            if oBrainForMessage then
                local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(data.Location, true, aiBrain.AiBotTeam)
                if bDebugMessages == true then
                    local iPlateau, iZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(data.Location)
                    LOG(sFunctionRef..': Is tLZOrWZTeamData nil='..tostring(tLZOrWZTeamData == nil)..'; iPlateau='..(iPlateau or 'nil')..'; iZone='..(iZone or 'nil'))
                end
                if tLZOrWZTeamData then
                    --Check if the message contains "Engi"
                    if bDebugMessages == true then LOG(sFunctionRef..': string.lower of the text='..string.lower(data.Name)..'; Does this contain engi='..(string.find(string.lower(data.Name), 'engi') or 'nil')..'; Does this contain desired SMD refs='..tostring(string.find(string.lower(data.Name), 'smd', 1, true) and (string.find(string.lower(data.Name), 'get', 1, true) or string.find(string.lower(data.Name), 'build', 1, true) or string.find(string.lower(data.Name), 'need', 1, true) or string.lower(data.Name) == 'smd'))) end
                    if string.find(string.lower(data.Name), 'engi', 1, true) then
                        bEngiMarkerPing = true
                        if iTimeSinceLastRequest < 60 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Too soon since last valid request') end
                            if tLZOrWZTeamData[AiBotMap.subrefoBrainWantingEngi] == aiBrain then
                                AiBotChat.SendMessage(oBrainForMessage, 'EngiDenied', 'Yes yes I know, just be patient and I\'ll give you one when I can.', 1, 2, true, false, nil, nil, nil)
                            else
                                AiBotChat.SendMessage(oBrainForMessage, 'EngiDenied', 'You\'ll just have to wait and ask me again in '..math.floor(60-iTimeSinceLastRequest)..' seconds.', 1, 2, true, false, nil, nil, nil)
                            end
                        else
                            --Check we have engineers in this zone
                            local bHaveEngineersInZone = false
                            local tEngineers
                            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                tEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                if AiBotUtilities.IsTableEmpty(tEngineers) == false then
                                    bHaveEngineersInZone = true
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': bHaveEngineersInZone='..tostring(bHaveEngineersInZone or false)) end
                            if bHaveEngineersInZone then
                                tLZOrWZTeamData[AiBotMap.subrefoBrainWantingEngi] = aiBrain
                                AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeSinceLastEngiRequest] = GetGameTimeSeconds()
                                if not(ArmyBrains[ tLZOrWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].BrainType == 'Human') then oBrainForMessage = ArmyBrains[ tLZOrWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]] end
                                -- AiBotChat.SendMessage(oBrainForMessage, 'EngiReqQ', 'I\'ll send you an engineer when I can', 3, 5, true, false, nil, nil, nil) --dont other with this, as its a fairly high priority
                                if bDebugMessages == true then LOG(sFunctionRef..': recording that we want to give an engineer to '..aiBrain.Nickname) end
                            else
                                AiBotChat.SendMessage(oBrainForMessage, 'EngiUnav', 'I don\'t have any nearby engineers, ask again when I do', 1, 5, true, false, nil, nil, nil)
                            end
                        end
                        --Does it contain SMD and either build, need, or get?
                    elseif string.find(string.lower(data.Name), 'smd', 1, true) and (string.find(string.lower(data.Name), 'get', 1, true) or string.find(string.lower(data.Name), 'build', 1, true) or string.find(string.lower(data.Name), 'need', 1, true) or string.lower(data.Name) == 'smd') then
                        bSMDPing = true
                        local iTeam = aiBrain.AiBotTeam
                        if bDebugMessages == true then LOG(sFunctionRef..': Have an SMD ping, subrefiActiveAiBotBrainCount='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) end
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                            --Check we have friendly units in this zone or nearby (if helpful teammates is disabled or it is not a core base/one with significant s value, then require these to be AiBot units)
                            local iNearbyFriendlyMass = 0
                            local tNearbyFriendlyUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryStructure, data.Location, 120, 'Ally') --SMD typical range is 90, doing 120 to give allowance for placing it in the path of a nuke
                            if AiBotUtilities.IsTableEmpty(tNearbyFriendlyUnits) == false then
                                if ScenarioInfo.Options.AiBotTeammate == 1 and (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or tLZOrWZTeamData[AiBotMap.subrefLZSValue] >= 3000) then
                                    iNearbyFriendlyMass = AiBotUnitInfo.GetMassCostOfUnits(tNearbyFriendlyUnits, false)
                                else
                                    for iUnit, oUnit in tNearbyFriendlyUnits do
                                        if oUnit:GetAIBrain().AiBotAI and (AiBotOrders.bDontConsiderCombinedArmy or oUnit.AiBotActive) then
                                            iNearbyFriendlyMass = iNearbyFriendlyMass + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Deciding if should flag to build SMD, iNearbyFriendlyMass='..iNearbyFriendlyMass) end
                            if iNearbyFriendlyMass >= 5000 then
                                tLZOrWZTeamData[AiBotMap.refiTimeOfLastSMDPrioritisationRequest] = GetGameTimeSeconds()
                            else
                                --If enemy has SMD near the ping then dont send any message
                                local rRectangleToSearch = AiBotUtilities.GetRectAroundLocation(data.Location, 20)
                                local tUnitsInRect = GetUnitsInRect(rRectangleToSearch)
                                local bEnemySMD = false
                                if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
                                    local tSMD = EntityCategoryFilterDown(AiBotUnitInfo.refCategorySMD, tUnitsInRect)
                                    if AiBotUtilities.IsTableEmpty(tSMD) == false then
                                        for iSMD, oSMD in tSMD do
                                            if IsEnemy(oSMD:GetAIBrain():GetArmyIndex(), aiBrain:GetArmyIndex()) then
                                                bEnemySMD = true
                                                break
                                            end
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Dont want to build SMD due to lack of friendly units, bEnemySMD='..tostring(bEnemySMD)) end
                                if bEnemySMD then
                                    --Ignore/do nothing
                                elseif ScenarioInfo.Options.AiBotTeammate == 1 then
                                    --SendMessage(      aiBrain,         sMessageType, sMessage,                                    iOptionalDelayBeforeSending, iOptionalTimeBetweenMessageType, bOnlySendToTeam, bWaitUntilHaveACU, sOptionalSoundCue, sOptionalSoundBank, oOptionalOnlyBrainToSendTo)
                                    AiBotChat.SendMessage(oBrainForMessage, 'SMDDenied', 'There aren\'t enough friendly units near there for me to justify building an SMD', 1,       2,                              true,           false, nil, nil, nil)
                                else
                                    AiBotChat.SendMessage(oBrainForMessage, 'SMDDenied', 'I don\'t have enough units near there to justify building an SMD', 1,       2,                              true,           false, nil, nil, nil)
                                end
                            end
                        end
                    end
                end
            end
        end
        if not(bEngiMarkerPing) and not(bSMDPing) then
            if oFirstAiBotBrain then
                AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiGeneralPingsInLast30Seconds] = (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiGeneralPingsInLast30Seconds] or 0) + 1
                AiBotUtilities.DelayChangeVariable(AiBotTeam.tTeamData[aiBrain.AiBotTeam], AiBotTeam.refiGeneralPingsInLast30Seconds, -1, 30, nil, nil, nil, nil, true)
                if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiGeneralPingsInLast30Seconds] >= 4 then
                    AiBotChat.SendMessageAboutTooManyPings(aiBrain.AiBotTeam)
                end
            end
        end
    end
end

function OnImpactTerrain(oProjectile, targetType, targetEntity, tProjectilePosition, tTargetPosition)
    local oLauncher = oProjectile.Launcher
    if not( IsDestroyed(oLauncher)) then
        --T2 arti logic to register shot is blocked
        if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oLauncher.UnitId) then
            local sFunctionRef = 'OnImpactTerrain'
            local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

            --Is our shot far from our target?
            local tLastOrder = oLauncher[AiBotOrders.reftiLastOrders][1] --Since we add a delay on t2 arti before giving it a new order (with onweaponfired) hopefully this will be accurate
            if bDebugMessages == true then LOG(sFunctionRef..': subrefoOrderUnitTarget='..(tLastOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) or 'nil')) end
            if tLastOrder[AiBotOrders.subrefoOrderUnitTarget] and AiBotUnitInfo.IsUnitValid(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) then
                --Did we impact terrain significantly higher up than our arti?
                if bDebugMessages == true then LOG(sFunctionRef..': tProjectilePosition='..repru(tProjectilePosition)..'; tTargetPosition='..repru(tTargetPosition)..'; oLauncher:GetPosition()='..repru(oLauncher:GetPosition())) end
                if tProjectilePosition[2] > oLauncher:GetPosition()[2] + 1 then
                    --Did we hit terrain far from this target?

                    --[[if tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack then tTargetPosition = tLastOrder[AiBotOrders.subrefoOrderUnitTarget]:GetPosition()
                    else tTargetPosition = (tLastOrder[AiBotOrders.subreftOrderPosition] or tLastOrder[AiBotOrders.subrefoOrderUnitTarget]:GetPosition())
                    end--]]
                    local iDistToTargetFromProjectile = AiBotUtilities.GetDistanceBetweenPositions(tProjectilePosition, tTargetPosition)
                    if bDebugMessages == true then LOG(sFunctionRef..': iDistToTargetFromProjectile='..iDistToTargetFromProjectile) end
                    if iDistToTargetFromProjectile >= 30 then
                        --Did we impact on the way to the target from the launcher?
                        local iDistToLauncherFromProjectile = AiBotUtilities.GetDistanceBetweenPositions(tProjectilePosition, oLauncher:GetPosition())
                        local iDistToLauncherFromTarget = AiBotUtilities.GetDistanceBetweenPositions(tTargetPosition, oLauncher:GetPosition())
                        if bDebugMessages == true then LOG(sFunctionRef..': iDistToLauncherFromProjectile='..iDistToLauncherFromProjectile..'; iDistToLauncherFromTarget='..iDistToLauncherFromTarget..'; Is shot blocked='..tostring(AiBotLogic.IsShotBlocked(oLauncher, tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) or false)) end
                        if iDistToLauncherFromProjectile < iDistToLauncherFromTarget - 5 then
                            --If we fired a directfire shot would it be blocked?
                            if AiBotLogic.IsShotBlocked(oLauncher, tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) then
                                --Shot is blocked
                                local iTargetSegmentX, iTargetSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tTargetPosition)
                                if not(oLauncher[AiBotBuilding.reftbTerrainBlockedTargetsBySegment]) then oLauncher[AiBotBuilding.reftbTerrainBlockedTargetsBySegment] = {} end
                                if not(oLauncher[AiBotBuilding.reftbTerrainBlockedTargetsBySegment][iTargetSegmentX]) then oLauncher[AiBotBuilding.reftbTerrainBlockedTargetsBySegment][iTargetSegmentX] = {} end
                                oLauncher[AiBotBuilding.reftbTerrainBlockedTargetsBySegment][iTargetSegmentX][iTargetSegmentZ] = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Recording shots blocked for iTargetSegmentX='..iTargetSegmentX..'Z='..iTargetSegmentZ) end
                            end
                        end
                    end
                end
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        end
    end
end

function MissileReflected(oTarget, oAttacker)
    if AiBotUnitInfo.IsUnitValid(oTarget) and oTarget:GetAIBrain().AiBotAI and (AiBotOrders.bDontConsiderCombinedArmy or oTarget.AiBotActive) then
        ForkThread(AiBotMicro.DodgeShot,oTarget, nil, oAttacker, 3)
    end
end

function OnPlayerChatMessageSent(data)
    local sFunctionRef = 'OnPlayerChatMessageSent'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': data='..reprs(data)) end
    if data.Sender and data.Msg and data.Msg.Chat and data.Msg.text then
        local tsToxicSearchStrings = {'stfu', 'fuck you', 'kys', 'retard', 'clanker'}
        local tbDirectedAtPerson = {true, true, true, false, false}
        local bToxicMessageSent = false
        local bMessageTargetingPerson = false
        for iMessage, sToxicMessage in tsToxicSearchStrings do
            if string.find(string.lower(data.Msg.text), sToxicMessage, 1, true) then
                if bDebugMessages == true then LOG(sFunctionRef..': Toxic message detected when searching sToxicMessage='..sToxicMessage) end
                bToxicMessageSent = true
                bMessageTargetingPerson = tbDirectedAtPerson[iMessage]
                break
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bToxicMessageSent='..tostring(bToxicMessageSent)) end
        if bToxicMessageSent then
            --Find AiBot player to tell the sender off
            for iBrain, oBrain in ArmyBrains do
                if oBrain.AiBotAI and oBrain.BrainType == 'AI' and not(oBrain.AiBotIsDefeated) then
                    AiBotChat.SendMessageAboutToxicChat(oBrain, bMessageTargetingPerson)
                    break
                end
            end
            --Did enemy team send a polite start of game message?
        elseif GetGameTimeSeconds() <= 180 and data.Sender and data.Msg.to == 'all' then
            --Consider responding to early game messages
            local tsNiceGreetings = {'gl hf', 'glhf', 'good luck', 'have fun'}
            for iMessage, sMessage in tsNiceGreetings do
                if string.find(string.lower(data.Msg.text), sMessage, 1, true) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Friendly message detected when searching sMessage='..sMessage) end
                    --Find an AiBot brain on the opposite team to the sender
                    local iOriginatorTeam, oOriginatorBrain
                    for iBrain, oBrain in ArmyBrains do
                        if oBrain.Nickname == data.Sender then
                            iOriginatorTeam = oBrain.AiBotTeam
                            oOriginatorBrain = oBrain
                            break
                        end
                    end
                    local oBrainToSendMessage
                    for iTeam = 1, AiBotTeam.iTotalTeamCount do
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 then
                            if IsEnemy(oOriginatorBrain:GetArmyIndex(), AiBotTeam.GetFirstActiveAiBotBrain(iTeam):GetArmyIndex()) then
                                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                    if oBrain.AiBotAI and oBrain.BrainType == 'AI' then
                                        oBrainToSendMessage = oBrain
                                        break
                                    end
                                end
                                if oBrainToSendMessage then break end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': oBrainToSendMessage='..(oBrainToSendMessage.Nickname or 'nil')) end
                    if oBrainToSendMessage then
                        local tsPotentialmessages = {'thanks, you too', 'thx, u2', 'u2'}
                        local iRand = math.random(1, table.getn(tsPotentialmessages))
                        if bDebugMessages == true then LOG(sFunctionRef..': Will send start of game message, iRand='..iRand..'; tsPotentialmessages[iRand]='..(tsPotentialmessages[iRand] or 'nil')) end
                        --SendStartOfGameMessage(oOrigBrain, iOptionalExtraDelayInSeconds, sOptionalMessageTypePrefix, iOptionalBaseDelayOverride, sOptionalMessageOverride)
                        AiBotChat.SendStartOfGameMessage(oBrainToSendMessage, 0.1,                            nil,                     1, tsPotentialmessages[iRand])
                    end
                    break
                end
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end
